import { CreateCategoryUseCase } from '../CreateCategoryUseCase';
import { CategoryRepository } from '../../../../Domains/categories/CategoryRepository';
import { ProductCategory } from '../../../../Domains/categories/entities/ProductCategory';
import { ProductGroupRepository } from '../../../../Domains/product-groups/ProductGroupRepository';
import { ProductGroup } from '../../../../Domains/product-groups/entities/ProductGroup';

const mockCategoryRepo: jest.Mocked<CategoryRepository> = {
  addCategory: jest.fn(),
  generateCategoryCode: jest.fn(),
  getCategoriesByCompany: jest.fn(),
  getCategoryById: jest.fn(),
  updateCategory: jest.fn(),
  softDeleteCategory: jest.fn(),
  countActiveDependents: jest.fn(),
} as unknown as jest.Mocked<CategoryRepository>;

const mockProductGroupRepo: jest.Mocked<ProductGroupRepository> = {
  getProductGroupById: jest.fn(),
} as unknown as jest.Mocked<ProductGroupRepository>;

const companyId = 'company-uuid';
const productGroupId = 'pg-uuid';

const activeGroup = new ProductGroup({
  id: productGroupId,
  companyId,
  code: 'PG-001',
  name: 'Bakery',
  description: null,
  isActive: true,
  createdAt: new Date(),
  updatedAt: new Date(),
});

const created = new ProductCategory({
  id: 'cat-uuid',
  companyId,
  productGroupId,
  code: 'PC-001',
  name: 'Roti Manis',
  description: null,
  isActive: true,
  createdAt: new Date(),
  updatedAt: new Date(),
});

describe('CreateCategoryUseCase', () => {
  let useCase: CreateCategoryUseCase;

  beforeEach(() => {
    jest.clearAllMocks();
    useCase = new CreateCategoryUseCase(mockCategoryRepo, mockProductGroupRepo);
    mockProductGroupRepo.getProductGroupById.mockResolvedValue(activeGroup);
    mockCategoryRepo.generateCategoryCode.mockResolvedValue('PC-001');
    mockCategoryRepo.addCategory.mockResolvedValue(created);
  });

  it('should validate the group, generate a code, and persist the category', async () => {
    const result = await useCase.execute(
      { productGroupId, name: 'Roti Manis' },
      companyId,
    );

    expect(mockProductGroupRepo.getProductGroupById).toHaveBeenCalledWith(
      productGroupId,
      companyId,
    );
    expect(mockCategoryRepo.generateCategoryCode).toHaveBeenCalledWith(companyId);
    expect(mockCategoryRepo.addCategory).toHaveBeenCalledWith(
      { code: 'PC-001', name: 'Roti Manis', description: null, productGroupId },
      companyId,
    );
    expect(result.code).toBe('PC-001');
  });

  it('should pass through trimmed description', async () => {
    await useCase.execute(
      { productGroupId, name: 'Roti', description: '  Kategori  ' },
      companyId,
    );
    expect(mockCategoryRepo.addCategory).toHaveBeenCalledWith(
      { code: 'PC-001', name: 'Roti', description: 'Kategori', productGroupId },
      companyId,
    );
  });

  it('should throw when the product group is inactive', async () => {
    mockProductGroupRepo.getProductGroupById.mockResolvedValue({
      ...activeGroup,
      isActive: false,
    } as ProductGroup);

    await expect(
      useCase.execute({ productGroupId, name: 'Roti' }, companyId),
    ).rejects.toThrow('CREATE_CATEGORY.PRODUCT_GROUP_INACTIVE');
    expect(mockCategoryRepo.addCategory).not.toHaveBeenCalled();
  });

  it('should propagate NOT_FOUND when the group is missing or foreign', async () => {
    mockProductGroupRepo.getProductGroupById.mockRejectedValue(
      new Error('PRODUCT_GROUP.NOT_FOUND'),
    );

    await expect(
      useCase.execute({ productGroupId, name: 'Roti' }, companyId),
    ).rejects.toThrow('PRODUCT_GROUP.NOT_FOUND');
    expect(mockCategoryRepo.addCategory).not.toHaveBeenCalled();
  });

  it('should throw when payload is invalid', async () => {
    await expect(useCase.execute({ productGroupId, name: '' }, companyId)).rejects.toThrow(
      'CREATE_CATEGORY.NOT_CONTAIN_NEEDED_PROPERTY',
    );
    expect(mockCategoryRepo.addCategory).not.toHaveBeenCalled();
  });
});

import { RegisterCompanyUseCase } from '../RegisterCompanyUseCase';
import { CompanyRepository } from '../../../../Domains/companies/CompanyRepository';
import { UserRepository } from '../../../../Domains/users/UserRepository';
import { RoleRepository } from '../../../../Domains/roles/RoleRepository';
import { PasswordHash } from '../../../security/PasswordHash';
import { RegisteredCompany } from '../../../../Domains/companies/entities/RegisteredCompany';
import { RegisteredUser } from '../../../../Domains/users/entities/RegisteredUser';

// ─── Mocks ───────────────────────────────────────────────────────────────────

const mockCompanyRepository: jest.Mocked<CompanyRepository> = {
  addCompany: jest.fn(),
  verifyAvailableSlug: jest.fn(),
  getCompanyById: jest.fn(),
  generateCompanyCode: jest.fn(),
} as unknown as jest.Mocked<CompanyRepository>;

const mockUserRepository: jest.Mocked<UserRepository> = {
  addUser: jest.fn(),
  verifyAvailableEmail: jest.fn(),
  getPasswordByEmail: jest.fn(),
  getUserWithPermissionsByEmail: jest.fn(),
  getUserWithPermissionsById: jest.fn(),
  getUserById: jest.fn(),
} as unknown as jest.Mocked<UserRepository>;

const mockRoleRepository: jest.Mocked<RoleRepository> = {
  addRole: jest.fn(),
  getRoleById: jest.fn(),
  getRoleByCode: jest.fn(),
  assignPermissionsToRole: jest.fn(),
  assignAllPermissionsToRole: jest.fn(),
  getRolesByCompanyId: jest.fn(),
} as unknown as jest.Mocked<RoleRepository>;

const mockPasswordHash: jest.Mocked<PasswordHash> = {
  hash: jest.fn(),
  comparePassword: jest.fn(),
} as unknown as jest.Mocked<PasswordHash>;

// ─── Fixtures ────────────────────────────────────────────────────────────────

const validPayload = {
  name: 'Toko Roti Makmur',
  slug: 'toko-roti-makmur',
  ownerName: 'Budi Santoso',
  ownerEmail: 'budi@rotimakmur.com',
  ownerPassword: 'Secret1234',
};

// ─── Tests ───────────────────────────────────────────────────────────────────

describe('RegisterCompanyUseCase', () => {
  let useCase: RegisterCompanyUseCase;

  beforeEach(() => {
    jest.clearAllMocks();

    useCase = new RegisterCompanyUseCase(
      mockCompanyRepository,
      mockUserRepository,
      mockRoleRepository,
      mockPasswordHash,
    );

    // Default happy-path stubs
    mockCompanyRepository.verifyAvailableSlug.mockResolvedValue(undefined);
    mockUserRepository.verifyAvailableEmail.mockResolvedValue(undefined);
    mockCompanyRepository.generateCompanyCode.mockResolvedValue('COMP-001');
    mockCompanyRepository.addCompany.mockResolvedValue(
      new RegisteredCompany({
        id: 'company-uuid',
        code: 'COMP-001',
        name: 'Toko Roti Makmur',
        slug: 'toko-roti-makmur',
      }),
    );
    mockRoleRepository.addRole.mockResolvedValue('role-uuid');
    mockRoleRepository.assignAllPermissionsToRole.mockResolvedValue(undefined);
    mockRoleRepository.assignPermissionsToRole.mockResolvedValue(undefined);
    mockPasswordHash.hash.mockResolvedValue('hashed_password');
    mockUserRepository.addUser.mockResolvedValue(
      new RegisteredUser({
        id: 'user-uuid',
        name: 'Budi Santoso',
        email: 'budi@rotimakmur.com',
      }),
    );
  });

  it('should register company and return company + owner data', async () => {
    const result = await useCase.execute(validPayload);

    expect(result.company.id).toBe('company-uuid');
    expect(result.company.code).toBe('COMP-001');
    expect(result.company.name).toBe('Toko Roti Makmur');
    expect(result.owner.email).toBe('budi@rotimakmur.com');
  });

  it('should call verifyAvailableSlug with normalised slug', async () => {
    await useCase.execute(validPayload);

    expect(mockCompanyRepository.verifyAvailableSlug).toHaveBeenCalledWith(
      'toko-roti-makmur',
    );
  });

  it('should call verifyAvailableEmail with normalised email', async () => {
    await useCase.execute(validPayload);

    expect(mockUserRepository.verifyAvailableEmail).toHaveBeenCalledWith(
      'budi@rotimakmur.com',
    );
  });

  it('should call generateCompanyCode once', async () => {
    await useCase.execute(validPayload);

    expect(mockCompanyRepository.generateCompanyCode).toHaveBeenCalledTimes(1);
  });

  it('should seed all 5 default roles for the new company', async () => {
    await useCase.execute(validPayload);

    // DEFAULT_ROLES has 5 entries
    expect(mockRoleRepository.addRole).toHaveBeenCalledTimes(5);
  });

  it('should call assignAllPermissionsToRole for OWNER role', async () => {
    await useCase.execute(validPayload);

    expect(mockRoleRepository.assignAllPermissionsToRole).toHaveBeenCalledTimes(1);
  });

  it('should call assignPermissionsToRole for non-OWNER roles', async () => {
    await useCase.execute(validPayload);

    // 4 non-OWNER roles
    expect(mockRoleRepository.assignPermissionsToRole).toHaveBeenCalledTimes(4);
  });

  it('should hash the owner password before persisting', async () => {
    await useCase.execute(validPayload);

    expect(mockPasswordHash.hash).toHaveBeenCalledWith('Secret1234');
    expect(mockUserRepository.addUser).toHaveBeenCalledWith(
      expect.objectContaining({ password: 'hashed_password' }),
      'company-uuid',
      'role-uuid', // OWNER role id
    );
  });

  it('should throw when slug is already taken', async () => {
    mockCompanyRepository.verifyAvailableSlug.mockRejectedValue(
      new Error('COMPANY.SLUG_ALREADY_USED'),
    );

    await expect(useCase.execute(validPayload)).rejects.toThrow(
      'COMPANY.SLUG_ALREADY_USED',
    );
  });

  it('should throw when owner email is already used', async () => {
    mockUserRepository.verifyAvailableEmail.mockRejectedValue(
      new Error('USER.EMAIL_ALREADY_USED'),
    );

    await expect(useCase.execute(validPayload)).rejects.toThrow(
      'USER.EMAIL_ALREADY_USED',
    );
  });

  it('should throw when payload is invalid (domain entity validation)', async () => {
    await expect(useCase.execute({ ...validPayload, slug: 'Invalid Slug!' })).rejects.toThrow(
      'REGISTER_COMPANY.SLUG_CONTAIN_RESTRICTED_CHARACTER',
    );
  });
});

import { UploadGoodsReceiptAttachmentUseCase } from '../UploadGoodsReceiptAttachmentUseCase';
import { ListGoodsReceiptAttachmentsUseCase } from '../ListGoodsReceiptAttachmentsUseCase';
import { GetGoodsReceiptAttachmentUseCase } from '../GetGoodsReceiptAttachmentUseCase';
import { DeleteGoodsReceiptAttachmentUseCase } from '../DeleteGoodsReceiptAttachmentUseCase';
import { UploadGoodsReceiptAttachment } from '../../../../Domains/goods-receipts/entities/UploadGoodsReceiptAttachment';
import { GoodsReceiptRepository } from '../../../../Domains/goods-receipts/GoodsReceiptRepository';
import { GoodsReceiptAttachmentStorage } from '../../../../Domains/goods-receipts/GoodsReceiptAttachmentStorage';
import { MAX_ATTACHMENT_SIZE_BYTES } from '../../../../Domains/goods-receipts/goodsReceiptAttachmentPolicy';

const grRepo: jest.Mocked<GoodsReceiptRepository> = {
  createDraft: jest.fn(),
  updateDraft: jest.fn(),
  getById: jest.fn(),
  list: jest.fn(),
  getConsumedQtyByPoItem: jest.fn(),
  cancel: jest.fn(),
  complete: jest.fn(),
  ensureExists: jest.fn(),
  addComment: jest.fn(),
  listComments: jest.fn(),
  addAttachment: jest.fn(),
  listAttachments: jest.fn(),
  getAttachmentById: jest.fn(),
  deleteAttachment: jest.fn(),
} as unknown as jest.Mocked<GoodsReceiptRepository>;

const storage: jest.Mocked<GoodsReceiptAttachmentStorage> = {
  save: jest.fn(),
  remove: jest.fn(),
  resolveAbsolutePath: jest.fn(),
  createReadStream: jest.fn(),
} as unknown as jest.Mocked<GoodsReceiptAttachmentStorage>;

beforeEach(() => jest.clearAllMocks());

const pdf = { originalName: 'delivery-note.pdf', mimeType: 'application/pdf', buffer: Buffer.from('%PDF-1.4 data') };

describe('UploadGoodsReceiptAttachment (domain validation)', () => {
  it('should accept a valid PDF and expose trimmed metadata', () => {
    const vo = new UploadGoodsReceiptAttachment({
      originalName: '  delivery-note.pdf  ',
      mimeType: 'application/pdf',
      buffer: Buffer.from('data'),
    });
    expect(vo.originalName).toBe('delivery-note.pdf');
    expect(vo.mimeType).toBe('application/pdf');
    expect(vo.sizeBytes).toBe(4);
  });

  it('should reject a missing/empty file', () => {
    expect(
      () =>
        new UploadGoodsReceiptAttachment({
          originalName: 'x.pdf',
          mimeType: 'application/pdf',
          buffer: Buffer.alloc(0),
        }),
    ).toThrow('UPLOAD_GOODS_RECEIPT_ATTACHMENT.FILE_REQUIRED');
  });

  it('should reject a disallowed MIME type', () => {
    expect(
      () =>
        new UploadGoodsReceiptAttachment({
          originalName: 'evil.exe',
          mimeType: 'application/x-msdownload',
          buffer: Buffer.from('MZ'),
        }),
    ).toThrow('UPLOAD_GOODS_RECEIPT_ATTACHMENT.MIME_NOT_ALLOWED');
  });

  it('should reject when the extension is inconsistent with the MIME type', () => {
    expect(
      () =>
        new UploadGoodsReceiptAttachment({
          originalName: 'sneaky.exe',
          mimeType: 'application/pdf',
          buffer: Buffer.from('data'),
        }),
    ).toThrow('UPLOAD_GOODS_RECEIPT_ATTACHMENT.MIME_NOT_ALLOWED');
  });

  it('should reject a file larger than 5 MB', () => {
    expect(
      () =>
        new UploadGoodsReceiptAttachment({
          originalName: 'big.png',
          mimeType: 'image/png',
          buffer: Buffer.alloc(MAX_ATTACHMENT_SIZE_BYTES + 1),
        }),
    ).toThrow('UPLOAD_GOODS_RECEIPT_ATTACHMENT.FILE_TOO_LARGE');
  });

  it('should accept a jpeg with .jpg extension', () => {
    const vo = new UploadGoodsReceiptAttachment({
      originalName: 'photo.jpg',
      mimeType: 'image/jpeg',
      buffer: Buffer.from('jpegdata'),
    });
    expect(vo.mimeType).toBe('image/jpeg');
  });
});

describe('UploadGoodsReceiptAttachmentUseCase', () => {
  it('should validate, verify tenant scope, store the file, then persist metadata', async () => {
    grRepo.getById.mockResolvedValue({ id: 'gr1', grNumber: 'GR-2026-000001' } as never);
    storage.save.mockResolvedValue({ storedPath: 'uploads/goods-receipt/2026/x.pdf' });
    grRepo.addAttachment.mockResolvedValue({
      id: 'att-1',
      originalName: 'delivery-note.pdf',
      mimeType: 'application/pdf',
      sizeBytes: pdf.buffer.length,
      uploadedBy: 'u1',
      uploadedByName: 'Budi',
      createdAt: new Date(),
    });

    const useCase = new UploadGoodsReceiptAttachmentUseCase(grRepo, storage);
    const result = await useCase.execute('gr1', pdf, 'c1', 'u1');

    expect(grRepo.getById).toHaveBeenCalledWith('gr1', 'c1');
    expect(storage.save).toHaveBeenCalledWith(
      'GR-2026-000001',
      'delivery-note.pdf',
      'application/pdf',
      pdf.buffer,
    );
    expect(grRepo.addAttachment).toHaveBeenCalledWith('gr1', 'c1', 'u1', {
      originalName: 'delivery-note.pdf',
      storedPath: 'uploads/goods-receipt/2026/x.pdf',
      mimeType: 'application/pdf',
      sizeBytes: pdf.buffer.length,
    });
    expect(result.id).toBe('att-1');
  });

  it('should reject an invalid file before any IO', async () => {
    const useCase = new UploadGoodsReceiptAttachmentUseCase(grRepo, storage);
    await expect(
      useCase.execute(
        'gr1',
        { originalName: 'x.exe', mimeType: 'application/octet-stream', buffer: Buffer.from('x') },
        'c1',
        'u1',
      ),
    ).rejects.toThrow('UPLOAD_GOODS_RECEIPT_ATTACHMENT.MIME_NOT_ALLOWED');
    expect(grRepo.getById).not.toHaveBeenCalled();
    expect(storage.save).not.toHaveBeenCalled();
  });

  it('should propagate GOODS_RECEIPT.NOT_FOUND for a foreign GR (no file written)', async () => {
    grRepo.getById.mockRejectedValue(new Error('GOODS_RECEIPT.NOT_FOUND'));
    const useCase = new UploadGoodsReceiptAttachmentUseCase(grRepo, storage);
    await expect(useCase.execute('gr1', pdf, 'c1', 'u1')).rejects.toThrow(
      'GOODS_RECEIPT.NOT_FOUND',
    );
    expect(storage.save).not.toHaveBeenCalled();
  });

  it('should remove the orphan file when the DB write fails', async () => {
    grRepo.getById.mockResolvedValue({ id: 'gr1', grNumber: 'GR-1' } as never);
    storage.save.mockResolvedValue({ storedPath: 'uploads/goods-receipt/2026/x.pdf' });
    grRepo.addAttachment.mockRejectedValue(new Error('DB down'));
    storage.remove.mockResolvedValue(undefined);

    const useCase = new UploadGoodsReceiptAttachmentUseCase(grRepo, storage);
    await expect(useCase.execute('gr1', pdf, 'c1', 'u1')).rejects.toThrow('DB down');
    expect(storage.remove).toHaveBeenCalledWith('uploads/goods-receipt/2026/x.pdf');
  });
});

describe('ListGoodsReceiptAttachmentsUseCase', () => {
  it('should verify tenant scope then list', async () => {
    grRepo.ensureExists.mockResolvedValue(undefined);
    grRepo.listAttachments.mockResolvedValue([]);

    await new ListGoodsReceiptAttachmentsUseCase(grRepo).execute('gr1', 'c1');

    expect(grRepo.ensureExists).toHaveBeenCalledWith('gr1', 'c1');
    expect(grRepo.listAttachments).toHaveBeenCalledWith('gr1', 'c1');
  });

  it('should propagate GOODS_RECEIPT.NOT_FOUND for a foreign GR', async () => {
    grRepo.ensureExists.mockRejectedValue(new Error('GOODS_RECEIPT.NOT_FOUND'));
    await expect(
      new ListGoodsReceiptAttachmentsUseCase(grRepo).execute('gr1', 'c1'),
    ).rejects.toThrow('GOODS_RECEIPT.NOT_FOUND');
    expect(grRepo.listAttachments).not.toHaveBeenCalled();
  });
});

describe('GetGoodsReceiptAttachmentUseCase', () => {
  it('should resolve metadata (GR + company scoped) and open a stream', async () => {
    const meta = {
      id: 'att-1',
      originalName: 'delivery-note.pdf',
      mimeType: 'application/pdf',
      sizeBytes: 10,
      uploadedBy: 'u1',
      uploadedByName: 'Budi',
      createdAt: new Date(),
      storedPath: 'uploads/goods-receipt/2026/x.pdf',
    };
    grRepo.getAttachmentById.mockResolvedValue(meta);
    const fakeStream = { pipe: jest.fn() } as unknown as NodeJS.ReadableStream;
    storage.createReadStream.mockReturnValue(fakeStream);

    const result = await new GetGoodsReceiptAttachmentUseCase(grRepo, storage).execute(
      'gr1',
      'att-1',
      'c1',
    );

    expect(grRepo.getAttachmentById).toHaveBeenCalledWith('gr1', 'att-1', 'c1');
    expect(storage.createReadStream).toHaveBeenCalledWith('uploads/goods-receipt/2026/x.pdf');
    expect(result.attachment).toBe(meta);
    expect(result.stream).toBe(fakeStream);
  });

  it('should propagate NOT_FOUND for a foreign attachment (IDOR guard)', async () => {
    grRepo.getAttachmentById.mockRejectedValue(
      new Error('GOODS_RECEIPT_ATTACHMENT.NOT_FOUND'),
    );
    await expect(
      new GetGoodsReceiptAttachmentUseCase(grRepo, storage).execute('gr1', 'att-1', 'c1'),
    ).rejects.toThrow('GOODS_RECEIPT_ATTACHMENT.NOT_FOUND');
    expect(storage.createReadStream).not.toHaveBeenCalled();
  });
});

describe('DeleteGoodsReceiptAttachmentUseCase', () => {
  it('should delete the row (GR + company scoped) then remove the physical file', async () => {
    grRepo.deleteAttachment.mockResolvedValue({
      id: 'att-1',
      originalName: 'delivery-note.pdf',
      mimeType: 'application/pdf',
      sizeBytes: 10,
      uploadedBy: 'u1',
      uploadedByName: null,
      createdAt: new Date(),
      storedPath: 'uploads/goods-receipt/2026/x.pdf',
    });
    storage.remove.mockResolvedValue(undefined);

    await new DeleteGoodsReceiptAttachmentUseCase(grRepo, storage).execute('gr1', 'att-1', 'c1');

    expect(grRepo.deleteAttachment).toHaveBeenCalledWith('gr1', 'att-1', 'c1');
    expect(storage.remove).toHaveBeenCalledWith('uploads/goods-receipt/2026/x.pdf');
  });

  it('should propagate NOT_FOUND without touching storage', async () => {
    grRepo.deleteAttachment.mockRejectedValue(
      new Error('GOODS_RECEIPT_ATTACHMENT.NOT_FOUND'),
    );
    await expect(
      new DeleteGoodsReceiptAttachmentUseCase(grRepo, storage).execute('gr1', 'att-1', 'c1'),
    ).rejects.toThrow('GOODS_RECEIPT_ATTACHMENT.NOT_FOUND');
    expect(storage.remove).not.toHaveBeenCalled();
  });
});

import { CreateGoodsReceiptUseCase } from '../CreateGoodsReceiptUseCase';
import { UpdateGoodsReceiptUseCase } from '../UpdateGoodsReceiptUseCase';
import { CancelGoodsReceiptUseCase } from '../CancelGoodsReceiptUseCase';
import { CompleteGoodsReceiptUseCase } from '../CompleteGoodsReceiptUseCase';
import { GetGoodsReceiptsUseCase } from '../GetGoodsReceiptsUseCase';
import { GetGoodsReceiptOutstandingUseCase } from '../GetGoodsReceiptOutstandingUseCase';
import { AddGoodsReceiptCommentUseCase } from '../AddGoodsReceiptCommentUseCase';
import { GetGoodsReceiptCommentsUseCase } from '../GetGoodsReceiptCommentsUseCase';
import { GoodsReceiptRepository } from '../../../../Domains/goods-receipts/GoodsReceiptRepository';
import { PurchaseOrderRepository } from '../../../../Domains/purchase-orders/PurchaseOrderRepository';
import { ProductRepository } from '../../../../Domains/products/ProductRepository';
import { UomRepository } from '../../../../Domains/uoms/UomRepository';
import { ProductUomConversionRepository } from '../../../../Domains/product-uom-conversions/ProductUomConversionRepository';

const grRepo: jest.Mocked<GoodsReceiptRepository> = {
  createDraft: jest.fn(),
  updateDraft: jest.fn(),
  getById: jest.fn(),
  list: jest.fn(),
  getConsumedQtyByPoItem: jest.fn(),
  cancel: jest.fn(),
  complete: jest.fn(),
  ensureExists: jest.fn(),
  addComment: jest.fn(),
  listComments: jest.fn(),
} as unknown as jest.Mocked<GoodsReceiptRepository>;

const poRepo: jest.Mocked<PurchaseOrderRepository> = {
  getById: jest.fn(),
} as unknown as jest.Mocked<PurchaseOrderRepository>;

const productRepo: jest.Mocked<ProductRepository> = {
  getProductById: jest.fn(),
} as unknown as jest.Mocked<ProductRepository>;

const uomRepo: jest.Mocked<UomRepository> = {
  getUomById: jest.fn(),
} as unknown as jest.Mocked<UomRepository>;

const conversionRepo: jest.Mocked<ProductUomConversionRepository> = {
  listByProduct: jest.fn(),
} as unknown as jest.Mocked<ProductUomConversionRepository>;

/**
 * Build a product UOM conversion row (UOM Conversion T2). `factorToBase` relates
 * the alternate uom to the base: 1 <uomId> = factorToBase <base>.
 */
function conversion(
  productId: string,
  uomId: string,
  factorToBase: number,
  isActive = true,
) {
  return { productId, uomId, factorToBase, isActive };
}

/** An APPROVED PO with two lines, used as the valid source for GR creation. */
function approvedPo(over: Record<string, unknown> = {}) {
  return {
    id: 'po-1',
    companyId: 'c1',
    status: 'APPROVED',
    supplierId: 'sup-1',
    destinationOutletId: 'outlet-1',
    items: [
      { id: 'poi-1', productId: 'prod-1', quantity: 10, uomId: 'uom-1' },
      { id: 'poi-2', productId: 'prod-2', quantity: 5, uomId: 'uom-1' },
    ],
    ...over,
  };
}

/**
 * A non-batch product by default. uomId defaults to 'uom-1' so a GR line in
 * 'uom-1' is in the product base unit (conversion factor 1 — pre-T2 identity).
 */
function product(id: string, isBatchTracked = false, uomId = 'uom-1') {
  return { id, isBatchTracked, uomId };
}

const basePayload = {
  purchaseOrderId: 'po-1',
  receiveDate: '2026-10-10',
  items: [
    {
      purchaseOrderItemId: 'poi-1',
      productId: 'prod-1',
      acceptedQuantity: 6,
      rejectedQuantity: 1,
      uomId: 'uom-1',
    },
  ],
};

beforeEach(() => {
  jest.clearAllMocks();
  // Default: no sibling GR consumption → outstanding == full PO quantity.
  grRepo.getConsumedQtyByPoItem.mockResolvedValue(new Map<string, number>());
  // Default products are non-batch, base unit 'uom-1'.
  productRepo.getProductById.mockImplementation((id: string) =>
    Promise.resolve(product(id) as never),
  );
  uomRepo.getUomById.mockResolvedValue({ id: 'uom' } as never);
  // Default: no alternate conversions → every base-unit line resolves factor 1.
  conversionRepo.listByProduct.mockResolvedValue([]);
});

function createUseCase() {
  return new CreateGoodsReceiptUseCase(grRepo, poRepo, productRepo, uomRepo, conversionRepo);
}

describe('CreateGoodsReceiptUseCase', () => {
  it('creates from an APPROVED PO, snapshotting supplier/outlet/ordered qty + numbering via repo', async () => {
    poRepo.getById.mockResolvedValue(approvedPo() as never);
    grRepo.createDraft.mockResolvedValue({ id: 'gr1' } as never);

    await createUseCase().execute(basePayload, 'c1', 'u1');

    expect(poRepo.getById).toHaveBeenCalledWith('po-1', 'c1');
    expect(grRepo.getConsumedQtyByPoItem).toHaveBeenCalledWith('po-1', 'c1');
    expect(grRepo.createDraft).toHaveBeenCalledWith(
      'c1',
      'u1',
      expect.objectContaining({
        purchaseOrderId: 'po-1',
        supplierId: 'sup-1', // inherited from the PO
        destinationOutletId: 'outlet-1', // inherited from the PO
      }),
    );
    const arg = grRepo.createDraft.mock.calls[0][2];
    expect(arg.items).toHaveLength(1);
    // ordered_quantity snapshotted from the PO line (10), not from the body.
    expect(arg.items[0]).toEqual(
      expect.objectContaining({
        purchaseOrderItemId: 'poi-1',
        orderedQuantity: 10,
        acceptedQuantity: 6,
        rejectedQuantity: 1,
      }),
    );
  });

  it('rejects creation when the PO is not APPROVED', async () => {
    poRepo.getById.mockResolvedValue(approvedPo({ status: 'SUBMITTED' }) as never);

    await expect(createUseCase().execute(basePayload, 'c1', 'u1')).rejects.toThrow(
      'GOODS_RECEIPT.PO_NOT_APPROVED',
    );
    expect(grRepo.createDraft).not.toHaveBeenCalled();
  });

  it('propagates PURCHASE_ORDER.NOT_FOUND for a foreign/missing PO (company-scope)', async () => {
    poRepo.getById.mockRejectedValue(new Error('PURCHASE_ORDER.NOT_FOUND'));

    await expect(createUseCase().execute(basePayload, 'c1', 'u1')).rejects.toThrow(
      'PURCHASE_ORDER.NOT_FOUND',
    );
    expect(grRepo.createDraft).not.toHaveBeenCalled();
  });

  it('rejects received (accepted + rejected) exceeding the PO line outstanding', async () => {
    poRepo.getById.mockResolvedValue(approvedPo() as never);
    // poi-1 PO qty 10, a sibling GR consumed 6 → outstanding 4; asking 7 fails.
    grRepo.getConsumedQtyByPoItem.mockResolvedValue(new Map([['poi-1', 6]]));

    await expect(createUseCase().execute(basePayload, 'c1', 'u1')).rejects.toThrow(
      'GOODS_RECEIPT.QTY_EXCEEDS_OUTSTANDING',
    );
    expect(grRepo.createDraft).not.toHaveBeenCalled();
  });

  it('accepts received exactly equal to the remaining outstanding', async () => {
    poRepo.getById.mockResolvedValue(approvedPo() as never);
    grRepo.createDraft.mockResolvedValue({ id: 'gr1' } as never);
    // poi-1 PO qty 10, consumed 3 → outstanding 7; receiving exactly 7 succeeds.
    grRepo.getConsumedQtyByPoItem.mockResolvedValue(new Map([['poi-1', 3]]));

    await createUseCase().execute(
      {
        ...basePayload,
        items: [
          {
            purchaseOrderItemId: 'poi-1',
            productId: 'prod-1',
            acceptedQuantity: 7,
            rejectedQuantity: 0,
            uomId: 'uom-1',
          },
        ],
      },
      'c1',
      'u1',
    );

    expect(grRepo.createDraft).toHaveBeenCalled();
  });

  it('rejects a product that does not belong to the source PO line', async () => {
    poRepo.getById.mockResolvedValue(approvedPo() as never);

    await expect(
      createUseCase().execute(
        {
          ...basePayload,
          items: [
            {
              purchaseOrderItemId: 'poi-1',
              productId: 'prod-foreign',
              acceptedQuantity: 1,
              rejectedQuantity: 0,
              uomId: 'uom-1',
            },
          ],
        },
        'c1',
        'u1',
      ),
    ).rejects.toThrow('GOODS_RECEIPT.ITEM_PRODUCT_MISMATCH');
    expect(grRepo.createDraft).not.toHaveBeenCalled();
  });

  it('requires batch + expiry for an accepted batch-tracked product', async () => {
    poRepo.getById.mockResolvedValue(approvedPo() as never);
    productRepo.getProductById.mockImplementation((id: string) =>
      Promise.resolve(product(id, true) as never),
    );

    await expect(createUseCase().execute(basePayload, 'c1', 'u1')).rejects.toThrow(
      'GOODS_RECEIPT.BATCH_REQUIRED',
    );
    expect(grRepo.createDraft).not.toHaveBeenCalled();
  });

  it('accepts an accepted batch-tracked product when batch + expiry are provided', async () => {
    poRepo.getById.mockResolvedValue(approvedPo() as never);
    productRepo.getProductById.mockImplementation((id: string) =>
      Promise.resolve(product(id, true) as never),
    );
    grRepo.createDraft.mockResolvedValue({ id: 'gr1' } as never);

    await createUseCase().execute(
      {
        ...basePayload,
        items: [
          {
            purchaseOrderItemId: 'poi-1',
            productId: 'prod-1',
            acceptedQuantity: 6,
            rejectedQuantity: 0,
            uomId: 'uom-1',
            batchNumber: 'B-001',
            expiryDate: '2026-12-31',
          },
        ],
      },
      'c1',
      'u1',
    );

    expect(grRepo.createDraft).toHaveBeenCalled();
    const arg = grRepo.createDraft.mock.calls[0][2];
    expect(arg.items[0]).toEqual(
      expect.objectContaining({ batchNumber: 'B-001', expiryDate: '2026-12-31' }),
    );
  });

  it('prefills only outstanding>0 lines (accepted = outstanding, rejected = 0) when body omits items', async () => {
    poRepo.getById.mockResolvedValue(approvedPo() as never);
    grRepo.createDraft.mockResolvedValue({ id: 'gr1' } as never);
    // poi-1: PO 10, consumed 4 → outstanding 6; poi-2: PO 5, consumed 5 → 0.
    grRepo.getConsumedQtyByPoItem.mockResolvedValue(new Map([['poi-1', 4], ['poi-2', 5]]));

    const { items, ...noItems } = basePayload;
    void items;
    await createUseCase().execute(noItems, 'c1', 'u1');

    const arg = grRepo.createDraft.mock.calls[0][2];
    expect(arg.items).toHaveLength(1);
    expect(arg.items[0]).toEqual(
      expect.objectContaining({
        purchaseOrderItemId: 'poi-1',
        acceptedQuantity: 6,
        rejectedQuantity: 0,
        orderedQuantity: 10,
      }),
    );
  });

  it('rejects create (prefill mode) when every PO line is fully received', async () => {
    poRepo.getById.mockResolvedValue(approvedPo() as never);
    grRepo.getConsumedQtyByPoItem.mockResolvedValue(new Map([['poi-1', 10], ['poi-2', 5]]));

    const { items, ...noItems } = basePayload;
    void items;
    await expect(createUseCase().execute(noItems, 'c1', 'u1')).rejects.toThrow(
      'GOODS_RECEIPT.NO_OUTSTANDING_ITEMS',
    );
    expect(grRepo.createDraft).not.toHaveBeenCalled();
  });

  it('validates every item product/uom against the company', async () => {
    poRepo.getById.mockResolvedValue(approvedPo() as never);
    productRepo.getProductById.mockRejectedValue(new Error('PRODUCT.NOT_FOUND'));

    await expect(createUseCase().execute(basePayload, 'c1', 'u1')).rejects.toThrow(
      'PRODUCT.NOT_FOUND',
    );
    expect(grRepo.createDraft).not.toHaveBeenCalled();
  });

  // --- UOM Conversion T2 (doc 50 §4/§8) — snapshot factor on create ---

  it('snapshots conversionFactor = 1 when the line uom IS the product base unit', async () => {
    poRepo.getById.mockResolvedValue(approvedPo() as never);
    grRepo.createDraft.mockResolvedValue({ id: 'gr1' } as never);
    // basePayload line uom 'uom-1' == product base 'uom-1' → factor 1.

    await createUseCase().execute(basePayload, 'c1', 'u1');

    const arg = grRepo.createDraft.mock.calls[0][2];
    expect(arg.items[0].conversionFactor).toBe(1);
    // A base-unit line never needs to consult the conversion master.
    expect(conversionRepo.listByProduct).toHaveBeenCalledWith('prod-1', 'c1');
  });

  it('snapshots factor_to_base when the line uom is an active alternate unit', async () => {
    // PO/GR line in 'uom-karung'; product base is 'uom-gram'; 1 karung = 25000 g.
    poRepo.getById.mockResolvedValue(
      approvedPo({
        items: [{ id: 'poi-1', productId: 'prod-1', quantity: 10, uomId: 'uom-karung' }],
      }) as never,
    );
    productRepo.getProductById.mockImplementation((id: string) =>
      Promise.resolve(product(id, false, 'uom-gram') as never),
    );
    conversionRepo.listByProduct.mockResolvedValue([
      conversion('prod-1', 'uom-karung', 25000) as never,
    ]);
    grRepo.createDraft.mockResolvedValue({ id: 'gr1' } as never);

    await createUseCase().execute(
      {
        ...basePayload,
        items: [
          {
            purchaseOrderItemId: 'poi-1',
            productId: 'prod-1',
            acceptedQuantity: 6,
            rejectedQuantity: 1,
            uomId: 'uom-karung',
          },
        ],
      },
      'c1',
      'u1',
    );

    const arg = grRepo.createDraft.mock.calls[0][2];
    expect(arg.items[0].conversionFactor).toBe(25000);
  });

  it('rejects a non-base line uom with no active conversion (MISSING_UOM_CONVERSION)', async () => {
    poRepo.getById.mockResolvedValue(
      approvedPo({
        items: [{ id: 'poi-1', productId: 'prod-1', quantity: 10, uomId: 'uom-karung' }],
      }) as never,
    );
    productRepo.getProductById.mockImplementation((id: string) =>
      Promise.resolve(product(id, false, 'uom-gram') as never),
    );
    // No conversion row for (prod-1, uom-karung).
    conversionRepo.listByProduct.mockResolvedValue([]);

    await expect(
      createUseCase().execute(
        {
          ...basePayload,
          items: [
            {
              purchaseOrderItemId: 'poi-1',
              productId: 'prod-1',
              acceptedQuantity: 6,
              rejectedQuantity: 1,
              uomId: 'uom-karung',
            },
          ],
        },
        'c1',
        'u1',
      ),
    ).rejects.toThrow('GOODS_RECEIPT.MISSING_UOM_CONVERSION');
    expect(grRepo.createDraft).not.toHaveBeenCalled();
  });

  it('treats an INACTIVE conversion as missing (MISSING_UOM_CONVERSION)', async () => {
    poRepo.getById.mockResolvedValue(
      approvedPo({
        items: [{ id: 'poi-1', productId: 'prod-1', quantity: 10, uomId: 'uom-karung' }],
      }) as never,
    );
    productRepo.getProductById.mockImplementation((id: string) =>
      Promise.resolve(product(id, false, 'uom-gram') as never),
    );
    conversionRepo.listByProduct.mockResolvedValue([
      conversion('prod-1', 'uom-karung', 25000, false) as never,
    ]);

    await expect(
      createUseCase().execute(
        {
          ...basePayload,
          items: [
            {
              purchaseOrderItemId: 'poi-1',
              productId: 'prod-1',
              acceptedQuantity: 6,
              rejectedQuantity: 1,
              uomId: 'uom-karung',
            },
          ],
        },
        'c1',
        'u1',
      ),
    ).rejects.toThrow('GOODS_RECEIPT.MISSING_UOM_CONVERSION');
    expect(grRepo.createDraft).not.toHaveBeenCalled();
  });
});

