import { RegisterCompany } from '../entities/RegisterCompany';

const validPayload = {
  name: 'Toko Roti Makmur',
  slug: 'toko-roti-makmur',
  ownerName: 'Budi Santoso',
  ownerEmail: 'budi@rotimakmur.com',
  ownerPassword: 'Secret1234',
};

describe('RegisterCompany', () => {
  it('should create entity with correct properties', () => {
    const entity = new RegisterCompany(validPayload);

    expect(entity.name).toBe('Toko Roti Makmur');
    expect(entity.slug).toBe('toko-roti-makmur');
    expect(entity.ownerName).toBe('Budi Santoso');
    expect(entity.ownerEmail).toBe('budi@rotimakmur.com');
    expect(entity.ownerPassword).toBe('Secret1234');
  });

  it('should normalize slug by trimming whitespace', () => {
    const entity = new RegisterCompany({ ...validPayload, slug: '  toko-roti  ' });

    expect(entity.slug).toBe('toko-roti');
  });

  it('should normalize email to lowercase', () => {
    const entity = new RegisterCompany({ ...validPayload, ownerEmail: 'BUDI@ROTI.COM' });

    expect(entity.ownerEmail).toBe('budi@roti.com');
  });

  it('should throw NOT_CONTAIN_NEEDED_PROPERTY when name is missing', () => {
    expect(() => new RegisterCompany({ ...validPayload, name: '' })).toThrow(
      'REGISTER_COMPANY.NOT_CONTAIN_NEEDED_PROPERTY',
    );
  });

  it('should throw NOT_CONTAIN_NEEDED_PROPERTY when slug is missing', () => {
    expect(() => new RegisterCompany({ ...validPayload, slug: '' })).toThrow(
      'REGISTER_COMPANY.NOT_CONTAIN_NEEDED_PROPERTY',
    );
  });

  it('should throw NOT_CONTAIN_NEEDED_PROPERTY when ownerEmail is missing', () => {
    expect(() => new RegisterCompany({ ...validPayload, ownerEmail: '' })).toThrow(
      'REGISTER_COMPANY.NOT_CONTAIN_NEEDED_PROPERTY',
    );
  });

  it('should throw NOT_CONTAIN_NEEDED_PROPERTY when ownerPassword is missing', () => {
    expect(() => new RegisterCompany({ ...validPayload, ownerPassword: '' })).toThrow(
      'REGISTER_COMPANY.NOT_CONTAIN_NEEDED_PROPERTY',
    );
  });

  it('should throw NOT_CONTAIN_NEEDED_PROPERTY when payload is null', () => {
    expect(() => new RegisterCompany(null)).toThrow(
      'REGISTER_COMPANY.NOT_CONTAIN_NEEDED_PROPERTY',
    );
  });

  it('should throw NOT_MEET_DATA_TYPE_SPECIFICATION when name is not a string', () => {
    expect(() => new RegisterCompany({ ...validPayload, name: 123 })).toThrow(
      'REGISTER_COMPANY.NOT_MEET_DATA_TYPE_SPECIFICATION',
    );
  });

  it('should throw NAME_LIMIT_CHAR when name exceeds 100 characters', () => {
    expect(
      () => new RegisterCompany({ ...validPayload, name: 'a'.repeat(101) }),
    ).toThrow('REGISTER_COMPANY.NAME_LIMIT_CHAR');
  });

  it('should throw SLUG_CONTAIN_RESTRICTED_CHARACTER when slug has spaces', () => {
    expect(
      () => new RegisterCompany({ ...validPayload, slug: 'toko roti' }),
    ).toThrow('REGISTER_COMPANY.SLUG_CONTAIN_RESTRICTED_CHARACTER');
  });

  it('should throw SLUG_CONTAIN_RESTRICTED_CHARACTER when slug has uppercase', () => {
    // 'TokoRoti' contains uppercase letters — regex /^[a-z0-9-]+$/ rejects it
    expect(
      () => new RegisterCompany({ ...validPayload, slug: 'TOKO-ROTI' }),
    ).toThrow('REGISTER_COMPANY.SLUG_CONTAIN_RESTRICTED_CHARACTER');
  });

  it('should throw SLUG_CONTAIN_RESTRICTED_CHARACTER when slug has special chars', () => {
    expect(
      () => new RegisterCompany({ ...validPayload, slug: 'toko_roti!' }),
    ).toThrow('REGISTER_COMPANY.SLUG_CONTAIN_RESTRICTED_CHARACTER');
  });

  it('should allow slug with numbers and hyphens', () => {
    expect(
      () => new RegisterCompany({ ...validPayload, slug: 'roti-123' }),
    ).not.toThrow();
  });
});

import {
  CreateGoodsReceipt,
  buildOutstandingMap,
  validateItemsAgainstOutstanding,
  validateBatchRequirements,
  resolveConversionFactor,
  ProductConversionContext,
  ResolvedGoodsReceiptItem,
  SourcePoItem,
  OutstandingPoItem,
} from '../entities/CreateGoodsReceipt';

const validPayload = {
  purchaseOrderId: 'po-1',
  receiveDate: '2026-10-10',
  items: [
    {
      purchaseOrderItemId: 'poi-1',
      productId: 'prod-1',
      acceptedQuantity: 3,
      rejectedQuantity: 0,
      uomId: 'uom-1',
    },
  ],
};

describe('CreateGoodsReceipt entity', () => {
  it('accepts a valid payload and trims strings', () => {
    const gr = new CreateGoodsReceipt(validPayload);
    expect(gr.purchaseOrderId).toBe('po-1');
    expect(gr.receiveDate).toBe('2026-10-10');
    expect(gr.items).toHaveLength(1);
    expect(gr.items![0].purchaseOrderItemId).toBe('poi-1');
  });

  it('leaves items null when none are supplied (prefill mode)', () => {
    const { items, ...noItems } = validPayload;
    void items;
    const gr = new CreateGoodsReceipt(noItems);
    expect(gr.items).toBeNull();
  });

  it('rejects a missing purchaseOrderId', () => {
    expect(() => new CreateGoodsReceipt({ receiveDate: '2026-10-10' })).toThrow(
      'CREATE_GOODS_RECEIPT.PURCHASE_ORDER_REQUIRED',
    );
  });

  it('rejects an invalid receive date', () => {
    expect(
      () => new CreateGoodsReceipt({ purchaseOrderId: 'po-1', receiveDate: 'not-a-date' }),
    ).toThrow('CREATE_GOODS_RECEIPT.RECEIVE_DATE_INVALID');
  });

  it('rejects an item missing the PO item reference', () => {
    expect(
      () =>
        new CreateGoodsReceipt({
          ...validPayload,
          items: [{ productId: 'prod-1', acceptedQuantity: 1, rejectedQuantity: 0, uomId: 'uom-1' }],
        }),
    ).toThrow('CREATE_GOODS_RECEIPT.ITEM_PO_ITEM_REQUIRED');
  });

  it('rejects a negative accepted quantity', () => {
    expect(
      () =>
        new CreateGoodsReceipt({
          ...validPayload,
          items: [
            {
              purchaseOrderItemId: 'poi-1',
              productId: 'prod-1',
              acceptedQuantity: -1,
              rejectedQuantity: 0,
              uomId: 'uom-1',
            },
          ],
        }),
    ).toThrow('CREATE_GOODS_RECEIPT.ITEM_ACCEPTED_QTY_MUST_BE_NON_NEGATIVE');
  });

  it('rejects a non-numeric rejected quantity', () => {
    expect(
      () =>
        new CreateGoodsReceipt({
          ...validPayload,
          items: [
            {
              purchaseOrderItemId: 'poi-1',
              productId: 'prod-1',
              acceptedQuantity: 1,
              rejectedQuantity: 'x',
              uomId: 'uom-1',
            },
          ],
        }),
    ).toThrow('CREATE_GOODS_RECEIPT.ITEM_REJECTED_QTY_NOT_MEET_DATA_TYPE_SPECIFICATION');
  });
});

describe('buildOutstandingMap', () => {
  const poItems: SourcePoItem[] = [
    { id: 'poi-1', productId: 'prod-1', quantity: 10, uomId: 'uom-1' },
    { id: 'poi-2', productId: 'prod-2', quantity: 5, uomId: 'uom-1' },
  ];

  it('computes outstanding = qtyPO - consumed, clamped at 0', () => {
    const consumed = new Map<string, number>([
      ['poi-1', 4],
      ['poi-2', 7], // over-consumed → clamp to 0
    ]);
    const result = buildOutstandingMap(poItems, consumed);
    expect(result).toEqual([
      expect.objectContaining({
        purchaseOrderItemId: 'poi-1',
        orderedQuantity: 10,
        receivedQuantity: 4,
        outstandingQuantity: 6,
      }),
      expect.objectContaining({
        purchaseOrderItemId: 'poi-2',
        orderedQuantity: 5,
        receivedQuantity: 7,
        outstandingQuantity: 0,
      }),
    ]);
  });

  it('treats a missing consumption key as 0', () => {
    const result = buildOutstandingMap(poItems, new Map());
    expect(result[0].outstandingQuantity).toBe(10);
    expect(result[1].outstandingQuantity).toBe(5);
  });
});

describe('validateItemsAgainstOutstanding', () => {
  const outstanding: OutstandingPoItem[] = [
    {
      purchaseOrderItemId: 'poi-1',
      productId: 'prod-1',
      orderedQuantity: 10,
      receivedQuantity: 4,
      outstandingQuantity: 6,
      uomId: 'uom-1',
    },
  ];

  function item(over: Partial<ResolvedGoodsReceiptItem> = {}): ResolvedGoodsReceiptItem {
    return {
      purchaseOrderItemId: 'poi-1',
      productId: 'prod-1',
      orderedQuantity: 10,
      acceptedQuantity: 3,
      rejectedQuantity: 1,
      uomId: 'uom-1',
      conversionFactor: 1,
      batchNumber: null,
      lotNumber: null,
      expiryDate: null,
      ...over,
    };
  }

  it('accepts accepted + rejected within outstanding', () => {
    expect(() => validateItemsAgainstOutstanding([item()], outstanding)).not.toThrow();
  });

  it('rejects a PO line not present in the PO', () => {
    expect(() =>
      validateItemsAgainstOutstanding([item({ purchaseOrderItemId: 'poi-x' })], outstanding),
    ).toThrow('GOODS_RECEIPT.ITEM_NOT_IN_PO');
  });

  it('rejects a product that does not match the PO line', () => {
    expect(() =>
      validateItemsAgainstOutstanding([item({ productId: 'prod-other' })], outstanding),
    ).toThrow('GOODS_RECEIPT.ITEM_PRODUCT_MISMATCH');
  });

  it('rejects duplicate PO lines in one GR', () => {
    expect(() => validateItemsAgainstOutstanding([item(), item()], outstanding)).toThrow(
      'GOODS_RECEIPT.DUPLICATE_ITEM',
    );
  });

  it('rejects a line that received nothing (accepted + rejected = 0)', () => {
    expect(() =>
      validateItemsAgainstOutstanding(
        [item({ acceptedQuantity: 0, rejectedQuantity: 0 })],
        outstanding,
      ),
    ).toThrow('GOODS_RECEIPT.ITEM_NOTHING_RECEIVED');
  });

  it('rejects received quantity exceeding outstanding', () => {
    expect(() =>
      validateItemsAgainstOutstanding(
        [item({ acceptedQuantity: 6, rejectedQuantity: 1 })], // 7 > 6
        outstanding,
      ),
    ).toThrow('GOODS_RECEIPT.QTY_EXCEEDS_OUTSTANDING');
  });
});

describe('validateBatchRequirements', () => {
  function item(over: Partial<ResolvedGoodsReceiptItem> = {}): ResolvedGoodsReceiptItem {
    return {
      purchaseOrderItemId: 'poi-1',
      productId: 'prod-1',
      orderedQuantity: 10,
      acceptedQuantity: 3,
      rejectedQuantity: 0,
      uomId: 'uom-1',
      conversionFactor: 1,
      batchNumber: null,
      lotNumber: null,
      expiryDate: null,
      ...over,
    };
  }

  it('requires batch for a batch-tracked product with accepted > 0', () => {
    expect(() =>
      validateBatchRequirements([item()], new Map([['prod-1', true]])),
    ).toThrow('GOODS_RECEIPT.BATCH_REQUIRED');
  });

  it('requires expiry for a batch-tracked product with accepted > 0 even if batch is present', () => {
    expect(() =>
      validateBatchRequirements(
        [item({ batchNumber: 'B1' })],
        new Map([['prod-1', true]]),
      ),
    ).toThrow('GOODS_RECEIPT.EXPIRY_REQUIRED');
  });

  it('passes when a batch-tracked accepted line has batch + expiry', () => {
    expect(() =>
      validateBatchRequirements(
        [item({ batchNumber: 'B1', expiryDate: '2026-12-31' })],
        new Map([['prod-1', true]]),
      ),
    ).not.toThrow();
  });

  it('does not require batch/expiry for a non-batch product', () => {
    expect(() =>
      validateBatchRequirements([item()], new Map([['prod-1', false]])),
    ).not.toThrow();
  });

  it('does not require batch/expiry for a batch-tracked product with accepted = 0 (rejected only)', () => {
    expect(() =>
      validateBatchRequirements(
        [item({ acceptedQuantity: 0, rejectedQuantity: 2 })],
        new Map([['prod-1', true]]),
      ),
    ).not.toThrow();
  });
});

describe('resolveConversionFactor (UOM Conversion T2)', () => {
  function context(over: Partial<ProductConversionContext> = {}): ProductConversionContext {
    return {
      baseUomId: 'uom-base',
      activeFactorsByUom: new Map<string, number>(),
      ...over,
    };
  }

  it('returns 1 when the line uom IS the product base unit (no row needed)', () => {
    expect(resolveConversionFactor('uom-base', context())).toBe(1);
  });

  it('returns factor_to_base for an active alternate unit', () => {
    const ctx = context({
      activeFactorsByUom: new Map([['uom-karung', 25000]]),
    });
    expect(resolveConversionFactor('uom-karung', ctx)).toBe(25000);
  });

  it('throws MISSING_UOM_CONVERSION for a non-base unit with no active factor', () => {
    expect(() => resolveConversionFactor('uom-karung', context())).toThrow(
      'GOODS_RECEIPT.MISSING_UOM_CONVERSION',
    );
  });

  it('preserves the pre-T2 identity: factor 1 ⇒ baseQty == inputQty', () => {
    const factor = resolveConversionFactor('uom-base', context());
    const inputQty = 7.5;
    expect(inputQty * factor).toBe(inputQty);
  });
});

import { CreateOutlet } from '../entities/CreateOutlet';

describe('CreateOutlet', () => {
  it('should create entity with correct properties', () => {
    const entity = new CreateOutlet({
      name: 'Outlet Sudirman',
      address: 'Jl. Sudirman No. 1',
      phone: '021-555-0100',
    });

    expect(entity.name).toBe('Outlet Sudirman');
    expect(entity.address).toBe('Jl. Sudirman No. 1');
    expect(entity.phone).toBe('021-555-0100');
  });

  it('should trim whitespace on name, address, and phone', () => {
    const entity = new CreateOutlet({
      name: '  Outlet A  ',
      address: '  Jl. A  ',
      phone: '  021  ',
    });

    expect(entity.name).toBe('Outlet A');
    expect(entity.address).toBe('Jl. A');
    expect(entity.phone).toBe('021');
  });

  it('should default address and phone to null when omitted', () => {
    const entity = new CreateOutlet({ name: 'Outlet A' });

    expect(entity.address).toBeNull();
    expect(entity.phone).toBeNull();
  });

  it('should throw NOT_CONTAIN_NEEDED_PROPERTY when payload is null', () => {
    expect(() => new CreateOutlet(null)).toThrow(
      'CREATE_OUTLET.NOT_CONTAIN_NEEDED_PROPERTY',
    );
  });

  it('should throw NOT_CONTAIN_NEEDED_PROPERTY when name is missing', () => {
    expect(() => new CreateOutlet({ name: '' })).toThrow(
      'CREATE_OUTLET.NOT_CONTAIN_NEEDED_PROPERTY',
    );
  });

  it('should throw NOT_MEET_DATA_TYPE_SPECIFICATION when name is not a string', () => {
    expect(() => new CreateOutlet({ name: 123 })).toThrow(
      'CREATE_OUTLET.NOT_MEET_DATA_TYPE_SPECIFICATION',
    );
  });

  it('should throw NOT_MEET_DATA_TYPE_SPECIFICATION when phone is not a string', () => {
    expect(() => new CreateOutlet({ name: 'A', phone: 123 })).toThrow(
      'CREATE_OUTLET.NOT_MEET_DATA_TYPE_SPECIFICATION',
    );
  });

  it('should throw NAME_LIMIT_CHAR when name exceeds 100 characters', () => {
    expect(() => new CreateOutlet({ name: 'a'.repeat(101) })).toThrow(
      'CREATE_OUTLET.NAME_LIMIT_CHAR',
    );
  });

  it('should throw PHONE_LIMIT_CHAR when phone exceeds 30 characters', () => {
    expect(() => new CreateOutlet({ name: 'A', phone: '1'.repeat(31) })).toThrow(
      'CREATE_OUTLET.PHONE_LIMIT_CHAR',
    );
  });

  it('should default code to null when omitted or blank', () => {
    expect(new CreateOutlet({ name: 'Outlet A' }).code).toBeNull();
    expect(new CreateOutlet({ name: 'Outlet A', code: '   ' }).code).toBeNull();
    expect(new CreateOutlet({ name: 'Outlet A', code: null }).code).toBeNull();
  });

  it('should trim and uppercase a supplied code', () => {
    const entity = new CreateOutlet({ name: 'Outlet A', code: '  out-bdg-01  ' });

    expect(entity.code).toBe('OUT-BDG-01');
  });

  it('should throw NOT_MEET_DATA_TYPE_SPECIFICATION when code is not a string', () => {
    expect(() => new CreateOutlet({ name: 'A', code: 123 })).toThrow(
      'CREATE_OUTLET.NOT_MEET_DATA_TYPE_SPECIFICATION',
    );
  });

  it('should throw CODE_LIMIT_CHAR when code exceeds 20 characters', () => {
    expect(() => new CreateOutlet({ name: 'A', code: 'X'.repeat(21) })).toThrow(
      'CREATE_OUTLET.CODE_LIMIT_CHAR',
    );
  });
});

