import { Pool } from 'pg';
import { DashboardRepositoryPostgres } from '../DashboardRepositoryPostgres';

const mockPool = { query: jest.fn() } as unknown as Pool;
const query = mockPool.query as jest.Mock;

const companyId = 'c1';
const outletId = 'o1';
const businessDate = new Date('2026-10-25T03:00:00.000Z');

/** Resolve each aggregate query with a shape its mapper can consume. */
function stubAggregates(topProductRows: unknown[] = []): void {
  query.mockImplementation((sql: string) => {
    if (sql.includes('FROM sales_order_items soi')) {
      return Promise.resolve({ rows: topProductRows });
    }
    if (sql.includes('COUNT(*) AS count')) {
      return Promise.resolve({ rows: [{ count: '0', revenue: '0' }] });
    }
    if (sql.includes('AS revenue')) {
      return Promise.resolve({ rows: [{ revenue: '0', count: '0' }] });
    }
    return Promise.resolve({ rows: [] });
  });
}

/** Grab the (sql, params) pair of the call whose SQL contains `marker`. */
function callWith(marker: string): [string, unknown[]] {
  const call = query.mock.calls.find(([sql]) => (sql as string).includes(marker));
  if (!call) throw new Error(`No query matched marker: ${marker}`);
  return call as [string, unknown[]];
}

describe('DashboardRepositoryPostgres.getOwnerSummary', () => {
  let repo: DashboardRepositoryPostgres;

  beforeEach(() => {
    jest.clearAllMocks();
    stubAggregates();
    repo = new DashboardRepositoryPostgres(mockPool);
  });

  describe('company-wide (no outlet)', () => {
    beforeEach(async () => {
      await repo.getOwnerSummary(companyId, {}, businessDate);
    });

    it('should not filter any aggregate by outlet', () => {
      for (const [sql] of query.mock.calls) {
        expect(sql as string).not.toMatch(/outlet_id = \$/);
      }
    });

    it('should scope every aggregate to the company', () => {
      for (const [, params] of query.mock.calls) {
        expect((params as unknown[])[0]).toBe(companyId);
      }
    });
  });

  describe('scoped to one outlet', () => {
    beforeEach(async () => {
      await repo.getOwnerSummary(companyId, { outletId }, businessDate);
    });

    it('should filter today sales metrics by outlet', () => {
      const [sql, params] = callWith("DATE(paid_at + interval '7 hours') = $2");
      expect(sql).toContain('AND outlet_id = $3');
      expect(params).toEqual([companyId, '2026-10-25', outletId]);
    });

    it('should filter the low stock aggregate by outlet', () => {
      const [sql, params] = callWith('HAVING SUM(b.qty_available) < p.minimum_stock');
      expect(sql).toContain('AND b.outlet_id = $2');
      expect(params).toEqual([companyId, outletId]);
    });

    it('should filter the expired batch count by outlet', () => {
      const [sql, params] = callWith('AND expired_date < $2::date');
      expect(sql).toContain('AND outlet_id = $3');
      expect(params).toEqual([companyId, '2026-10-25', outletId]);
    });

    it('should filter the sales trend by outlet', () => {
      const [sql, params] = callWith('GROUP BY DATE(paid_at');
      expect(sql).toContain('AND outlet_id = $4');
      expect(params).toEqual([companyId, '2026-10-19', '2026-10-25', outletId]);
    });

    it('should filter expiring batches by outlet without displacing the limit', () => {
      const [sql, params] = callWith('b.batch_number AS batch_no');
      expect(sql).toContain('AND b.outlet_id = $5');
      expect(sql).toContain('LIMIT $4');
      expect(params).toEqual([companyId, '2026-10-25', '2026-11-24', 10, outletId]);
    });

    it('should filter top selling products by outlet without displacing the limit', () => {
      const [sql, params] = callWith('soi.product_name_snapshot');
      expect(sql).toContain('AND so.outlet_id = $5');
      expect(sql).toContain('LIMIT $4');
      expect(params).toEqual([companyId, '2026-10-19', '2026-10-25', 10, outletId]);
    });
  });

  it('should apply a custom period and top-products limit', async () => {
    await repo.getOwnerSummary(
      companyId,
      { periodDays: 30, topProductsLimit: 20 },
      businessDate,
    );

    const [, trendParams] = callWith('GROUP BY DATE(paid_at');
    const [, topProductParams] = callWith('FROM sales_order_items soi');
    expect(trendParams).toEqual([companyId, '2026-09-26', '2026-10-25']);
    expect(topProductParams).toEqual([companyId, '2026-09-26', '2026-10-25', 20]);
  });

  describe('waffle and topping combinations', () => {
    it.each([
      { label: 'no toppings', toppingNames: [] },
      { label: 'one topping', toppingNames: ['Synthetic Cocoa'] },
      { label: 'multiple toppings', toppingNames: ['Synthetic Berry', 'Synthetic Cocoa'] },
    ])('should map $label and numeric aggregates', async ({ toppingNames }) => {
      const productId = '00000000-0000-4000-8000-000000000001';
      stubAggregates([{
        product_id: productId,
        product_name: 'Synthetic Waffle Snapshot',
        topping_names: toppingNames,
        qty_sold: '2.750',
        revenue: '12345.67',
      }]);

      const summary = await repo.getOwnerSummary(companyId, {}, businessDate);

      expect(summary.topProducts).toEqual([{
        productId,
        productName: 'Synthetic Waffle Snapshot',
        toppingNames,
        qtySold: 2.75,
        revenue: 12345.67,
      }]);
    });

    it('should map an empty result to an empty top-products list', async () => {
      const summary = await repo.getOwnerSummary(companyId, {}, businessDate);
      expect(summary.topProducts).toEqual([]);
    });

    it('should aggregate sorted snapshot names once per item with an empty-array fallback', async () => {
      await repo.getOwnerSummary(companyId, {}, businessDate);
      const [sql] = callWith('FROM sales_order_items soi');

      expect(sql).toMatch(/LEFT JOIN LATERAL\s*\(/);
      expect(sql).toMatch(
        /COALESCE\(\s*ARRAY_AGG\(sot\.topping_name_snapshot ORDER BY sot\.topping_name_snapshot\),\s*ARRAY\[\]::varchar\[\]/,
      );
      expect(sql).toContain('FROM sales_order_item_toppings sot');
      expect(sql).toContain('WHERE sot.sales_order_item_id = soi.id');
      expect(sql).toMatch(/\) topping ON TRUE/);
    });

    it('should group variants without multiplying sums or consulting current master data', async () => {
      await repo.getOwnerSummary(companyId, {}, businessDate);
      const [sql, params] = callWith('FROM sales_order_items soi');

      expect(sql).toContain(
        'GROUP BY soi.product_id, soi.product_name_snapshot, topping.topping_names',
      );
      expect(sql.match(/SUM\(soi\.qty\)/g)).toHaveLength(1);
      expect(sql.match(/SUM\(soi\.line_total\)/g)).toHaveLength(1);
      expect(sql).not.toMatch(/JOIN\s+(?:products|toppings)\b/i);
      expect(sql).toContain('ORDER BY qty_sold DESC, product_name, topping.topping_names');
      expect(sql).toContain('LIMIT $4');
      expect(params).toEqual([companyId, '2026-10-19', '2026-10-25', 10]);
    });
  });
});

import { Pool, PoolClient } from 'pg';
import { GoodsReceiptRepositoryPostgres } from '../GoodsReceiptRepositoryPostgres';
import { NotFoundError } from '../../../Commons/exceptions/NotFoundError';
import { InvariantError } from '../../../Commons/exceptions/InvariantError';

/**
 * Unit tests for the Goods Receipt complete (Stage 2) posting path. The pg
 * client is mocked and sequenced by call order, mirroring the style used by
 * InventoryRepositoryPostgres.test / StockAdjustmentRepositoryPostgres.test.
 *
 * complete() must: post only ACCEPTED (>0) lines, resolve-or-create the batch
 * for batch-tracked lines (expiry preserved) and a synthetic non-batch row for
 * null-batch lines, flip DRAFT -> COMPLETED + inventory_posted_at + status log,
 * be idempotent for an already-COMPLETED GR, reject a non-DRAFT transition, and
 * roll back entirely if any posting step fails (atomicity).
 */

const mockPool = { query: jest.fn(), connect: jest.fn() } as unknown as Pool;

function headerRow(over: Record<string, unknown> = {}) {
  return {
    id: 'gr1',
    company_id: 'c1',
    gr_number: 'GR-2026-000001',
    purchase_order_id: 'po1',
    supplier_id: 'sup1',
    destination_outlet_id: 'o1',
    receive_date: new Date('2026-10-10'),
    status: 'DRAFT',
    inventory_posted_at: null,
    notes: null,
    approved_by: null,
    approved_at: null,
    created_by: 'u1',
    updated_by: null,
    created_at: new Date('2026-10-10'),
    updated_at: new Date('2026-10-10'),
    ...over,
  };
}

function itemRow(over: Record<string, unknown> = {}) {
  return {
    id: 'gri1',
    purchase_order_item_id: 'poi1',
    product_id: 'prod1',
    ordered_quantity: '10',
    accepted_quantity: '6',
    rejected_quantity: '1',
    uom_id: 'uom1',
    conversion_factor: '1',
    batch_number: 'B-001',
    lot_number: null,
    expiry_date: new Date('2026-12-31'),
    ...over,
  };
}

describe('GoodsReceiptRepositoryPostgres.complete', () => {
  let repo: GoodsReceiptRepositoryPostgres;
  let client: { query: jest.Mock; release: jest.Mock };

  beforeEach(() => {
    jest.clearAllMocks();
    client = { query: jest.fn(), release: jest.fn() };
    (mockPool.connect as jest.Mock).mockResolvedValue(client as unknown as PoolClient);
    repo = new GoodsReceiptRepositoryPostgres(mockPool);
  });

  it('throws NotFoundError when the GR is missing/foreign', async () => {
    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce(undefined) // SET ISOLATION
      .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // SELECT header FOR UPDATE
      .mockResolvedValueOnce(undefined); // ROLLBACK

    await expect(repo.complete('grX', 'c1', 'u1', null)).rejects.toBeInstanceOf(NotFoundError);
    expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    expect(client.release).toHaveBeenCalled();
  });

  it('rejects completing a non-DRAFT (e.g. CANCELLED) GR with an invalid transition', async () => {
    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce(undefined) // SET ISOLATION
      .mockResolvedValueOnce({ rows: [headerRow({ status: 'CANCELLED' })], rowCount: 1 }) // header
      .mockResolvedValueOnce(undefined); // ROLLBACK

    await expect(repo.complete('gr1', 'c1', 'u1', null)).rejects.toThrow(
      'GOODS_RECEIPT.INVALID_STATUS_TRANSITION',
    );
    expect(client.query).toHaveBeenCalledWith('ROLLBACK');
  });

  it('is idempotent: an already-COMPLETED GR is returned unchanged without posting', async () => {
    const completedHeader = headerRow({
      status: 'COMPLETED',
      inventory_posted_at: new Date('2026-10-11'),
    });
    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce(undefined) // SET ISOLATION
      .mockResolvedValueOnce({ rows: [completedHeader], rowCount: 1 }) // header
      .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // _loadItems
      .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs
      .mockResolvedValueOnce(undefined); // COMMIT

    const gr = await repo.complete('gr1', 'c1', 'u1', null);

    expect(gr.status).toBe('COMPLETED');
    expect(client.query).toHaveBeenCalledWith('COMMIT');
    // No batch INSERT/UPDATE or movement INSERT was issued.
    const sqls = client.query.mock.calls.map((c) => String(c[0]));
    expect(sqls.some((s) => s.includes('inventory_movements'))).toBe(false);
    expect(sqls.some((s) => s.includes("status = 'COMPLETED'"))).toBe(false);
  });

  it('completes DRAFT -> COMPLETED, posting only accepted>0 lines (batch-tracked resolve-or-create)', async () => {
    // One batch-tracked accepted line (6) + one rejected-only line (should NOT post).
    const accepted = itemRow({ id: 'gri1', accepted_quantity: '6' });
    const rejectedOnly = itemRow({
      id: 'gri2',
      product_id: 'prod2',
      accepted_quantity: '0',
      rejected_quantity: '2',
      batch_number: null,
      expiry_date: null,
    });

    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce(undefined) // SET ISOLATION
      .mockResolvedValueOnce({ rows: [headerRow()], rowCount: 1 }) // header FOR UPDATE
      .mockResolvedValueOnce({ rows: [accepted, rejectedOnly], rowCount: 2 }) // _loadItems
      // --- posting gri1 (accepted 6): resolveOrCreateBatch -> not found -> insert
      .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // SELECT batch FOR UPDATE
      .mockResolvedValueOnce({ rows: [{ id: 'batch1' }], rowCount: 1 }) // INSERT batch
      .mockResolvedValueOnce({ rowCount: 1 }) // UPDATE batch balance
      .mockResolvedValueOnce({ rows: [{ id: 'm1' }], rowCount: 1 }) // INSERT movement
      // --- flip header + log
      .mockResolvedValueOnce({ rows: [headerRow({ status: 'COMPLETED', inventory_posted_at: new Date() })], rowCount: 1 }) // UPDATE header
      .mockResolvedValueOnce(undefined) // INSERT log
      .mockResolvedValueOnce({ rows: [accepted, rejectedOnly], rowCount: 2 }) // _loadItems final
      .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs final
      .mockResolvedValueOnce(undefined); // COMMIT

    const gr = await repo.complete('gr1', 'c1', 'u1', 'received ok');

    expect(gr.status).toBe('COMPLETED');
    expect(client.query).toHaveBeenCalledWith('COMMIT');

    // Exactly one PURCHASE movement inserted (only the accepted line).
    const movementInserts = client.query.mock.calls.filter((c) =>
      String(c[0]).includes('INSERT INTO inventory_movements'),
    );
    expect(movementInserts).toHaveLength(1);
    const movementParams = movementInserts[0][1] as unknown[];
    expect(movementParams).toContain('PURCHASE');
    expect(movementParams).toContain('GOODS_RECEIPT');
    expect(movementParams).toContain(6); // accepted qty posted

    // The created batch carried the batch-tracked expiry (date-only string).
    const batchInsert = client.query.mock.calls.find((c) =>
      String(c[0]).includes('INSERT INTO inventory_batches'),
    );
    expect(batchInsert).toBeDefined();
    expect((batchInsert![1] as unknown[])).toContain('2026-12-31'); // expiry
    expect((batchInsert![1] as unknown[])).toContain(false); // is_non_batch

    // Header flipped to COMPLETED + inventory posted.
    const headerUpdate = client.query.mock.calls.find((c) =>
      String(c[0]).includes("status = 'COMPLETED'"),
    );
    expect(headerUpdate).toBeDefined();
    expect(String(headerUpdate![0])).toContain('inventory_posted_at = NOW()');
  });

  it('creates a synthetic non-batch row (empty batch, null expiry) for a non-batch accepted line', async () => {
    const nonBatch = itemRow({
      id: 'gri1',
      product_id: 'prodNB',
      accepted_quantity: '4',
      rejected_quantity: '0',
      batch_number: null,
      lot_number: null,
      expiry_date: null,
    });

    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce(undefined) // SET ISOLATION
      .mockResolvedValueOnce({ rows: [headerRow()], rowCount: 1 }) // header
      .mockResolvedValueOnce({ rows: [nonBatch], rowCount: 1 }) // _loadItems
      .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // SELECT batch FOR UPDATE
      .mockResolvedValueOnce({ rows: [{ id: 'batchNB' }], rowCount: 1 }) // INSERT batch
      .mockResolvedValueOnce({ rowCount: 1 }) // UPDATE batch
      .mockResolvedValueOnce({ rows: [{ id: 'mNB' }], rowCount: 1 }) // INSERT movement
      .mockResolvedValueOnce({ rows: [headerRow({ status: 'COMPLETED' })], rowCount: 1 }) // UPDATE header
      .mockResolvedValueOnce(undefined) // INSERT log
      .mockResolvedValueOnce({ rows: [nonBatch], rowCount: 1 }) // _loadItems final
      .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs final
      .mockResolvedValueOnce(undefined); // COMMIT

    await repo.complete('gr1', 'c1', 'u1', null);

    const batchInsert = client.query.mock.calls.find((c) =>
      String(c[0]).includes('INSERT INTO inventory_batches'),
    );
    const params = batchInsert![1] as unknown[];
    // batch_number '' sentinel, null expiry, is_non_batch true.
    expect(params).toContain('');
    expect(params).toContain(null);
    expect(params).toContain(true);
  });

  it('reuses an existing batch (resolve) and adds to its balance', async () => {
    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce(undefined) // SET ISOLATION
      .mockResolvedValueOnce({ rows: [headerRow()], rowCount: 1 }) // header
      .mockResolvedValueOnce({ rows: [itemRow({ accepted_quantity: '6' })], rowCount: 1 }) // _loadItems
      .mockResolvedValueOnce({ rows: [{ id: 'batchExisting', qty_available: '4' }], rowCount: 1 }) // SELECT batch FOR UPDATE -> found
      .mockResolvedValueOnce({ rowCount: 1 }) // UPDATE batch
      .mockResolvedValueOnce({ rows: [{ id: 'm1' }], rowCount: 1 }) // INSERT movement
      .mockResolvedValueOnce({ rows: [headerRow({ status: 'COMPLETED' })], rowCount: 1 }) // UPDATE header
      .mockResolvedValueOnce(undefined) // INSERT log
      .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // _loadItems final
      .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs final
      .mockResolvedValueOnce(undefined); // COMMIT

    await repo.complete('gr1', 'c1', 'u1', null);

    // No batch INSERT (reused). Movement after_qty = 4 + 6 = 10.
    const batchInsert = client.query.mock.calls.find((c) =>
      String(c[0]).includes('INSERT INTO inventory_batches'),
    );
    expect(batchInsert).toBeUndefined();
    const movementInsert = client.query.mock.calls.find((c) =>
      String(c[0]).includes('INSERT INTO inventory_movements'),
    );
    const params = movementInsert![1] as unknown[];
    expect(params).toContain(4); // before_qty
    expect(params).toContain(10); // after_qty
  });

  // --- UOM Conversion T2 (doc 50 §4/§8): posting converts accepted → baseQty ---

  it('posts baseQty = accepted * snapshot factor (factor 25000) into a reused batch', async () => {
    // 2 karung accepted, snapshot factor 25000 → baseQty 50000; batch had 0.
    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce(undefined) // SET ISOLATION
      .mockResolvedValueOnce({ rows: [headerRow()], rowCount: 1 }) // header
      .mockResolvedValueOnce({
        rows: [itemRow({ accepted_quantity: '2', conversion_factor: '25000' })],
        rowCount: 1,
      }) // _loadItems
      .mockResolvedValueOnce({ rows: [{ id: 'b1', qty_available: '0' }], rowCount: 1 }) // SELECT batch -> found
      .mockResolvedValueOnce({ rowCount: 1 }) // UPDATE batch
      .mockResolvedValueOnce({ rows: [{ id: 'm1' }], rowCount: 1 }) // INSERT movement
      .mockResolvedValueOnce({ rows: [headerRow({ status: 'COMPLETED' })], rowCount: 1 }) // UPDATE header
      .mockResolvedValueOnce(undefined) // INSERT log
      .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // _loadItems final
      .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs final
      .mockResolvedValueOnce(undefined); // COMMIT

    await repo.complete('gr1', 'c1', 'u1', null);

    const movementInsert = client.query.mock.calls.find((c) =>
      String(c[0]).includes('INSERT INTO inventory_movements'),
    );
    const params = movementInsert![1] as unknown[];
    // qty, before_qty, after_qty all in the BASE unit.
    expect(params).toContain(50000); // qty = 2 * 25000
    expect(params).toContain(0); // before_qty
    expect(params).toContain(50000); // after_qty = 0 + 50000
  });

  it('REGRESSION: factor 1 posts accepted unchanged (identical to pre-T2)', async () => {
    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce(undefined) // SET ISOLATION
      .mockResolvedValueOnce({ rows: [headerRow()], rowCount: 1 }) // header
      .mockResolvedValueOnce({
        rows: [itemRow({ accepted_quantity: '6', conversion_factor: '1' })],
        rowCount: 1,
      }) // _loadItems
      .mockResolvedValueOnce({ rows: [{ id: 'b1', qty_available: '4' }], rowCount: 1 }) // SELECT batch
      .mockResolvedValueOnce({ rowCount: 1 }) // UPDATE batch
      .mockResolvedValueOnce({ rows: [{ id: 'm1' }], rowCount: 1 }) // INSERT movement
      .mockResolvedValueOnce({ rows: [headerRow({ status: 'COMPLETED' })], rowCount: 1 }) // UPDATE header
      .mockResolvedValueOnce(undefined) // INSERT log
      .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // _loadItems final
      .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs final
      .mockResolvedValueOnce(undefined); // COMMIT

    await repo.complete('gr1', 'c1', 'u1', null);

    const movementInsert = client.query.mock.calls.find((c) =>
      String(c[0]).includes('INSERT INTO inventory_movements'),
    );
    const params = movementInsert![1] as unknown[];
    expect(params).toContain(6); // qty == accepted (factor 1)
    expect(params).toContain(4); // before_qty
    expect(params).toContain(10); // after_qty = 4 + 6
  });

  it('rounds baseQty to NUMERIC(18,3) stock precision (0.333333 factor)', async () => {
    // accepted 10, factor 0.333333 → 3.33333 → rounded to 3.333 (3 decimals).
    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce(undefined) // SET ISOLATION
      .mockResolvedValueOnce({ rows: [headerRow()], rowCount: 1 }) // header
      .mockResolvedValueOnce({
        rows: [itemRow({ accepted_quantity: '10', conversion_factor: '0.333333' })],
        rowCount: 1,
      }) // _loadItems
      .mockResolvedValueOnce({ rows: [{ id: 'b1', qty_available: '0' }], rowCount: 1 }) // SELECT batch
      .mockResolvedValueOnce({ rowCount: 1 }) // UPDATE batch
      .mockResolvedValueOnce({ rows: [{ id: 'm1' }], rowCount: 1 }) // INSERT movement
      .mockResolvedValueOnce({ rows: [headerRow({ status: 'COMPLETED' })], rowCount: 1 }) // UPDATE header
      .mockResolvedValueOnce(undefined) // INSERT log
      .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // _loadItems final
      .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs final
      .mockResolvedValueOnce(undefined); // COMMIT

    await repo.complete('gr1', 'c1', 'u1', null);

    const movementInsert = client.query.mock.calls.find((c) =>
      String(c[0]).includes('INSERT INTO inventory_movements'),
    );
    const params = movementInsert![1] as unknown[];
    expect(params).toContain(3.333); // round(10 * 0.333333, 3)
  });

  it('rolls back and surfaces DUPLICATE_MOVEMENT_SOURCE on a double-post (atomicity)', async () => {
    const dupErr = Object.assign(new Error('dup'), { code: '23505' });
    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce(undefined) // SET ISOLATION
      .mockResolvedValueOnce({ rows: [headerRow()], rowCount: 1 }) // header
      .mockResolvedValueOnce({ rows: [itemRow({ accepted_quantity: '6' })], rowCount: 1 }) // _loadItems
      .mockResolvedValueOnce({ rows: [{ id: 'b1', qty_available: '0' }], rowCount: 1 }) // SELECT batch FOR UPDATE
      .mockResolvedValueOnce({ rowCount: 1 }) // UPDATE batch
      .mockRejectedValueOnce(dupErr) // INSERT movement -> conflict
      .mockResolvedValueOnce(undefined); // ROLLBACK

    await expect(repo.complete('gr1', 'c1', 'u1', null)).rejects.toThrow(
      'INVENTORY.DUPLICATE_MOVEMENT_SOURCE',
    );
    expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    // Header was never flipped to COMPLETED.
    const headerUpdate = client.query.mock.calls.find((c) =>
      String(c[0]).includes("status = 'COMPLETED'"),
    );
    expect(headerUpdate).toBeUndefined();
    expect(client.release).toHaveBeenCalled();
  });

  it('cancel (Opsi A): DRAFT -> CANCELLED keeps the row visible (no deleted_at/by) and logs', async () => {
    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce({ rows: [headerRow({ status: 'DRAFT' })], rowCount: 1 }) // lock header
      .mockResolvedValueOnce({ rows: [headerRow({ status: 'CANCELLED' })], rowCount: 1 }) // update
      .mockResolvedValueOnce(undefined) // insert log
      .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // _loadItems
      .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs
      .mockResolvedValueOnce(undefined); // COMMIT

    const gr = await repo.cancel('gr1', 'c1', 'u1', 'batal');
    expect(gr.status).toBe('CANCELLED');

    const updateCall = client.query.mock.calls[2];
    // Opsi A: cancel must NOT soft-delete; the row stays visible in list.
    expect(String(updateCall[0])).not.toContain('deleted_at');
    expect(String(updateCall[0])).not.toContain('deleted_by');
    expect(String(updateCall[0])).toContain("status = 'CANCELLED'");
    expect(client.query).toHaveBeenCalledWith('COMMIT');
  });

  it('rolls back when the balance update would go negative (shared negative-stock ban)', async () => {
    // Not expected for inbound PURCHASE, but proves the shared ledger guard is
    // active on this path. Force an outbound-like failure by making before_qty
    // such that... (inbound always adds, so instead assert InvariantError is
    // propagated by simulating the INSERT failing is covered above). Here we
    // assert a NotFoundError from a vanished batch mid-transaction rolls back.
    client.query
      .mockResolvedValueOnce(undefined) // BEGIN
      .mockResolvedValueOnce(undefined) // SET ISOLATION
      .mockResolvedValueOnce({ rows: [headerRow()], rowCount: 1 }) // header
      .mockResolvedValueOnce({ rows: [itemRow({ accepted_quantity: '6' })], rowCount: 1 }) // _loadItems
      .mockRejectedValueOnce(new InvariantError('INVENTORY.SOMETHING')) // resolveOrCreateBatch SELECT fails
      .mockResolvedValueOnce(undefined); // ROLLBACK

    await expect(repo.complete('gr1', 'c1', 'u1', null)).rejects.toBeInstanceOf(InvariantError);
    expect(client.query).toHaveBeenCalledWith('ROLLBACK');
  });
});

import { Pool, PoolClient } from 'pg';
import { InventoryRepositoryPostgres } from '../InventoryRepositoryPostgres';
import { NotFoundError } from '../../../Commons/exceptions/NotFoundError';
import { InvariantError } from '../../../Commons/exceptions/InvariantError';
import { MovementDraft } from '../../../Domains/inventory/InventoryRepository';

const mockPool = { query: jest.fn(), connect: jest.fn() } as unknown as Pool;

function batchRow(over: Record<string, unknown> = {}) {
  return {
    id: 'b1',
    company_id: 'c1',
    outlet_id: 'o1',
    product_id: 'p1',
    batch_number: 'B-1',
    lot_key: '',
    lot_number: null,
    expired_date: new Date('2026-12-31'),
    received_date: new Date('2026-01-01'),
    qty_available: '10',
    status: 'ACTIVE',
    is_non_batch: false,
    ...over,
  };
}

describe('InventoryRepositoryPostgres', () => {
  let repo: InventoryRepositoryPostgres;

  beforeEach(() => {
    jest.clearAllMocks();
    repo = new InventoryRepositoryPostgres(mockPool);
  });

  describe('getStockOnHand', () => {
    it.each([false, true])('sums non-expired ACTIVE batches with lowOnly=%s', async (lowOnly) => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [{ count: '1' }] })
        .mockResolvedValueOnce({
          rows: [
            {
              product_id: 'p1',
              product_sku: 'SKU-1',
              product_name: 'Waffle',
              outlet_id: 'o1',
              outlet_name: 'Outlet Utama',
              uom_id: 'u1',
              uom_code: 'PCS',
              uom_name: 'Pieces',
              qty_available: '4',
              minimum_stock: '5',
            },
          ],
        });

      const result = await repo.getStockOnHand(
        'c1',
        { limit: 20, offset: 0, outletId: 'o1', lowOnly },
        new Date('2026-10-27T17:00:00.000Z'),
      );

      expect(result.rows[0]).toMatchObject({ qtyAvailable: 4, isLow: true });
      for (const [sql] of (mockPool.query as jest.Mock).mock.calls) {
        expect(sql as string).toContain("b.status = 'ACTIVE'");
        expect(sql as string).toContain('b.expired_date IS NULL OR b.expired_date >= $2::date');
        expect(sql as string).not.toContain('CURRENT_DATE');
      }
      expect((mockPool.query as jest.Mock).mock.calls[0][1]).toEqual([
        'c1',
        '2026-10-28',
        'o1',
      ]);
      expect((mockPool.query as jest.Mock).mock.calls[1][1]).toEqual([
        'c1',
        '2026-10-28',
        'o1',
        20,
        0,
      ]);
    });
  });

  describe('getBatchById', () => {
    it('should return an InventoryBatch when found', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rows: [batchRow()], rowCount: 1 });

      const batch = await repo.getBatchById('b1', 'c1');
      expect(batch.id).toBe('b1');
      expect(batch.qtyAvailable).toBe(10);
    });

    it('should throw NotFoundError when missing', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rows: [], rowCount: 0 });
      await expect(repo.getBatchById('x', 'c1')).rejects.toBeInstanceOf(NotFoundError);
    });
  });

  describe('planFefoAllocation', () => {
    it('should allocate from nearest expiry first across batches', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({
        rows: [
          batchRow({ id: 'near', expired_date: new Date('2026-02-01'), qty_available: '3' }),
          batchRow({ id: 'far', expired_date: new Date('2026-05-01'), qty_available: '10' }),
        ],
        rowCount: 2,
      });

      const plan = await repo.planFefoAllocation('c1', 'o1', 'p1', 5, new Date('2026-01-01'));

      expect(plan).toHaveLength(2);
      expect(plan[0]).toMatchObject({ batchId: 'near', qty: 3 });
      expect(plan[1]).toMatchObject({ batchId: 'far', qty: 2 });
    });

    it('should allocate fully from a single batch when sufficient', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({
        rows: [batchRow({ id: 'only', qty_available: '10' })],
        rowCount: 1,
      });

      const plan = await repo.planFefoAllocation('c1', 'o1', 'p1', 4, new Date('2026-01-01'));
      expect(plan).toEqual([expect.objectContaining({ batchId: 'only', qty: 4 })]);
    });

    it('should throw INSUFFICIENT_STOCK (InvariantError) when not enough stock', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({
        rows: [batchRow({ qty_available: '2' })],
        rowCount: 1,
      });

      await expect(
        repo.planFefoAllocation('c1', 'o1', 'p1', 5, new Date('2026-01-01')),
      ).rejects.toBeInstanceOf(InvariantError);
    });

    it('should throw INSUFFICIENT_STOCK when no batches available', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rows: [], rowCount: 0 });

      await expect(
        repo.planFefoAllocation('c1', 'o1', 'p1', 1, new Date('2026-01-01')),
      ).rejects.toThrow('INVENTORY.INSUFFICIENT_STOCK');
    });
  });

  describe('postMovements', () => {
    let client: { query: jest.Mock; release: jest.Mock };

    beforeEach(() => {
      client = { query: jest.fn(), release: jest.fn() };
      (mockPool.connect as jest.Mock).mockResolvedValue(client as unknown as PoolClient);
    });

    it('should return empty array for no drafts without touching the pool', async () => {
      const result = await repo.postMovements('c1', []);
      expect(result).toEqual([]);
      expect(mockPool.connect).not.toHaveBeenCalled();
    });

    it('should apply an inbound movement and commit', async () => {
      const draft: MovementDraft = {
        outletId: 'o1',
        batchId: 'b1',
        productId: 'p1',
        movementType: 'PURCHASE',
        qty: 5,
      };

      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [batchRow({ qty_available: '10' })], rowCount: 1 }) // SELECT FOR UPDATE
        .mockResolvedValueOnce({ rowCount: 1 }) // UPDATE batch
        .mockResolvedValueOnce({
          rows: [
            {
              id: 'm1', company_id: 'c1', outlet_id: 'o1', batch_id: 'b1', product_id: 'p1',
              movement_type: 'PURCHASE', qty: '5', before_qty: '10', after_qty: '15',
              source_document_type: null, source_document_id: null, notes: null,
              user_id: null, created_at: new Date(),
            },
          ],
          rowCount: 1,
        }) // INSERT movement
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.postMovements('c1', [draft]);

      expect(result).toHaveLength(1);
      expect(result[0].afterQty).toBe(15);
      expect(client.query).toHaveBeenCalledWith('COMMIT');
      expect(client.release).toHaveBeenCalled();
    });

    it('should rollback and throw INSUFFICIENT_STOCK when outbound exceeds balance', async () => {
      const draft: MovementDraft = {
        outletId: 'o1',
        batchId: 'b1',
        productId: 'p1',
        movementType: 'SALE',
        qty: 20,
      };

      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [batchRow({ qty_available: '10' })], rowCount: 1 }) // SELECT FOR UPDATE
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.postMovements('c1', [draft])).rejects.toThrow(
        'INVENTORY.INSUFFICIENT_STOCK',
      );
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
      expect(client.release).toHaveBeenCalled();
    });

    it('should rollback and throw NotFoundError when batch missing', async () => {
      const draft: MovementDraft = {
        outletId: 'o1', batchId: 'x', productId: 'p1', movementType: 'PURCHASE', qty: 1,
      };

      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // SELECT FOR UPDATE -> not found
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.postMovements('c1', [draft])).rejects.toBeInstanceOf(NotFoundError);
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });

    it('should translate duplicate source key (23505) into DUPLICATE_MOVEMENT_SOURCE', async () => {
      const draft: MovementDraft = {
        outletId: 'o1', batchId: 'b1', productId: 'p1', movementType: 'PURCHASE', qty: 1,
        sourceDocumentType: 'GOODS_RECEIPT', sourceDocumentId: 'gr1',
      };

      const dupErr = Object.assign(new Error('dup'), { code: '23505' });
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [batchRow()], rowCount: 1 }) // SELECT FOR UPDATE
        .mockResolvedValueOnce({ rowCount: 1 }) // UPDATE
        .mockRejectedValueOnce(dupErr) // INSERT -> conflict
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.postMovements('c1', [draft])).rejects.toThrow(
        'INVENTORY.DUPLICATE_MOVEMENT_SOURCE',
      );
    });
  });
});

import { OutletRepositoryPostgres } from '../OutletRepositoryPostgres';
import { Pool } from 'pg';
import { Outlet } from '../../../Domains/outlets/entities/Outlet';
import { NotFoundError } from '../../../Commons/exceptions/NotFoundError';
import { ConflictError } from '../../../Commons/exceptions/ConflictError';

const mockPool = { query: jest.fn() } as unknown as Pool;

const outletRow = {
  id: 'outlet-uuid',
  company_id: 'company-uuid',
  code: 'OUT-001',
  name: 'Outlet A',
  address: null,
  phone: null,
  is_active: true,
  created_at: new Date(),
  updated_at: new Date(),
};

describe('OutletRepositoryPostgres', () => {
  let repo: OutletRepositoryPostgres;

  beforeEach(() => {
    jest.clearAllMocks();
    repo = new OutletRepositoryPostgres(mockPool);
  });

  describe('addOutlet', () => {
    it('should return an Outlet on success', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rows: [outletRow], rowCount: 1 });

      const result = await repo.addOutlet(
        { code: 'OUT-001', name: 'Outlet A', address: null, phone: null },
        'company-uuid',
      );

      expect(result).toBeInstanceOf(Outlet);
      expect(result.code).toBe('OUT-001');
    });

    it('should translate a unique violation into OUTLET.CODE_DUPLICATE', async () => {
      (mockPool.query as jest.Mock).mockRejectedValue({ code: '23505' });

      await expect(
        repo.addOutlet(
          { code: 'OUT-001', name: 'Outlet A', address: null, phone: null },
