describe('ProductionOrderRepositoryPostgres (instant-complete)', () => {
  let repo: ProductionOrderRepositoryPostgres;
  let client: { query: jest.Mock; release: jest.Mock };

  beforeEach(() => {
    jest.clearAllMocks();
    repo = new ProductionOrderRepositoryPostgres(mockPool);
    client = { query: jest.fn(), release: jest.fn() };
    (mockPool.connect as jest.Mock).mockResolvedValue(client as unknown as PoolClient);
  });

  describe('createInstant', () => {
    it('should resolve recipe, backflush FEFO, create finished batch and COMPLETE', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET SERIALIZABLE
        .mockResolvedValueOnce({
          rows: [{ id: 'recipe-1', product_id: 'finished-1', yield_qty: '20', status: 'ACTIVE' }],
          rowCount: 1,
        }) // resolve recipe by id
        .mockResolvedValueOnce({ rows: [{ count: '0' }] }) // generate number
        .mockResolvedValueOnce({ rows: [header()], rowCount: 1 }) // insert header COMPLETED
        .mockResolvedValueOnce({
          rows: [{ id: 'ri-1', ingredient_product_id: 'ing-1', qty: '500', loss_percentage: '0' }],
          rowCount: 1,
        }) // recipe items (need 500 * scale 2 = 1000)
        .mockResolvedValueOnce({
          rows: [
            { id: 'batch-1', batch_number: 'B1', lot_key: '', expired_date: new Date('2026-10-01'), qty_available: '1000' },
          ],
          rowCount: 1,
        }) // FEFO batches
        .mockResolvedValueOnce(undefined) // UPDATE batch balance
        .mockResolvedValueOnce(undefined) // INSERT PRODUCTION_CONSUME movement
        .mockResolvedValueOnce(undefined) // INSERT production_order_materials
        .mockResolvedValueOnce({ rows: [{ id: 'fg-batch' }], rowCount: 1 }) // INSERT finished batch
        .mockResolvedValueOnce(undefined) // INSERT PRODUCTION_RESULT movement
        .mockResolvedValueOnce(undefined) // INSERT production_order_results
        .mockResolvedValueOnce(undefined) // UPDATE header result_batch_id
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // load materials
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // load results
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.createInstant('c1', baseData);

      expect(result.status).toBe('COMPLETED');
      expect(result.productionNumber).toBe('PRD-2026-000001');
      expect(result.scaleFactor).toBe(2);
      expect(result.resultBatchId).toBe('fg-batch');
      expect(client.query).toHaveBeenCalledWith('COMMIT');
    });

    it('should NOT create a finished batch when actualQty is 0 (full waste)', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET SERIALIZABLE
        .mockResolvedValueOnce({
          rows: [{ id: 'recipe-1', product_id: 'finished-1', yield_qty: '20', status: 'ACTIVE' }],
          rowCount: 1,
        }) // resolve recipe
        .mockResolvedValueOnce({ rows: [{ count: '0' }] }) // generate number
        .mockResolvedValueOnce({
          rows: [header({ actual_qty: '0', waste_qty: '40', result_expired_date: null })],
          rowCount: 1,
        }) // insert header COMPLETED
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // recipe items (none for brevity)
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // load materials
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // load results
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.createInstant('c1', {
        ...baseData,
        actualQty: 0,
        wasteQty: 40,
        resultExpiredDate: null,
      });

      expect(result.status).toBe('COMPLETED');
      expect(result.resultBatchId).toBeNull();
      expect(client.query).toHaveBeenCalledWith('COMMIT');
    });

    it('should reject when the resolved recipe is not ACTIVE', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET SERIALIZABLE
        .mockResolvedValueOnce({
          rows: [{ id: 'recipe-1', product_id: 'finished-1', yield_qty: '20', status: 'DRAFT' }],
          rowCount: 1,
        }) // resolve recipe
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.createInstant('c1', baseData)).rejects.toBeInstanceOf(InvariantError);
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });

    it('should throw NO_ACTIVE_RECIPE when resolving by product finds none', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET SERIALIZABLE
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // resolve active by product
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(
        repo.createInstant('c1', { ...baseData, recipeId: null, productId: 'finished-1' }),
      ).rejects.toThrow('RECIPE.NO_ACTIVE_RECIPE');
    });

    it('should throw INSUFFICIENT_STOCK when FEFO cannot cover the requirement', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET SERIALIZABLE
        .mockResolvedValueOnce({
          rows: [{ id: 'recipe-1', product_id: 'finished-1', yield_qty: '20', status: 'ACTIVE' }],
          rowCount: 1,
        }) // resolve recipe
        .mockResolvedValueOnce({ rows: [{ count: '0' }] }) // generate number
        .mockResolvedValueOnce({ rows: [header()], rowCount: 1 }) // insert header
        .mockResolvedValueOnce({
          rows: [{ id: 'ri-1', ingredient_product_id: 'ing-1', qty: '500', loss_percentage: '0' }],
          rowCount: 1,
        }) // recipe items (need 1000)
        .mockResolvedValueOnce({
          rows: [
            { id: 'batch-1', batch_number: 'B1', lot_key: '', expired_date: new Date('2026-10-01'), qty_available: '100' },
          ],
          rowCount: 1,
        }) // FEFO: only 100 available
        .mockResolvedValueOnce(undefined) // UPDATE batch balance
        .mockResolvedValueOnce(undefined) // INSERT movement
        .mockResolvedValueOnce(undefined) // INSERT material snapshot
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.createInstant('c1', baseData)).rejects.toThrow(
        'INVENTORY.INSUFFICIENT_STOCK',
      );
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });
  });

  describe('getById', () => {
    it('should throw NotFoundError when missing', async () => {
      client.query.mockResolvedValueOnce({ rows: [], rowCount: 0 });
      await expect(repo.getById('x', 'c1')).rejects.toBeInstanceOf(NotFoundError);
    });

    it('should load header + materials + results', async () => {
      client.query
        .mockResolvedValueOnce({
          rows: [
            header({
              outlet_name: 'Outlet Utama',
              product_name: 'Roti Coklat',
              recipe_name: 'Resep Roti Coklat',
            }),
          ],
          rowCount: 1,
        }) // header
        .mockResolvedValueOnce({
          rows: [
            {
              id: 'material-1',
              recipe_item_id: 'recipe-item-1',
              product_id: 'ingredient-1',
              product_name: 'Tepung',
              batch_id: 'batch-1',
              batch_number: 'BATCH-001',
              planned_qty: '500',
              qty_consumed: '500',
            },
          ],
          rowCount: 1,
        }) // materials
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }); // results

      const result = await repo.getById('po1', 'c1');
      expect(result.status).toBe('COMPLETED');
      expect(result.outletName).toBe('Outlet Utama');
      expect(result.productName).toBe('Roti Coklat');
      expect(result.recipeName).toBe('Resep Roti Coklat');
      expect(result.materials[0].productName).toBe('Tepung');
      expect(result.materials[0].batchNumber).toBe('BATCH-001');
      const headerQuery = client.query.mock.calls[0][0] as string;
      const materialsQuery = client.query.mock.calls[1][0] as string;
      expect(headerQuery).toContain('AS outlet_name');
      expect(headerQuery).toContain('AS recipe_name');
      expect(materialsQuery).toContain('AS product_name');
      expect(materialsQuery).toContain('b.batch_number');
    });
  });

  describe('list', () => {
    it('should return headers only with total', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [{ count: '1' }] }) // count
        .mockResolvedValueOnce({
          rows: [header({ outlet_name: 'Outlet Utama', product_name: 'Roti Coklat' })],
          rowCount: 1,
        }); // rows

      const result = await repo.list('c1', { limit: 10, offset: 0 });
      expect(result.total).toBe(1);
      expect(result.rows).toHaveLength(1);
      expect(result.rows[0].status).toBe('COMPLETED');
      expect(result.rows[0].outletName).toBe('Outlet Utama');
      expect(result.rows[0].productName).toBe('Roti Coklat');
      const listQuery = (mockPool.query as jest.Mock).mock.calls[1][0] as string;
      expect(listQuery).toContain('AS outlet_name');
      expect(listQuery).toContain('AS product_name');
      expect(listQuery).toContain('p.company_id = production_orders.company_id');
    });
  });

  describe('getProducible', () => {
    const recipeRow = {
      id: 'recipe-1',
      recipe_number: 'RCP-2026-000001',
      name: 'Roti Coklat',
      yield_qty: '20',
      yield_uom_id: 'uom-pcs',
      yield_uom_name: 'Pcs',
    };

    it('should throw NO_ACTIVE_RECIPE when the product has no active recipe', async () => {
      (mockPool.query as jest.Mock).mockResolvedValueOnce({ rows: [], rowCount: 0 }); // recipe lookup

      await expect(repo.getProducible('c1', 'finished-1', 'outlet-1')).rejects.toThrow(
        'RECIPE.NO_ACTIVE_RECIPE',
      );
    });

    it('should compute producibleQty = MIN(floor(available / perUnit)) across ingredients', async () => {
      // Recipe yields 20 finished units per batch.
      // ing-1: base 500, loss 0  -> perUnit = 500/20 = 25; available 1000 -> floor(1000/25) = 40
      // ing-2: base 100, loss 0  -> perUnit = 100/20 = 5;  available 60   -> floor(60/5)   = 12 (limiting)
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [recipeRow], rowCount: 1 }) // recipe
        .mockResolvedValueOnce({
          rows: [
            {
              ingredient_product_id: 'ing-1',
              ingredient_product_name: 'Tepung',
              qty: '500',
              loss_percentage: '0',
              uom_id: 'uom-g',
              uom_name: 'Gram',
            },
            {
              ingredient_product_id: 'ing-2',
              ingredient_product_name: 'Gula',
              qty: '100',
              loss_percentage: '0',
              uom_id: 'uom-g',
              uom_name: 'Gram',
            },
          ],
          rowCount: 2,
        }) // recipe items
        .mockResolvedValueOnce({
          rows: [
            { product_id: 'ing-1', qty_available: '1000' },
            { product_id: 'ing-2', qty_available: '60' },
          ],
          rowCount: 2,
        }); // stock

      const result = await repo.getProducible('c1', 'finished-1', 'outlet-1');

      expect(result.producibleQty).toBe(12);
      expect(result.recipe).toEqual({
        id: 'recipe-1',
        recipeNumber: 'RCP-2026-000001',
        name: 'Roti Coklat',
        yieldQty: 20,
        yieldUomId: 'uom-pcs',
        yieldUomName: 'Pcs',
      });
      const ing1 = result.items.find((i) => i.ingredientProductId === 'ing-1')!;
      const ing2 = result.items.find((i) => i.ingredientProductId === 'ing-2')!;
      expect(ing1.requiredPerUnit).toBe(25);
      expect(ing1.ingredientProductName).toBe('Tepung');
      expect(ing1.uomName).toBe('Gram');
      expect(ing1.availableQty).toBe(1000);
      expect(ing1.isLimiting).toBe(false);
      expect(ing2.requiredPerUnit).toBe(5);
      expect(ing2.isLimiting).toBe(true);
    });

    it('should IGNORE loss% in the per-unit requirement (estimate only)', async () => {
      // ing-1: base 100, loss 25 (ignored) -> perUnit = 100 / 20 = 5; available 100 -> floor(100/5) = 20
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [recipeRow], rowCount: 1 })
        .mockResolvedValueOnce({
          rows: [
            {
              ingredient_product_id: 'ing-1',
              ingredient_product_name: 'Tepung',
              qty: '100',
              loss_percentage: '25',
              uom_id: 'uom-g',
              uom_name: 'Gram',
            },
          ],
          rowCount: 1,
        })
        .mockResolvedValueOnce({
          rows: [{ product_id: 'ing-1', qty_available: '100' }],
          rowCount: 1,
        });

      const result = await repo.getProducible('c1', 'finished-1', 'outlet-1');

      expect(result.items[0].requiredPerUnit).toBe(5);
      expect(result.producibleQty).toBe(20);
    });

    it('maximises producible units: stock 1.8, base/unit 0.2 -> 9 (loss ignored)', async () => {
      // ing-1: base 0.2 per batch, yield 1 -> perUnit = 0.2; stock 1.8 -> floor(1.8/0.2) = 9
      // loss 12.5 would previously yield 8; it is now ignored.
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({
          rows: [{ ...recipeRow, yield_qty: '1' }],
          rowCount: 1,
        })
        .mockResolvedValueOnce({
          rows: [
            {
              ingredient_product_id: 'ing-1',
              ingredient_product_name: 'Tepung',
              qty: '0.2',
              loss_percentage: '12.5',
              uom_id: 'uom-g',
              uom_name: 'Gram',
            },
          ],
          rowCount: 1,
        })
        .mockResolvedValueOnce({
          rows: [{ product_id: 'ing-1', qty_available: '1.8' }],
          rowCount: 1,
        });

      const result = await repo.getProducible('c1', 'finished-1', 'outlet-1');

      expect(result.items[0].requiredPerUnit).toBe(0.2);
      expect(result.producibleQty).toBe(9);
    });

    it('should return producibleQty 0 when an ingredient has zero stock', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [recipeRow], rowCount: 1 })
        .mockResolvedValueOnce({
          rows: [
            {
              ingredient_product_id: 'ing-1',
              ingredient_product_name: 'Tepung',
              qty: '500',
              loss_percentage: '0',
              uom_id: 'uom-g',
              uom_name: 'Gram',
            },
          ],
          rowCount: 1,
        })
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }); // no stock at all

      const result = await repo.getProducible('c1', 'finished-1', 'outlet-1');

      expect(result.producibleQty).toBe(0);
      expect(result.items[0].availableQty).toBe(0);
      expect(result.items[0].isLimiting).toBe(true);
    });

    it('should return producibleQty 0 for an empty recipe (no ingredient lines)', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [recipeRow], rowCount: 1 })
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // no items
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }); // no stock

      const result = await repo.getProducible('c1', 'finished-1', 'outlet-1');

      expect(result.producibleQty).toBe(0);
      expect(result.items).toHaveLength(0);
    });
  });
});

import { Pool, PoolClient } from 'pg';
import { PurchaseRequestRepositoryPostgres } from '../PurchaseRequestRepositoryPostgres';
import { NotFoundError } from '../../../Commons/exceptions/NotFoundError';
import { InvariantError } from '../../../Commons/exceptions/InvariantError';

const mockPool = { query: jest.fn(), connect: jest.fn() } as unknown as Pool;

function header(over: Record<string, unknown> = {}) {
  return {
    id: 'pr1',
    company_id: 'c1',
    pr_number: 'PR-OUT001-2026-000001',
    requestor_id: 'u1',
    destination_outlet_id: 'outlet-1',
    expected_date: new Date('2026-10-05'),
    total_estimated_amount: '16000',
    status: 'DRAFT',
    notes: null,
    approved_by: null,
    approved_at: null,
    created_by: 'u1',
    updated_by: null,
    created_at: new Date(),
    updated_at: new Date(),
    ...over,
  };
}

function itemRow(over: Record<string, unknown> = {}) {
  return {
    id: 'item-1',
    product_id: 'prod-1',
    quantity: '3',
    uom_id: 'uom-1',
    estimated_price: '5000',
    subtotal: '15000',
    ...over,
  };
}

function logRow(over: Record<string, unknown> = {}) {
  return {
    id: 'log-1',
    from_status: null,
    to_status: 'DRAFT',
    actor_id: 'u1',
    actor_name: 'Budi Owner',
    note: null,
    created_at: new Date(),
    ...over,
  };
}

function commentRow(over: Record<string, unknown> = {}) {
  return {
    id: 'cmt-1',
    category: 'INTERNAL',
    body: 'Please review the quantities.',
    author_id: 'u1',
    author_name: 'Budi Owner',
    created_at: new Date(),
    ...over,
  };
}

const newData = {
  destinationOutletId: 'outlet-1',
  expectedDate: '2026-10-05',
  notes: null,
  totalEstimatedAmount: 16000,
  items: [
    { productId: 'prod-1', quantity: 3, uomId: 'uom-1', estimatedPrice: 5000, subtotal: 15000 },
    { productId: 'prod-2', quantity: 1, uomId: 'uom-1', estimatedPrice: 1000, subtotal: 1000 },
  ],
};

describe('PurchaseRequestRepositoryPostgres', () => {
  let repo: PurchaseRequestRepositoryPostgres;
  let client: { query: jest.Mock; release: jest.Mock };

  beforeEach(() => {
    jest.clearAllMocks();
    repo = new PurchaseRequestRepositoryPostgres(mockPool);
    client = { query: jest.fn(), release: jest.fn() };
    (mockPool.connect as jest.Mock).mockResolvedValue(client as unknown as PoolClient);
  });

  describe('createDraft', () => {
    it('should generate a PR-{outletCode}-YYYY-NNNNNN number, insert items and a DRAFT log', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [{ code: 'OUT001' }], rowCount: 1 }) // resolve outlet code
        .mockResolvedValueOnce({ rows: [{ max_serial: null }], rowCount: 1 }) // number lookup
        .mockResolvedValueOnce({ rows: [header()], rowCount: 1 }) // insert header
        .mockResolvedValueOnce({ rowCount: 1 }) // insert item 1
        .mockResolvedValueOnce({ rowCount: 1 }) // insert item 2
        .mockResolvedValueOnce({ rowCount: 1 }) // insert log
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // load items
        .mockResolvedValueOnce({ rows: [logRow()], rowCount: 1 }) // load logs
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.createDraft('c1', 'u1', newData);

      expect(result.status).toBe('DRAFT');
      expect(result.prNumber).toBe('PR-OUT001-2026-000001');
      // header insert receives the generated number as 2nd param
      const insertHeaderCall = client.query.mock.calls[3];
      expect(insertHeaderCall[1][1]).toMatch(/^PR-OUT001-\d{4}-000001$/);
      // a null -> DRAFT log row is written
      const insertLogCall = client.query.mock.calls[6];
      expect(insertLogCall[0]).toContain('purchase_request_status_logs');
      expect(insertLogCall[1]).toEqual(['pr1', null, 'DRAFT', 'u1', null]);
      expect(client.query).toHaveBeenCalledWith('COMMIT');
    });

    it('should compute the next serial from the max existing serial', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [{ code: 'OUT001' }], rowCount: 1 }) // outlet code
        .mockResolvedValueOnce({ rows: [{ max_serial: '5' }], rowCount: 1 }) // number lookup
        .mockResolvedValueOnce({ rows: [header({ pr_number: 'PR-OUT001-2026-000006' })], rowCount: 1 })
        .mockResolvedValueOnce({ rowCount: 1 })
        .mockResolvedValueOnce({ rowCount: 1 })
        .mockResolvedValueOnce({ rowCount: 1 })
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 })
        .mockResolvedValueOnce({ rows: [logRow()], rowCount: 1 })
        .mockResolvedValueOnce(undefined);

      await repo.createDraft('c1', 'u1', newData);
      const insertHeaderCall = client.query.mock.calls[3];
      expect(insertHeaderCall[1][1]).toBe('PR-OUT001-2026-000006');
    });

    it('should rollback and throw NotFoundError when the outlet is not in the company', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }); // outlet code lookup -> none

      await expect(repo.createDraft('c1', 'u1', newData)).rejects.toBeInstanceOf(NotFoundError);
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });
  });

  describe('updateDraft', () => {
    it('should reject when the PR is not in an editable status', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [header({ status: 'SUBMITTED' })], rowCount: 1 }); // lock header

      await expect(repo.updateDraft('pr1', 'c1', 'u1', newData)).rejects.toBeInstanceOf(
        InvariantError,
      );
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });

    it('should log REJECTED -> DRAFT when editing a rejected PR', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [header({ status: 'REJECTED' })], rowCount: 1 }) // lock header
        .mockResolvedValueOnce({ rows: [header({ status: 'DRAFT' })], rowCount: 1 }) // update header
        .mockResolvedValueOnce({ rowCount: 2 }) // delete items
        .mockResolvedValueOnce({ rowCount: 1 }) // insert item 1
        .mockResolvedValueOnce({ rowCount: 1 }) // insert item 2
        .mockResolvedValueOnce({ rowCount: 1 }) // insert REJECTED->DRAFT log
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // load items
        .mockResolvedValueOnce({ rows: [logRow()], rowCount: 1 }) // load logs
        .mockResolvedValueOnce(undefined); // COMMIT

      await repo.updateDraft('pr1', 'c1', 'u1', newData);
      const logCall = client.query.mock.calls[6];
      expect(logCall[1]).toEqual([
        'pr1',
        'REJECTED',
        'DRAFT',
        'u1',
        'Diperbarui dan dikembalikan ke draft',
      ]);
    });

    it('should throw NotFoundError when PR does not exist', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }); // lock header -> none

      await expect(repo.updateDraft('pr1', 'c1', 'u1', newData)).rejects.toBeInstanceOf(
        NotFoundError,
      );
    });
  });

  describe('status transitions', () => {
    it('submit: DRAFT -> SUBMITTED writes a log and commits', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [header({ status: 'DRAFT' })], rowCount: 1 }) // lock
        .mockResolvedValueOnce({ rows: [header({ status: 'SUBMITTED' })], rowCount: 1 }) // update
        .mockResolvedValueOnce({ rowCount: 1 }) // insert log
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // items
        .mockResolvedValueOnce({ rows: [logRow({ to_status: 'SUBMITTED' })], rowCount: 1 }) // logs
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.submit('pr1', 'c1', 'u1');
      expect(result.status).toBe('SUBMITTED');
      const logCall = client.query.mock.calls[3];
      expect(logCall[1]).toEqual(['pr1', 'DRAFT', 'SUBMITTED', 'u1', null]);
    });

    it('approve: rejects an invalid transition from DRAFT', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [header({ status: 'DRAFT' })], rowCount: 1 }); // lock

      await expect(repo.approve('pr1', 'c1', 'u1', null)).rejects.toBeInstanceOf(InvariantError);
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });

    it('approve: SUBMITTED -> APPROVED sets approved_by/at and logs', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [header({ status: 'SUBMITTED' })], rowCount: 1 }) // lock
        .mockResolvedValueOnce({ rows: [header({ status: 'APPROVED' })], rowCount: 1 }) // update
        .mockResolvedValueOnce({ rowCount: 1 }) // log
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // items
        .mockResolvedValueOnce({ rows: [logRow({ to_status: 'APPROVED' })], rowCount: 1 }) // logs
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.approve('pr1', 'c1', 'u1', 'ok');
      expect(result.status).toBe('APPROVED');
      const updateCall = client.query.mock.calls[2];
      expect(updateCall[0]).toContain('approved_by = $2');
      expect(updateCall[0]).toContain('approved_at = NOW()');
    });

    it('cancel: DRAFT -> CANCELLED is terminal but NOT soft-deleted (Opsi A), logs and stays visible', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [header({ status: 'DRAFT' })], rowCount: 1 }) // lock
        .mockResolvedValueOnce({ rows: [header({ status: 'CANCELLED' })], rowCount: 1 }) // update
        .mockResolvedValueOnce({ rowCount: 1 }) // log
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // items
        .mockResolvedValueOnce({ rows: [logRow({ to_status: 'CANCELLED' })], rowCount: 1 }) // logs
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.cancel('pr1', 'c1', 'u1', null);
      expect(result.status).toBe('CANCELLED');
      const updateCall = client.query.mock.calls[2];
      // Opsi A: cancel must NOT soft-delete; the row stays visible in list.
      expect(updateCall[0]).not.toContain('deleted_at');
      expect(updateCall[0]).not.toContain('deleted_by');
      expect(updateCall[0]).toContain("status = $1");
      // A CANCELLED timeline log is still written.
      const logCall = client.query.mock.calls[3];
      expect(logCall[1]).toEqual(['pr1', 'DRAFT', 'CANCELLED', 'u1', null]);
    });
  });

  describe('getById', () => {
    it('should throw NotFoundError when the PR is missing or soft-deleted', async () => {
