  describe('list', () => {
    it('should filter out soft-deleted rows and paginate', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [{ count: '1' }], rowCount: 1 }) // count
        .mockResolvedValueOnce({ rows: [header()], rowCount: 1 }) // headers
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // items for row
        .mockResolvedValueOnce({ rows: [logRow()], rowCount: 1 }); // logs for row

      const result = await repo.list('c1', { limit: 10, offset: 0 });
      expect(result.total).toBe(1);
      expect(result.rows).toHaveLength(1);
      const countCall = (mockPool.query as jest.Mock).mock.calls[0];
      expect(countCall[0]).toContain('deleted_at IS NULL');
    });

    it('orderable=true restricts to APPROVED PRs with remaining orderable qty (picker)', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [{ count: '1' }], rowCount: 1 }) // count
        .mockResolvedValueOnce({ rows: [header({ status: 'APPROVED' })], rowCount: 1 }) // headers
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // items
        .mockResolvedValueOnce({ rows: [logRow({ to_status: 'APPROVED' })], rowCount: 1 }); // logs

      const result = await repo.list('c1', { limit: 10, offset: 0, orderable: true });
      expect(result.total).toBe(1);

      const countSql = String((mockPool.query as jest.Mock).mock.calls[0][0]);
      expect(countSql).toContain("status = 'APPROVED'");
      expect(countSql).toContain('EXISTS (');
      expect(countSql).toContain('purchase_order_items');
      expect(countSql).toContain("po.status IN ('DRAFT','SUBMITTED','APPROVED')");
      expect(countSql).toContain('deleted_at IS NULL');
    });

    it('does NOT add the orderable predicate on a normal list (default contract unchanged)', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [{ count: '0' }], rowCount: 1 }) // count
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }); // headers

      await repo.list('c1', { limit: 10, offset: 0 });
      const countSql = String((mockPool.query as jest.Mock).mock.calls[0][0]);
      expect(countSql).not.toContain('EXISTS (');
      expect(countSql).not.toContain("status = 'APPROVED'");
    });
  });
});

import { Pool, PoolClient } from 'pg';
import { PurchaseReturnRepositoryPostgres } from '../PurchaseReturnRepositoryPostgres';
import { NotFoundError } from '../../../Commons/exceptions/NotFoundError';
import { InvariantError } from '../../../Commons/exceptions/InvariantError';
import { NewPurchaseReturnData } from '../../../Domains/purchase-returns/PurchaseReturnRepository';

/**
 * Unit tests for PurchaseReturnRepositoryPostgres. The pg client/pool is mocked
 * and sequenced by call order, mirroring GoodsReceiptRepositoryPostgres.test /
 * StockTransferRepositoryPostgres style.
 *
 * Coverage:
 *   - createDraft: generates number, inserts header/items/log, returns entity.
 *   - getReturnable: derives returnable from posted PURCHASE movements minus
 *     completed + submitted; rejects a non-COMPLETED GR.
 *   - submit: reserves (status flip) and rejects returnQuantity > returnable.
 *   - complete: posts RETURN reversal (happy), rejects INSUFFICIENT_STOCK, and
 *     is idempotent for an already-COMPLETED return.
 */

const mockPool = { query: jest.fn(), connect: jest.fn() } as unknown as Pool;

function headerRow(over: Record<string, unknown> = {}) {
  return {
    id: 'ret1',
    company_id: 'c1',
    return_number: 'RTN-2026-000001',
    goods_receipt_id: 'gr1',
    purchase_order_id: 'po1',
    supplier_id: 'sup1',
    supplier_code: 'SUP-01',
    supplier_name: 'Vendor A',
    outlet_id: 'o1',
    outlet_code: 'OUT-01',
    outlet_name: 'Outlet A',
    return_date: new Date('2026-10-10'),
    status: 'DRAFT',
    notes: null,
    created_by: 'u1',
    updated_by: null,
    submitted_by: null,
    completed_by: null,
    cancelled_by: null,
    submitted_at: null,
    completed_at: null,
    cancelled_at: null,
    created_at: new Date('2026-10-10'),
    updated_at: new Date('2026-10-10'),
    ...over,
  };
}

function itemRow(over: Record<string, unknown> = {}) {
  return {
    id: 'rti1',
    goods_receipt_item_id: 'gri1',
    source_batch_id: 'batch1',
    source_movement_id: 'mov1',
    product_id: 'prod1',
    product_sku: 'SKU-1',
    product_name: 'Flour',
    uom_id: 'uom1',
    uom_code: 'KG',
    uom_name: 'Kilogram',
    batch_number: 'B-001',
    lot_number: null,
    expired_date: new Date('2026-12-31'),
    posted_accepted_quantity: '10',
    previously_returned_quantity: '0',
    return_quantity: '4',
    reason: 'DAMAGED',
    reason_description: null,
    ...over,
  };
}

const newData: NewPurchaseReturnData = {
  goodsReceiptId: 'gr1',
  purchaseOrderId: 'po1',
  supplierId: 'sup1',
  supplierCode: 'SUP-01',
  supplierName: 'Vendor A',
  outletId: 'o1',
  outletCode: 'OUT-01',
  outletName: 'Outlet A',
  returnDate: '2026-10-10',
  notes: null,
  items: [
    {
      goodsReceiptItemId: 'gri1',
      sourceBatchId: 'batch1',
      sourceMovementId: 'mov1',
      productId: 'prod1',
      productSku: 'SKU-1',
      productName: 'Flour',
      uomId: 'uom1',
      uomCode: 'KG',
      uomName: 'Kilogram',
      batchNumber: 'B-001',
      lotNumber: null,
      expiredDate: '2026-12-31',
      postedAcceptedQuantity: 10,
      previouslyReturnedQuantity: 0,
      returnQuantity: 4,
      reason: 'DAMAGED',
      reasonDescription: null,
    },
  ],
};

describe('PurchaseReturnRepositoryPostgres', () => {
  let repo: PurchaseReturnRepositoryPostgres;
  let client: { query: jest.Mock; release: jest.Mock };

  beforeEach(() => {
    jest.clearAllMocks();
    client = { query: jest.fn(), release: jest.fn() };
    (mockPool.connect as jest.Mock).mockResolvedValue(client as unknown as PoolClient);
    repo = new PurchaseReturnRepositoryPostgres(mockPool);
  });

  describe('createDraft', () => {
    it('generates a number, inserts header + items + log, returns the entity', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [{ max_serial: null }], rowCount: 1 }) // _generateNumber
        .mockResolvedValueOnce({ rows: [headerRow()], rowCount: 1 }) // INSERT header
        .mockResolvedValueOnce(undefined) // INSERT item
        .mockResolvedValueOnce(undefined) // INSERT log
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // _loadItems
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.createDraft('c1', 'u1', newData);

      expect(result.returnNumber).toBe('RTN-2026-000001');
      expect(result.status).toBe('DRAFT');
      expect(result.items).toHaveLength(1);
      expect(result.items[0].returnQuantity).toBe(4);
      expect(client.query).toHaveBeenCalledWith('COMMIT');
    });

    it('rolls back on error', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [{ max_serial: null }], rowCount: 1 }) // number
        .mockRejectedValueOnce(new Error('boom')) // INSERT header fails
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.createDraft('c1', 'u1', newData)).rejects.toThrow('boom');
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
      expect(client.release).toHaveBeenCalled();
    });
  });

  describe('getReturnable', () => {
    it('derives returnable = posted − completed − submitted per GR item', async () => {
      (mockPool.query as jest.Mock)
        // 1. GR status check
        .mockResolvedValueOnce({ rows: [{ status: 'COMPLETED' }], rowCount: 1 })
        // 2. posted PURCHASE movements
        .mockResolvedValueOnce({
          rows: [
            {
              movement_id: 'mov1',
              posted_qty: '10',
              batch_id: 'batch1',
              goods_receipt_item_id: 'gri1',
              product_id: 'prod1',
              product_sku: 'SKU-1',
              product_name: 'Flour',
              uom_id: 'uom1',
              uom_code: 'KG',
              uom_name: 'Kilogram',
              batch_number: 'B-001',
              lot_number: null,
              expired_date: new Date('2026-12-31'),
            },
          ],
          rowCount: 1,
        })
        // 3. completed sum
        .mockResolvedValueOnce({ rows: [{ goods_receipt_item_id: 'gri1', total: '3' }], rowCount: 1 })
        // 4. submitted sum
        .mockResolvedValueOnce({ rows: [{ goods_receipt_item_id: 'gri1', total: '2' }], rowCount: 1 });

      const lines = await repo.getReturnable('gr1', 'c1');

      expect(lines).toHaveLength(1);
      expect(lines[0].postedAcceptedQuantity).toBe(10);
      expect(lines[0].completedReturnQuantity).toBe(3);
      expect(lines[0].submittedReturnQuantity).toBe(2);
      expect(lines[0].returnableQuantity).toBe(5); // 10 - 3 - 2
      expect(lines[0].sourceMovementId).toBe('mov1');
      expect(lines[0].sourceBatchId).toBe('batch1');
      expect(lines[0].uomCode).toBe('KG');
      expect(lines[0].uomName).toBe('Kilogram');
    });

    it('throws NotFoundError when the GR is missing/foreign', async () => {
      (mockPool.query as jest.Mock).mockResolvedValueOnce({ rows: [], rowCount: 0 });
      await expect(repo.getReturnable('grX', 'c1')).rejects.toBeInstanceOf(NotFoundError);
    });

    it('rejects a non-COMPLETED GR', async () => {
      (mockPool.query as jest.Mock).mockResolvedValueOnce({
        rows: [{ status: 'DRAFT' }],
        rowCount: 1,
      });
      await expect(repo.getReturnable('gr1', 'c1')).rejects.toThrow(
        'PURCHASE_RETURN.GOODS_RECEIPT_NOT_COMPLETED',
      );
    });
  });

  describe('submit', () => {
    it('reserves (DRAFT -> SUBMITTED) when returnQuantity <= returnable', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [headerRow()], rowCount: 1 }) // header FOR UPDATE
        .mockResolvedValueOnce({ rows: [itemRow({ return_quantity: '4' })], rowCount: 1 }) // _loadItems
        // _deriveReturnableForReturn: posted movements
        .mockResolvedValueOnce({ rows: [{ goods_receipt_item_id: 'gri1', posted_qty: '10' }], rowCount: 1 })
        // completed sum
        .mockResolvedValueOnce({ rows: [], rowCount: 0 })
        // submitted sum (excluding this return)
        .mockResolvedValueOnce({ rows: [], rowCount: 0 })
        .mockResolvedValueOnce({ rows: [headerRow({ status: 'SUBMITTED' })], rowCount: 1 }) // UPDATE
        .mockResolvedValueOnce(undefined) // INSERT log
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // _loadItems
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.submit('ret1', 'c1', 'u1', null);
      expect(result.status).toBe('SUBMITTED');
      expect(client.query).toHaveBeenCalledWith('COMMIT');
    });

    it('rejects when returnQuantity exceeds returnable', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [headerRow()], rowCount: 1 }) // header
        .mockResolvedValueOnce({ rows: [itemRow({ return_quantity: '8' })], rowCount: 1 }) // items
        // posted 10, completed 3, submitted(excl) 0 -> returnable 7; 8 > 7
        .mockResolvedValueOnce({ rows: [{ goods_receipt_item_id: 'gri1', posted_qty: '10' }], rowCount: 1 })
        .mockResolvedValueOnce({ rows: [{ goods_receipt_item_id: 'gri1', total: '3' }], rowCount: 1 })
        .mockResolvedValueOnce({ rows: [], rowCount: 0 })
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.submit('ret1', 'c1', 'u1', null)).rejects.toThrow(
        'PURCHASE_RETURN.RETURN_QTY_EXCEEDS_RETURNABLE',
      );
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });

    it('rejects an invalid status transition (e.g. COMPLETED)', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [headerRow({ status: 'COMPLETED' })], rowCount: 1 }) // header
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.submit('ret1', 'c1', 'u1', null)).rejects.toThrow(
        'PURCHASE_RETURN.INVALID_STATUS_TRANSITION',
      );
    });
  });

  describe('complete', () => {
    it('posts the RETURN reversal (SUBMITTED -> COMPLETED), decrementing the batch', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [headerRow({ status: 'SUBMITTED' })], rowCount: 1 }) // header
        .mockResolvedValueOnce({ rows: [itemRow({ return_quantity: '4' })], rowCount: 1 }) // _loadItems
        .mockResolvedValueOnce({ rows: [{ qty_available: '10' }], rowCount: 1 }) // batch FOR UPDATE
        .mockResolvedValueOnce(undefined) // UPDATE batch
        .mockResolvedValueOnce(undefined) // INSERT movement
        .mockResolvedValueOnce({ rows: [headerRow({ status: 'COMPLETED' })], rowCount: 1 }) // UPDATE header
        .mockResolvedValueOnce(undefined) // INSERT log
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // _loadItems
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.complete('ret1', 'c1', 'u1', null);

      expect(result.status).toBe('COMPLETED');
      const sqls = client.query.mock.calls.map((c) => String(c[0]));
      expect(sqls.some((s) => s.includes("'RETURN'"))).toBe(true);
      expect(sqls.some((s) => s.includes("'PURCHASE_RETURN'"))).toBe(true);
      expect(client.query).toHaveBeenCalledWith('COMMIT');
    });

    it('rejects INVENTORY.INSUFFICIENT_STOCK when the batch balance is below the return qty', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [headerRow({ status: 'SUBMITTED' })], rowCount: 1 }) // header
        .mockResolvedValueOnce({ rows: [itemRow({ return_quantity: '8' })], rowCount: 1 }) // items
        .mockResolvedValueOnce({ rows: [{ qty_available: '5' }], rowCount: 1 }) // batch has only 5
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.complete('ret1', 'c1', 'u1', null)).rejects.toThrow(
        'INVENTORY.INSUFFICIENT_STOCK',
      );
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });

    it('is idempotent: an already-COMPLETED return returns unchanged without posting', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [headerRow({ status: 'COMPLETED' })], rowCount: 1 }) // header
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // _loadItems
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.complete('ret1', 'c1', 'u1', null);
      expect(result.status).toBe('COMPLETED');
      const sqls = client.query.mock.calls.map((c) => String(c[0]));
      expect(sqls.some((s) => s.includes('inventory_movements'))).toBe(false);
    });

    it('maps a duplicate source key (23505) to INVENTORY.DUPLICATE_MOVEMENT_SOURCE', async () => {
      const dupErr = Object.assign(new Error('dup'), { code: '23505' });
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [headerRow({ status: 'SUBMITTED' })], rowCount: 1 }) // header
        .mockResolvedValueOnce({ rows: [itemRow({ return_quantity: '4' })], rowCount: 1 }) // items
        .mockResolvedValueOnce({ rows: [{ qty_available: '10' }], rowCount: 1 }) // batch
        .mockResolvedValueOnce(undefined) // UPDATE batch
        .mockRejectedValueOnce(dupErr) // INSERT movement raises 23505
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.complete('ret1', 'c1', 'u1', null)).rejects.toThrow(
        'INVENTORY.DUPLICATE_MOVEMENT_SOURCE',
      );
    });
  });

  describe('cancel', () => {
    it('cancels a SUBMITTED return (releases reservation), stays visible', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [headerRow({ status: 'SUBMITTED' })], rowCount: 1 }) // header
        .mockResolvedValueOnce({ rows: [headerRow({ status: 'CANCELLED' })], rowCount: 1 }) // UPDATE
        .mockResolvedValueOnce(undefined) // INSERT log
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }) // _loadItems
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // _loadLogs
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.cancel('ret1', 'c1', 'u1', 'wrong vendor');
      expect(result.status).toBe('CANCELLED');
      // Opsi A: the cancel UPDATE flips status but does NOT set deleted_at.
      const updateSql = client.query.mock.calls
        .map((c) => String(c[0]))
        .find((s) => s.includes('UPDATE purchase_returns'));
      expect(updateSql).toBeDefined();
      expect(updateSql).toContain("status = 'CANCELLED'");
      expect(updateSql).not.toContain('deleted_at');
    });

    it('rejects cancelling a COMPLETED return', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [headerRow({ status: 'COMPLETED' })], rowCount: 1 }) // header
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.cancel('ret1', 'c1', 'u1', null)).rejects.toBeInstanceOf(InvariantError);
    });
  });
});

import { RoleRepositoryPostgres } from '../RoleRepositoryPostgres';
import { Pool } from 'pg';
import { Role } from '../../../Domains/roles/entities/Role';
import { NotFoundError } from '../../../Commons/exceptions/NotFoundError';

const mockPool = { query: jest.fn() } as unknown as Pool;

const roleRow = {
  id: 'role-uuid',
  company_id: 'company-uuid',
  code: 'KASIR',
  name: 'Kasir',
  description: null,
  is_active: true,
};

describe('RoleRepositoryPostgres', () => {
  let repo: RoleRepositoryPostgres;

  beforeEach(() => {
    jest.clearAllMocks();
    repo = new RoleRepositoryPostgres(mockPool);
  });

  describe('getRolesByCompanyId', () => {
    it('should map rows to Role entities', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rows: [roleRow], rowCount: 1 });

      const roles = await repo.getRolesByCompanyId('company-uuid');
      expect(roles).toHaveLength(1);
      expect(roles[0]).toBeInstanceOf(Role);
      expect(roles[0].code).toBe('KASIR');
    });
  });

  describe('getRoleByIdAndCompany', () => {
    it('should return the role when it belongs to the company', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rows: [roleRow], rowCount: 1 });

      const role = await repo.getRoleByIdAndCompany('role-uuid', 'company-uuid');
      expect(role.id).toBe('role-uuid');
    });

    it('should throw NotFoundError when the role is foreign or missing', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rows: [], rowCount: 0 });

      await expect(
        repo.getRoleByIdAndCompany('role-uuid', 'other-company'),
      ).rejects.toBeInstanceOf(NotFoundError);
    });
  });

  describe('getRolePermissions', () => {
    it('should return permission codes', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({
        rows: [{ code: 'product.read' }, { code: 'sales.manage' }],
        rowCount: 2,
      });

      const perms = await repo.getRolePermissions('role-uuid');
      expect(perms).toEqual(['product.read', 'sales.manage']);
    });

    it('should return an empty array when the role has no permissions', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rows: [], rowCount: 0 });

      expect(await repo.getRolePermissions('role-uuid')).toEqual([]);
    });
  });

  describe('updateRole', () => {
    it('should update editable fields scoped to the company and return the role', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({
        rows: [{ ...roleRow, name: 'Kasir Utama' }],
        rowCount: 1,
      });

      const role = await repo.updateRole('role-uuid', 'company-uuid', { name: 'Kasir Utama' });

      expect(role.name).toBe('Kasir Utama');
      const [sql, params] = (mockPool.query as jest.Mock).mock.calls[0];
      expect(sql).toContain('UPDATE roles');
      expect(sql).toContain('company_id =');
      expect(params).toContain('role-uuid');
      expect(params).toContain('company-uuid');
    });

    it('should throw NotFoundError when the role is foreign, platform, or missing', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rows: [], rowCount: 0 });

      await expect(
        repo.updateRole('role-uuid', 'other-company', { name: 'X' }),
      ).rejects.toBeInstanceOf(NotFoundError);
    });
  });

  describe('setRolePermissions', () => {
    it('should delete existing then insert resolved permissions in a transaction', async () => {
      const client = {
        query: jest
          .fn()
          .mockResolvedValueOnce(undefined) // BEGIN
          .mockResolvedValueOnce(undefined) // DELETE
          .mockResolvedValueOnce({ rows: [{ id: 'p1' }, { id: 'p2' }] }) // SELECT ids
          .mockResolvedValueOnce(undefined) // INSERT
          .mockResolvedValueOnce(undefined), // COMMIT
        release: jest.fn(),
      };
      (mockPool as unknown as { connect: jest.Mock }).connect = jest
        .fn()
        .mockResolvedValue(client);

      await repo.setRolePermissions('role-uuid', ['sales.manage', 'shift.manage']);

      expect(client.query).toHaveBeenCalledWith('BEGIN');
      expect(client.query).toHaveBeenCalledWith(
        expect.stringContaining('DELETE FROM role_permissions'),
        ['role-uuid'],
      );
      expect(client.query).toHaveBeenCalledWith('COMMIT');
      expect(client.release).toHaveBeenCalled();
    });

    it('should only delete when the new set is empty', async () => {
      const client = {
        query: jest
          .fn()
          .mockResolvedValueOnce(undefined) // BEGIN
          .mockResolvedValueOnce(undefined) // DELETE
          .mockResolvedValueOnce(undefined), // COMMIT
        release: jest.fn(),
      };
      (mockPool as unknown as { connect: jest.Mock }).connect = jest
        .fn()
        .mockResolvedValue(client);

      await repo.setRolePermissions('role-uuid', []);

      expect(client.query).toHaveBeenCalledWith('COMMIT');
      // No INSERT was issued
      const insertCall = client.query.mock.calls.find(
        (c: unknown[]) => typeof c[0] === 'string' && (c[0] as string).includes('INSERT'),
      );
      expect(insertCall).toBeUndefined();
    });

    it('should rollback and rethrow on failure', async () => {
      const client = {
        query: jest
          .fn()
          .mockResolvedValueOnce(undefined) // BEGIN
          .mockRejectedValueOnce(new Error('boom')) // DELETE fails
          .mockResolvedValueOnce(undefined), // ROLLBACK
        release: jest.fn(),
      };
      (mockPool as unknown as { connect: jest.Mock }).connect = jest
        .fn()
        .mockResolvedValue(client);

      await expect(repo.setRolePermissions('role-uuid', ['sales.manage'])).rejects.toThrow('boom');
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
      expect(client.release).toHaveBeenCalled();
    });
  });

  describe('deleteRole', () => {
    it('should delete a company-owned role', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rowCount: 1 });

      await expect(repo.deleteRole('role-uuid', 'company-uuid')).resolves.toBeUndefined();
      const [sql, params] = (mockPool.query as jest.Mock).mock.calls[0];
      expect(sql).toContain('DELETE FROM roles');
      expect(params).toEqual(['role-uuid', 'company-uuid']);
    });

    it('should throw NotFoundError when nothing was deleted (foreign/platform/missing)', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rowCount: 0 });

      await expect(repo.deleteRole('role-uuid', 'other-company')).rejects.toBeInstanceOf(
        NotFoundError,
      );
    });
  });

  describe('countUsersUsingRole', () => {
    it('should return the active user count for the role', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rows: [{ count: 4 }], rowCount: 1 });

      const count = await repo.countUsersUsingRole('role-uuid', 'company-uuid');
      expect(count).toBe(4);
      const [sql] = (mockPool.query as jest.Mock).mock.calls[0];
      expect(sql).toContain('deleted_at IS NULL');
    });

    it('should return 0 when no rows come back', async () => {
      (mockPool.query as jest.Mock).mockResolvedValue({ rows: [], rowCount: 0 });

      expect(await repo.countUsersUsingRole('role-uuid', 'company-uuid')).toBe(0);
    });
  });
});

import { Pool, PoolClient } from 'pg';
import { SalesOrderRepositoryPostgres } from '../SalesOrderRepositoryPostgres';
import { NotFoundError } from '../../../Commons/exceptions/NotFoundError';
import { InvariantError } from '../../../Commons/exceptions/InvariantError';
import { ConflictError } from '../../../Commons/exceptions/ConflictError';

const mockPool = { query: jest.fn(), connect: jest.fn() } as unknown as Pool;
const businessDate = new Date('2026-10-27T17:00:00.000Z');
const jakartaBusinessDate = '2026-10-28';

function header(over: Record<string, unknown> = {}) {
  return {
    id: 'so1',
    company_id: 'c1',
    outlet_id: 'out1',
    shift_id: 'sh1',
    invoice_number: 'INV-20261004-000001',
    customer_name: null,
    order_date: new Date('2026-10-04'),
    status: 'PENDING_PAYMENT',
    item_count: 1,
    subtotal: '15000.00',
    order_discount: '0.00',
    tax: '0.00',
    grand_total: '15000.00',
    cashier_user_id: 'u1',
    paid_at: null,
    created_at: new Date(),
    updated_at: new Date(),
    ...over,
  };
}

describe('SalesOrderRepositoryPostgres', () => {
  let repo: SalesOrderRepositoryPostgres;
  let client: { query: jest.Mock; release: jest.Mock };

  beforeEach(() => {
    // resetAllMocks (not clearAllMocks): several tests deliberately queue a
    // mockResolvedValueOnce that the resolver must NEVER consume (the ACTIVE
    // recipe an untopped line is forbidden to look for). clearAllMocks keeps
    // that once-queue alive, so the leftover value would silently feed the
    // next test's first query and cascade failures across the whole file.
    jest.resetAllMocks();
    repo = new SalesOrderRepositoryPostgres(mockPool);
    client = { query: jest.fn(), release: jest.fn() };
    (mockPool.connect as jest.Mock).mockResolvedValue(client as unknown as PoolClient);
  });

  // ── Mode resolution (§3.0) ──────────────────────────────────────────────
  // POS never auto-backflushes: EVERY line (topped or not) is served from the
  // sellable finished-goods stock at the outlet, or rejected. Toppings no
  // longer force MADE_TO_ORDER — they ride on top of whichever mode is used.
  describe('resolveCheckoutItems', () => {
    /** SQL of every pool.query call whose text contains `fragment`. */
    function sqls(fragment: string): string[] {
      return (mockPool.query as jest.Mock).mock.calls
        .filter((c) => typeof c[0] === 'string' && c[0].includes(fragment))
        .map((c) => c[0] as string);
    }

    /** Occurrences of `needle` inside `sql` (structural SQL assertions). */
    function count(sql: string, needle: string): number {
      return sql.split(needle).length - 1;
    }

    /** Untopped-line stock row: sellable + expired sums over the batches. */
    function stockRow(sellable: string, expired: string) {
      return { rows: [{ sellable_qty: sellable, expired_qty: expired }], rowCount: 1 };
    }

    const untopped = (productId: string, qty: number) => ({
      productId,
      qty,
      itemDiscount: 0,
      toppings: [],
    });

    describe('untopped lines — stock or reject, never MADE_TO_ORDER', () => {
      it('resolves STOCK when sellable stock covers qty', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce({
            rows: [{ id: 'p1', name: 'Waffle', selling_price: '8000.00' }],
            rowCount: 1,
          }) // product
          .mockResolvedValueOnce(stockRow('10', '0')); // sellable covers qty

        const { items } = await repo.resolveCheckoutItems('c1', 'o1', [untopped('p1', 2)]);

        expect(items[0].saleMode).toBe('STOCK');
        expect(items[0].recipeId).toBeNull();
        expect(items[0].unitPriceSnapshot).toBe(8000);
        expect(items[0].lineTotal).toBe(16000);
      });

      it('does not consult the recipe table at all for an untopped line', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce({
            rows: [{ id: 'p1', name: 'Waffle', selling_price: '8000.00' }],
            rowCount: 1,
          })
          .mockResolvedValueOnce(stockRow('10', '0'))
          // A recipe exists — but an untopped line must never reach for it.
          .mockResolvedValueOnce({ rows: [{ id: 'r1' }], rowCount: 1 });

        const { items } = await repo.resolveCheckoutItems('c1', 'o1', [untopped('p1', 2)]);

        expect(items[0].saleMode).toBe('STOCK');
        expect(sqls('FROM recipes')).toHaveLength(0);
        expect(mockPool.query).toHaveBeenCalledTimes(2);
      });

      it('guards BOTH stock sums with qty_available > 0 so drained expired batches are ignored', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce({
            rows: [{ id: 'p1', name: 'Waffle', selling_price: '8000.00' }],
            rowCount: 1,
          })
          .mockResolvedValueOnce(stockRow('10', '0'));

        await repo.resolveCheckoutItems('c1', 'o1', [untopped('p1', 2)], businessDate);

        const stockSql = sqls('FROM inventory_batches');
        expect(stockSql).toHaveLength(1);
        // One guard per FILTER: an expired batch with qty_available = 0 must
        // not be counted, otherwise expiredQty would explain nothing.
        expect(count(stockSql[0], 'qty_available > 0')).toBe(2);
        expect(count(stockSql[0], "status = 'ACTIVE'")).toBe(2);
        expect(stockSql[0]).toContain('expired_date >= $4::date');
        expect(stockSql[0]).toContain('expired_date < $4::date');
        expect(stockSql[0]).toContain('AS sellable_qty');
        expect(stockSql[0]).toContain('AS expired_qty');
        expect((mockPool.query as jest.Mock).mock.calls[1][1]).toEqual([
          'c1',
          'o1',
          'p1',
          jakartaBusinessDate,
        ]);
      });

      it('resolves STOCK for a FINISHED_GOODS line and snapshots the line total', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce({
            rows: [{ id: 'p2', name: 'Air Mineral', selling_price: '5000.00' }],
            rowCount: 1,
          })
          .mockResolvedValueOnce(stockRow('10', '3')); // 3 expired units are irrelevant

        const { items } = await repo.resolveCheckoutItems('c1', 'o1', [untopped('p2', 3)]);

        expect(items[0].saleMode).toBe('STOCK');
        expect(items[0].recipeId).toBeNull();
        expect(items[0].lineTotal).toBe(15000);
      });

      it('rejects SALES_ORDER.STOCK_EXPIRED when every batch on hand is expired', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce({
            rows: [{ id: 'p1', name: 'Waffle', selling_price: '8000.00' }],
            rowCount: 1,
          })
          .mockResolvedValueOnce(stockRow('0', '5')); // 0 sellable, 5 expired

        await expect(
          repo.resolveCheckoutItems('c1', 'o1', [untopped('p1', 2)]),
        ).rejects.toThrow('SALES_ORDER.STOCK_EXPIRED');
      });

      it('rejects SALES_ORDER.STOCK_EXPIRED when sellable stock is short and expired stock remains', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce({
            rows: [{ id: 'p1', name: 'Waffle', selling_price: '8000.00' }],
            rowCount: 1,
          })
          .mockResolvedValueOnce(stockRow('1', '4')); // qty 5 requested

        await expect(
          repo.resolveCheckoutItems('c1', 'o1', [untopped('p1', 5)]),
        ).rejects.toThrow('SALES_ORDER.STOCK_EXPIRED');
      });

      it('rejects SALES_ORDER.STOCK_EXPIRED as an InvariantError (HTTP 400)', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce({
            rows: [{ id: 'p1', name: 'Waffle', selling_price: '8000.00' }],
            rowCount: 1,
          })
          .mockResolvedValueOnce(stockRow('0', '5'));

        await expect(
          repo.resolveCheckoutItems('c1', 'o1', [untopped('p1', 2)]),
        ).rejects.toBeInstanceOf(InvariantError);
      });

      it('rejects INVENTORY.INSUFFICIENT_STOCK with no stock at all, even when an ACTIVE recipe exists', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce({
            rows: [{ id: 'p1', name: 'Waffle', selling_price: '8000.00' }],
            rowCount: 1,
          })
          .mockResolvedValueOnce(stockRow('0', '0'))
          // An ACTIVE recipe exists — POS must NOT backflush it into a sale.
          .mockResolvedValueOnce({ rows: [{ id: 'r1' }], rowCount: 1 });

        await expect(
          repo.resolveCheckoutItems('c1', 'o1', [untopped('p1', 2)]),
        ).rejects.toThrow('INVENTORY.INSUFFICIENT_STOCK');
        expect(sqls('FROM recipes')).toHaveLength(0);
      });

      it('rejects INVENTORY.INSUFFICIENT_STOCK when sellable stock is short and nothing is expired', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce({
            rows: [{ id: 'p1', name: 'Waffle', selling_price: '8000.00' }],
            rowCount: 1,
          })
          .mockResolvedValueOnce(stockRow('1', '0')) // qty 5 requested
          .mockResolvedValueOnce({ rows: [{ id: 'r1' }], rowCount: 1 }); // unused recipe

        await expect(
          repo.resolveCheckoutItems('c1', 'o1', [untopped('p1', 5)]),
        ).rejects.toThrow('INVENTORY.INSUFFICIENT_STOCK');
      });

      it('rejects INVENTORY.INSUFFICIENT_STOCK for a zero-priced product with no stock', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce({
            rows: [{ id: 'p3', name: 'Tepung', selling_price: '0.00' }],
            rowCount: 1,
          })
          .mockResolvedValueOnce(stockRow('0', '0'));

        await expect(
          repo.resolveCheckoutItems('c1', 'o1', [untopped('p3', 1)]),
        ).rejects.toThrow('INVENTORY.INSUFFICIENT_STOCK');
      });
    });

    describe('topped lines — stock-first, exactly like untopped ones', () => {
      // Topping-capable product row: the resolver reads name/price/flag only —
      // product_type is no longer part of the query.
      function toppingProduct(over: Record<string, unknown> = {}) {
        return {
          rows: [
            { id: 'p1', name: 'Waffle', selling_price: '8000.00', has_toppings: true, ...over },
          ],
          rowCount: 1,
        };
      }
      const topped = (productId: string, qty: number, toppingProductId = 't1') => ({
        productId,
        qty,
        itemDiscount: 0,
        toppings: [{ toppingProductId }],
      });
      /** Global catalog hit for topping t1 (25 g per item, +2000). */
      const catalogHit = {
        rows: [
          {
            topping_product_id: 't1',
            topping_name: 'Selai',
            default_qty_per_item: '25.000',
            extra_price: '2000.00',
          },
        ],
        rowCount: 1,
      };

      it('resolves STOCK when sellable stock covers a topped line (topping does NOT force MADE_TO_ORDER)', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce(toppingProduct()) // product
          .mockResolvedValueOnce(stockRow('10', '0')) // sellable covers qty
          .mockResolvedValueOnce(catalogHit); // topping in global catalog

        const { items } = await repo.resolveCheckoutItems('c1', 'o1', [topped('p1', 2)]);

        expect(items[0].saleMode).toBe('STOCK');
        // No recipe is snapshotted: the resolver has no recipe fallback.
        expect(items[0].recipeId).toBeNull();
        expect(items[0].toppings).toHaveLength(1);
        expect(items[0].toppings[0].toppingProductId).toBe('t1');
        // The stock query MUST run for a topped line — that is the whole fix.
        expect(sqls('FROM inventory_batches')).toHaveLength(1);
        expect(sqls('FROM recipes')).toHaveLength(0);
      });

      it('rejects INVENTORY.INSUFFICIENT_STOCK for a topped line with no stock (no recipe fallback)', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce(toppingProduct())
          .mockResolvedValueOnce(stockRow('0', '0'))
          // An ACTIVE recipe exists — POS must NOT backflush it into a sale.
          .mockResolvedValueOnce({ rows: [{ id: 'r1' }], rowCount: 1 });

        await expect(
          repo.resolveCheckoutItems('c1', 'o1', [topped('p1', 2)]),
        ).rejects.toThrow('INVENTORY.INSUFFICIENT_STOCK');
        expect(sqls('FROM recipes')).toHaveLength(0);
      });

      it('rejects SALES_ORDER.STOCK_EXPIRED for a topped line whose only stock is expired', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce(toppingProduct())
          .mockResolvedValueOnce(stockRow('0', '5'));

        await expect(
          repo.resolveCheckoutItems('c1', 'o1', [topped('p1', 1)]),
        ).rejects.toThrow('SALES_ORDER.STOCK_EXPIRED');
      });

      it('rejects TOPPING.NOT_ALLOWED when a STOCK product has has_toppings=false', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce(
            toppingProduct({ id: 'p2', name: 'Air Mineral', selling_price: '5000.00', has_toppings: false }),
          )
          .mockResolvedValueOnce(stockRow('10', '0')); // stock covers → mode STOCK

        await expect(
          repo.resolveCheckoutItems('c1', 'o1', [topped('p2', 1)]),
        ).rejects.toThrow('TOPPING.NOT_ALLOWED');
      });

      it('rejects TOPPING.NOT_ALLOWED when a topping is not in the active global catalog', async () => {
        (mockPool.query as jest.Mock)
          .mockResolvedValueOnce(toppingProduct())
          .mockResolvedValueOnce(stockRow('10', '0'))
          .mockResolvedValueOnce({ rows: [], rowCount: 0 }); // not in catalog

        await expect(
          repo.resolveCheckoutItems('c1', 'o1', [topped('p1', 1, 'tX')]),
