        'c1',
        'o1',
        jakartaBusinessDate,
      ]);
    });

    it('listActiveToppings defaults stock figures to 0 when the SUMs come back null', async () => {
      (mockPool.query as jest.Mock).mockResolvedValueOnce({
        rows: [
          {
            topping_product_id: 't1',
            topping_name: 'Selai',
            default_qty_per_item: '25.000',
            extra_price: '2000.00',
            sort_order: 0,
            available_qty: null,
            expired_qty: null,
          },
        ],
      });
      const toppings = await repo.listActiveToppings('c1', 'o1');
      expect(toppings[0].availableQty).toBe(0);
      expect(toppings[0].expiredQty).toBe(0);
    });

    it('listActiveToppings passes outletId = null when absent (safe degradation, no stock)', async () => {
      (mockPool.query as jest.Mock).mockResolvedValueOnce({
        rows: [
          {
            topping_product_id: 't1',
            topping_name: 'Selai',
            default_qty_per_item: '25.000',
            extra_price: '2000.00',
            sort_order: 0,
            available_qty: '0',
            expired_qty: '0',
          },
        ],
      });
      const toppings = await repo.listActiveToppings('c1', null, businessDate);
      expect(toppings[0].availableQty).toBe(0);
      expect(toppings[0].expiredQty).toBe(0);
      // No outlet → the stock param is NULL so both correlated SUMs collapse.
      expect((mockPool.query as jest.Mock).mock.calls[0][1]).toEqual([
        'c1',
        null,
        jakartaBusinessDate,
      ]);
    });

    it('listActiveToppings reuses the same batch filters/outlet param as the product grid', async () => {
      (mockPool.query as jest.Mock).mockResolvedValueOnce({ rows: [] });

      await repo.listActiveToppings('c1', 'o1', businessDate);

      const sql = (mockPool.query as jest.Mock).mock.calls[0][0] as string;
      // Same trap as the product grid: BOTH correlated sums need the
      // qty_available > 0 + ACTIVE guards, and both must point at the single
      // $2::uuid outlet placeholder.
      const guardCount = (needle: string) => sql.split(needle).length - 1;
      expect(guardCount('ib.qty_available > 0')).toBe(2);
      expect(guardCount("ib.status = 'ACTIVE'")).toBe(2);
      expect(sql).toContain('AS available_qty');
      expect(sql).toContain('AS expired_qty');
      expect(sql).toContain('ib.expired_date >= $3::date');
      expect(sql).toContain('ib.expired_date IS NOT NULL AND ib.expired_date < $3::date');
      const placeholders = sql.match(/\$\d+::uuid/g) as string[];
      expect(placeholders).toHaveLength(2);
      expect(placeholders[0]).toBe('$2::uuid');
      expect(placeholders[1]).toBe('$2::uuid');
    });

    it('listPosProducts returns 0 rows gracefully', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [{ count: '0' }] }) // count
        .mockResolvedValueOnce({ rows: [] }); // page
      const { rows, total } = await repo.listPosProducts('c1', { limit: 50, offset: 0 });
      expect(total).toBe(0);
      expect(rows).toEqual([]);
    });

    it('listPosProducts maps availableQty, expiredQty and STOCK/MTO modes', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [{ count: '2' }] }) // count
        .mockResolvedValueOnce({
          rows: [
            {
              id: 'p1',
              sku: 'SKU-WAFFLE-1',
              name: 'Waffle Original',
              product_type: 'FINISHED_GOODS',
              selling_price: '8000.00',
              has_toppings: true,
              recipe_id: 'r1',
              available_qty: '12',
              expired_qty: '4',
            },
            {
              id: 'p2',
              sku: 'SKU-TEA-1',
              name: 'Es Teh',
              product_type: 'FINISHED_GOODS',
              selling_price: '5000.00',
              has_toppings: false,
              recipe_id: null,
              available_qty: null,
              expired_qty: null,
            },
          ],
        }); // page
      const { rows, total } = await repo.listPosProducts('c1', {
        limit: 50,
        offset: 0,
        outletId: 'o1',
      });
      expect(total).toBe(2);
      expect(rows[0].saleMode).toBe('MADE_TO_ORDER');
      expect(rows[0].availableQty).toBe(12);
      expect(rows[0].expiredQty).toBe(4);
      expect(rows[1].saleMode).toBe('STOCK');
      expect(rows[1].availableQty).toBe(0);
      expect(rows[1].expiredQty).toBe(0);
    });

    it('listPosProducts guards expiredQty with qty_available > 0 so drained expired batches do not count', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [{ count: '1' }] }) // count
        .mockResolvedValueOnce({ rows: [] }); // page

      await repo.listPosProducts(
        'c1',
        { limit: 50, offset: 0, outletId: 'o1', search: 'waffle' },
        businessDate,
      );

      const sql = (mockPool.query as jest.Mock).mock.calls[1][0] as string;
      // The trap: an expired batch with qty_available = 0 must not inflate
      // expired_qty, so BOTH correlated sums need the qty_available > 0 guard.
      const guardCount = (needle: string) => sql.split(needle).length - 1;
      expect(guardCount('ib.qty_available > 0')).toBe(2);
      expect(guardCount("ib.status = 'ACTIVE'")).toBe(2);
      expect(sql).toContain('AS available_qty');
      expect(sql).toContain('AS expired_qty');
      expect(sql).toMatch(/ib\.expired_date >= \$\d+::date/);
      expect(sql).toMatch(/ib\.expired_date IS NOT NULL AND ib\.expired_date < \$\d+::date/);
      // Both subqueries must reuse the SAME dynamically-built outlet placeholder
      // (params.length + 1), never a hardcoded parameter number.
      const placeholders = sql.match(/\$\d+::uuid/g) as string[];
      expect(placeholders).toHaveLength(2);
      expect(placeholders[0]).toBe(placeholders[1]);
      const datePlaceholders = sql.match(/\$\d+::date/g) as string[];
      expect(datePlaceholders).toHaveLength(2);
      expect(datePlaceholders[0]).toBe(datePlaceholders[1]);
      const limitIndex = Number((sql.match(/LIMIT \$(\d+)/) as RegExpMatchArray)[1]);
      expect(placeholders[0]).toBe(`$${limitIndex + 2}::uuid`);
      expect(datePlaceholders[0]).toBe(`$${limitIndex + 3}::date`);
      expect((mockPool.query as jest.Mock).mock.calls[1][1]).toEqual([
        'c1',
        '%waffle%',
        50,
        0,
        'o1',
        jakartaBusinessDate,
      ]);
    });
  });

  // ── Refund (PAID -> REFUNDED, full-order) ────────────────────────────────
  describe('refund', () => {
    function orderItemRow(over: Record<string, unknown> = {}) {
      return {
        id: 'it1',
        product_id: 'p2',
        sale_mode: 'STOCK',
        recipe_id: null,
        product_name_snapshot: 'Air Mineral',
        unit_price_snapshot: '5000.00',
        qty: '3.000',
        item_discount: '0.00',
        toppings_price: '0.00',
        line_total: '15000.00',
        ...over,
      };
    }
    function returnHeaderRow(over: Record<string, unknown> = {}) {
      return {
        id: 'ret1',
        company_id: 'c1',
        outlet_id: 'out1',
        sales_order_id: 'so1',
        reason: null,
        refund_amount: '15000.00',
        status: 'COMPLETED',
        returned_by: 'u1',
        created_at: new Date(),
        updated_at: new Date(),
        ...over,
      };
    }

    it('returns consumed stock to the ORIGINAL batch via SALE_RETURN and flips to REFUNDED', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [header({ status: 'PAID', grand_total: '15000.00' })], rowCount: 1 }) // lock order (PAID)
        .mockResolvedValueOnce({ rows: [returnHeaderRow()], rowCount: 1 }) // insert sales_returns
        .mockResolvedValueOnce({ rows: [orderItemRow()], rowCount: 1 }) // load order items
        .mockResolvedValueOnce({ rows: [{ id: 'rit1' }], rowCount: 1 }) // insert sales_return_items
        .mockResolvedValueOnce({
          rows: [
            {
              id: 'sc1',
              sales_order_item_id: 'it1',
              product_id: 'p2',
              batch_id: 'b1',
              qty_consumed: '3.000',
            },
          ],
        }) // load consumptions
        .mockResolvedValueOnce({ rows: [{ qty_available: '0.000' }], rowCount: 1 }) // reload batch (was CONSUMED)
        .mockResolvedValueOnce({ rows: [], rowCount: 1 }) // update batch (reactivate)
        .mockResolvedValueOnce({ rows: [], rowCount: 1 }) // insert SALE_RETURN movement
        .mockResolvedValueOnce({ rows: [header({ status: 'REFUNDED' })], rowCount: 1 }) // update order
        .mockResolvedValueOnce({ rows: [{ id: 'rit1', sales_order_item_id: 'it1', qty_returned: '3.000', refund_line_amount: '15000.00' }] }) // _loadReturnItems
        .mockResolvedValueOnce({ rows: [] }) // _loadItems items
        .mockResolvedValueOnce({ rows: [] }) // _loadPayments
        .mockResolvedValueOnce(undefined); // COMMIT

      const { order, salesReturn } = await repo.refund('so1', 'c1', 'u1', null);

      expect(order.status).toBe('REFUNDED');
      expect(salesReturn.refundAmount).toBe(15000);
      expect(salesReturn.status).toBe('COMPLETED');

      // SALE_RETURN inbound movement posted to the original batch, qty 3.
      const movementCall = client.query.mock.calls.find(
        (c) => typeof c[0] === 'string' && c[0].includes("'SALE_RETURN'"),
      );
      expect(movementCall).toBeDefined();
      expect(movementCall![0]).toContain("'SALES_RETURN'");
      // before 0 + 3 = after 3 (batch_id b1, qty 3).
      expect(movementCall![1][2]).toBe('b1'); // batch_id
      expect(Number(movementCall![1][4])).toBeCloseTo(3); // qty
      expect(Number(movementCall![1][6])).toBeCloseTo(3); // after_qty

      // Batch update reactivates a CONSUMED batch when qty becomes > 0.
      const batchUpdate = client.query.mock.calls.find(
        (c) => typeof c[0] === 'string' && c[0].includes('UPDATE inventory_batches'),
      );
      expect(batchUpdate![0]).toContain("status = CASE WHEN status = 'CONSUMED'");
      expect(Number(batchUpdate![1][0])).toBeCloseTo(3);

      expect(client.query).toHaveBeenCalledWith('COMMIT');
    });

    it('rejects refunding an order that is not PAID (SALES_ORDER.NOT_PAID)', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [header({ status: 'PENDING_PAYMENT' })], rowCount: 1 }) // lock → not PAID
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.refund('so1', 'c1', 'u1', null)).rejects.toThrow('SALES_ORDER.NOT_PAID');
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });

    it('rejects double refund (SALES_ORDER.ALREADY_REFUNDED)', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [header({ status: 'REFUNDED' })], rowCount: 1 }) // lock → already REFUNDED
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.refund('so1', 'c1', 'u1', null)).rejects.toBeInstanceOf(ConflictError);
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });

    it('throws SALES_ORDER.NOT_FOUND when the order is missing', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // lock → none
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.refund('x', 'c1', 'u1', null)).rejects.toBeInstanceOf(NotFoundError);
    });

    it('maps a duplicate SALE_RETURN source key 23505 to INVENTORY.DUPLICATE_MOVEMENT_SOURCE', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [header({ status: 'PAID', grand_total: '15000.00' })], rowCount: 1 }) // lock
        .mockResolvedValueOnce({ rows: [returnHeaderRow()], rowCount: 1 }) // insert sales_returns
        .mockResolvedValueOnce({ rows: [orderItemRow()], rowCount: 1 }) // load order items
        .mockResolvedValueOnce({ rows: [{ id: 'rit1' }], rowCount: 1 }) // insert return item
        .mockResolvedValueOnce({
          rows: [
            { id: 'sc1', sales_order_item_id: 'it1', product_id: 'p2', batch_id: 'b1', qty_consumed: '3.000' },
          ],
        }) // consumptions
        .mockResolvedValueOnce({ rows: [{ qty_available: '0.000' }], rowCount: 1 }) // reload batch
        .mockResolvedValueOnce({ rows: [], rowCount: 1 }) // update batch
        .mockRejectedValueOnce({ code: '23505' }) // SALE_RETURN movement collides
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.refund('so1', 'c1', 'u1', null)).rejects.toThrow(
        'INVENTORY.DUPLICATE_MOVEMENT_SOURCE',
      );
    });

    it('getReturnByOrderId returns null when there is no refund', async () => {
      (mockPool.query as jest.Mock).mockResolvedValueOnce({ rows: [], rowCount: 0 });
      const result = await repo.getReturnByOrderId('so1', 'c1');
      expect(result).toBeNull();
    });

    it('getReturnByOrderId returns the latest refund with its items', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [returnHeaderRow()], rowCount: 1 }) // header
        .mockResolvedValueOnce({
          rows: [{ id: 'rit1', sales_order_item_id: 'it1', qty_returned: '3.000', refund_line_amount: '15000.00' }],
        }); // items
      const result = await repo.getReturnByOrderId('so1', 'c1');
      expect(result).not.toBeNull();
      expect(result!.refundAmount).toBe(15000);
      expect(result!.items).toHaveLength(1);
      expect(result!.items[0].qtyReturned).toBe(3);
    });
  });

  it('InvariantError is thrown via the right type for insufficient stock', () => {
    expect(new InvariantError('INVENTORY.INSUFFICIENT_STOCK')).toBeInstanceOf(InvariantError);
  });
});

import { Pool, PoolClient } from 'pg';
import pool from '../../database/pool';
import { DashboardRepositoryPostgres } from '../DashboardRepositoryPostgres';
import { ReportsRepositoryPostgres } from '../ReportsRepositoryPostgres';
import { SalesReport } from '../../../Domains/reports/entities/SalesReport';

const syntheticId = (n: number): string =>
  `00000000-0000-4000-8000-${String(n).padStart(12, '0')}`;
const companyId = syntheticId(1);
const otherCompanyId = syntheticId(2);
const outletId = syntheticId(3);
const otherOutletId = syntheticId(4);
const productId = syntheticId(5);
const otherProductId = syntheticId(6);
const productName = 'Synthetic Waffle Snapshot';
const berry = 'Synthetic Berry Snapshot';
const cocoa = 'Synthetic Cocoa Snapshot';
const businessDate = new Date('2026-10-25T03:00:00.000Z');
const dateFrom = '2026-10-19';
const dateTo = '2026-10-25';

type RepositoryKind = 'dashboard' | 'sales report';
interface FixtureItem {
  productId: string;
  productName: string;
  qty: number;
  lineTotal: number;
  toppings: string[];
}
interface FixtureOrder {
  items: FixtureItem[];
  companyId?: string;
  outletId?: string;
  status?: string;
  paidAt?: string | null;
  grandTotal?: number;
  itemCount?: number;
}

const waffle = (qty = 1, lineTotal = 100, toppings: string[] = []): FixtureItem => ({
  productId,
  productName,
  qty,
  lineTotal,
  toppings,
});
const variant = (toppingNames: string[], qtySold: number, revenue: number) => ({
  productId,
  productName,
  toppingNames,
  qtySold,
  revenue,
});

// SQL DATE may be local midnight; UTC conversion would shift its calendar day.
function calendarDate(value: string | Date): string {
  if (value instanceof Date) {
    return [
      value.getFullYear(),
      String(value.getMonth() + 1).padStart(2, '0'),
      String(value.getDate()).padStart(2, '0'),
    ].join('-');
  }
  return value;
}
function dailyRows(report: SalesReport) {
  return report.details.map((row) => ({ ...row, date: calendarDate(row.date) }));
}

describe('sales topping combinations (real PostgreSQL, TEMP tables only)', () => {
  let client: PoolClient | undefined;
  let dashboard: DashboardRepositoryPostgres;
  let reports: ReportsRepositoryPostgres;
  let savepointActive = false;
  let sequence = 100;
  let salesQueue: Promise<void> = Promise.resolve();

  function db(): PoolClient {
    if (!client) throw new Error('The isolated PostgreSQL client is not connected');
    return client;
  }

  // pg_temp-only search_path prevents fixtures from accessing public master data.
  function salesQuery(sql: string, params?: unknown[]) {
    if (!/^\s*SELECT\b/i.test(sql) || /\bpublic\s*\./i.test(sql)) {
      throw new Error('Only isolated sales SELECT queries are allowed');
    }
    // Serialize Promise.all queries without relying on pg's deprecated client queue.
    const result = salesQueue.then(() => db().query(sql, params));
    salesQueue = result.then(() => undefined, () => undefined);
    return result;
  }
  const reportQuery = jest.fn(salesQuery);

  beforeAll(async () => {
    if (process.env.NODE_ENV !== 'test') {
      throw new Error('This suite requires NODE_ENV=test and the existing test pool');
    }
    for (const key of ['PGHOST_TEST', 'PGUSER_TEST', 'PGDATABASE_TEST']) {
      if (!process.env[key]) throw new Error(`Missing required test environment: ${key}`);
    }
    if (!['localhost', '127.0.0.1', '::1'].includes(process.env.PGHOST_TEST!)) {
      throw new Error('This suite must use local PostgreSQL via PGHOST_TEST');
    }

    client = await pool.connect();
    await client.query('BEGIN');
    await client.query('SET LOCAL search_path TO pg_temp');
    await client.query(`
      CREATE TEMP TABLE sales_orders (
        id uuid PRIMARY KEY,
        company_id uuid NOT NULL,
        outlet_id uuid NOT NULL,
        status varchar NOT NULL,
        paid_at timestamp WITHOUT TIME ZONE,
        grand_total numeric(16, 2) NOT NULL,
        item_count integer NOT NULL
      ) ON COMMIT DROP;
      CREATE TEMP TABLE sales_order_items (
        id uuid PRIMARY KEY,
        sales_order_id uuid NOT NULL,
        product_id uuid NOT NULL,
        product_name_snapshot varchar NOT NULL,
        qty numeric(12, 3) NOT NULL,
        line_total numeric(16, 2) NOT NULL
      ) ON COMMIT DROP;
      CREATE TEMP TABLE sales_order_item_toppings (
        sales_order_item_id uuid NOT NULL,
        topping_name_snapshot varchar NOT NULL
      ) ON COMMIT DROP;
      CREATE TEMP TABLE outlets (
        id uuid PRIMARY KEY,
        name varchar NOT NULL
      ) ON COMMIT DROP;
    `);
    await client.query(
      'INSERT INTO pg_temp.outlets (id, name) VALUES ($1, $2), ($3, $4)',
      [outletId, 'Synthetic Outlet One', otherOutletId, 'Synthetic Outlet Two'],
    );

    dashboard = new DashboardRepositoryPostgres({
      query: (sql: string, params?: unknown[]) => {
        // Inventory is stubbed to keep all fixture tables confined to sales.
        if (/\bFROM inventory_batches\b/i.test(sql)) {
          return Promise.resolve({
            rows: sql.includes('COUNT(*) AS count') ? [{ count: '0' }] : [],
          });
        }
        return salesQuery(sql, params);
      },
    } as unknown as Pool);
    reports = new ReportsRepositoryPostgres({ query: reportQuery } as unknown as Pool);
  }, 20000);

  beforeEach(async () => {
    if (!client) return;
    await client.query('SAVEPOINT fixture');
    savepointActive = true;
    reportQuery.mockClear();
  });

  afterEach(async () => {
    if (!client || !savepointActive) return;
    try {
      // Drain even after a rejected Promise.all before rolling back fixtures.
      await salesQueue;
      await client.query('ROLLBACK TO SAVEPOINT fixture');
      await client.query('RELEASE SAVEPOINT fixture');
    } finally {
      savepointActive = false;
    }
  });

  afterAll(async () => {
    try {
      await salesQueue;
      if (client) await client.query('ROLLBACK');
    } finally {
      client?.release();
      await pool.end();
    }
  });

  async function addOrder(order: FixtureOrder): Promise<void> {
    const orderId = syntheticId(sequence++);
    await db().query(
      `INSERT INTO pg_temp.sales_orders
       (id, company_id, outlet_id, status, paid_at, grand_total, item_count)
       VALUES ($1, $2, $3, $4, $5, $6, $7)`,
      [
        orderId,
        order.companyId ?? companyId,
        order.outletId ?? outletId,
        order.status ?? 'PAID',
        order.paidAt === undefined ? '2026-10-25 03:00:00' : order.paidAt,
        order.grandTotal ?? order.items.reduce((sum, item) => sum + item.lineTotal, 0),
        order.itemCount ?? order.items.reduce((sum, item) => sum + item.qty, 0),
      ],
    );
    for (const item of order.items) {
      const itemId = syntheticId(sequence++);
      await db().query(
        `INSERT INTO pg_temp.sales_order_items
         (id, sales_order_id, product_id, product_name_snapshot, qty, line_total)
         VALUES ($1, $2, $3, $4, $5, $6)`,
        [itemId, orderId, item.productId, item.productName, item.qty, item.lineTotal],
      );
      for (const topping of item.toppings) {
        await db().query(
          `INSERT INTO pg_temp.sales_order_item_toppings
           (sales_order_item_id, topping_name_snapshot) VALUES ($1, $2)`,
          [itemId, topping],
        );
      }
    }
  }

  async function readVariants(
    kind: RepositoryKind,
    scope: { companyId?: string; outletId?: string } = {},
  ) {
    const scopedCompany = scope.companyId ?? companyId;
    if (kind === 'dashboard') {
      return (
        await dashboard.getOwnerSummary(
          scopedCompany,
          { outletId: scope.outletId },
          businessDate,
        )
      ).topProducts;
    }
    return (await reports.getSalesReport(scopedCompany, {
      dateFrom,
      dateTo,
      outletId: scope.outletId,
    })).topProducts;
  }

  it('resolves all fixture tables exclusively to this session TEMP schema', async () => {
    const result = await db().query(`
      SELECT relname, relpersistence, relnamespace = pg_my_temp_schema() AS isolated
      FROM pg_catalog.pg_class
      WHERE oid IN (
        'sales_orders'::regclass, 'sales_order_items'::regclass,
        'sales_order_item_toppings'::regclass, 'outlets'::regclass
      ) ORDER BY relname
    `);
    expect(result.rows).toEqual([
      'outlets', 'sales_order_item_toppings', 'sales_order_items', 'sales_orders',
    ].map((relname) => ({ relname, relpersistence: 't', isolated: true })));
  });

  describe.each<RepositoryKind>(['dashboard', 'sales report'])('%s', (kind) => {
    it('returns [] toppingNames and combines plain lines without losing quantity', async () => {
      await addOrder({ items: [waffle(2, 15000), waffle(3, 21000)] });
      expect(await readVariants(kind)).toEqual([variant([], 5, 36000)]);
    });

    it('returns one sold topping snapshot as a string array', async () => {
      await addOrder({ items: [waffle(2, 21000, [cocoa])] });
      expect(await readVariants(kind)).toEqual([variant([cocoa], 2, 21000)]);
    });

    it('groups reversed topping selection order into the same sorted variant across orders', async () => {
      await addOrder({ items: [waffle(2, 17000.25, [cocoa, berry])] });
      await addOrder({ items: [waffle(3, 24000.50, [berry, cocoa])] });
      expect(await readVariants(kind)).toEqual([variant([berry, cocoa], 5, 41000.75)]);
    });

    it('keeps plain, single-topping and distinct multi-topping combinations separate', async () => {
      await addOrder({ items: [
        waffle(1, 1000, [cocoa, berry]),
        waffle(2, 2000, [berry]),
        waffle(3, 3000, [cocoa]),
        waffle(4, 4000),
      ] });
      expect(await readVariants(kind)).toEqual([
        variant([], 4, 4000),
        variant([cocoa], 3, 3000),
        variant([berry], 2, 2000),
        variant([berry, cocoa], 1, 1000),
      ]);
    });

    it('does not double quantity or line revenue for an item with two toppings', async () => {
      await addOrder({ items: [waffle(3, 18750.25, [cocoa, berry])] });
      expect(await readVariants(kind)).toEqual([variant([berry, cocoa], 3, 18750.25)]);
    });

    it('preserves fractional quantities and discounted line totals, not order grand totals', async () => {
      await addOrder({
        items: [waffle(1.25, 9000.10, [cocoa]), waffle(2.5, 15000.20, [cocoa])],
        itemCount: 4,
        grandTotal: 99999,
      });
      expect(await readVariants(kind)).toEqual([variant([cocoa], 3.75, 24000.30)]);
    });

    it('groups by product ID and historical name as well as the topping combination', async () => {
      await addOrder({ items: [
        waffle(3, 300, [cocoa]),
        { ...waffle(2, 200, [cocoa]), productName: 'Synthetic Earlier Waffle Snapshot' },
        { ...waffle(1, 100, [cocoa]), productId: otherProductId },
      ] });
      expect(await readVariants(kind)).toEqual([
        variant([cocoa], 3, 300),
        { ...variant([cocoa], 2, 200), productName: 'Synthetic Earlier Waffle Snapshot' },
        { ...variant([cocoa], 1, 100), productId: otherProductId },
      ]);
    });

    it('excludes another company even when product/outlet snapshots match', async () => {
      await addOrder({ items: [waffle(2, 200, [cocoa])] });
      await addOrder({ companyId: otherCompanyId, items: [waffle(999, 99999, [cocoa])] });
      expect(await readVariants(kind)).toEqual([variant([cocoa], 2, 200)]);
      expect(await readVariants(kind, { companyId: otherCompanyId }))
        .toEqual([variant([cocoa], 999, 99999)]);
    });

    it('includes and combines both outlets for a company-wide request', async () => {
      await addOrder({ items: [waffle(2, 200, [cocoa])] });
      await addOrder({ outletId: otherOutletId, items: [waffle(3, 300, [cocoa])] });
      expect(await readVariants(kind)).toEqual([variant([cocoa], 5, 500)]);
    });

    it('filters the requested outlet without displacing date or limit parameters', async () => {
      await addOrder({ items: [waffle(2, 200, [cocoa])] });
      await addOrder({ outletId: otherOutletId, items: [waffle(999, 99999, [cocoa])] });
      expect(await readVariants(kind, { outletId })).toEqual([variant([cocoa], 2, 200)]);
      expect(await readVariants(kind, { outletId: otherOutletId }))
        .toEqual([variant([cocoa], 999, 99999)]);
    });

    it('defaults to PAID and excludes other statuses and missing paid_at', async () => {
      await addOrder({ items: [waffle(2, 200, [cocoa])] });
      for (const status of ['REFUNDED', 'CANCELLED', 'DRAFT']) {
        await addOrder({ status, items: [waffle(999, 99999, [cocoa])] });
      }
      await addOrder({ paidAt: null, items: [waffle(999, 99999, [cocoa])] });
      expect(await readVariants(kind)).toEqual([variant([cocoa], 2, 200)]);
    });

    it('includes both Jakarta date boundaries and excludes their adjacent UTC instants', async () => {
      await addOrder({ paidAt: '2026-10-18 16:59:59', items: [waffle(999, 99999)] });
      await addOrder({ paidAt: '2026-10-18 17:00:00', items: [waffle(2, 200)] });
      await addOrder({ paidAt: '2026-10-25 16:59:59', items: [waffle(3, 300)] });
      await addOrder({ paidAt: '2026-10-25 17:00:00', items: [waffle(999, 99999)] });
      expect(await readVariants(kind)).toEqual([variant([], 5, 500)]);
    });

    it('uses sold snapshots without any accessible current product or topping master tables', async () => {
      const masters = await db().query(`
        SELECT to_regclass('products')::text AS products,
               to_regclass('toppings')::text AS toppings
      `);
      expect(masters.rows).toEqual([{ products: null, toppings: null }]);
      await addOrder({ items: [waffle(2, 200, [cocoa, berry])] });
      expect(await readVariants(kind)).toEqual([variant([berry, cocoa], 2, 200)]);
    });

    it('returns an empty top-products list when no sales match', async () => {
      expect(await readVariants(kind)).toEqual([]);
    });

    it('orders equal quantities by snapshot name and sorted toppings, limiting variants to 10', async () => {
      const items: FixtureItem[] = [
        ...[[], [berry], [cocoa]].map((toppings) => ({
          ...waffle(1, 100, toppings), productName: 'A Synthetic Waffle',
        })),
        ...Array.from({ length: 9 }, (_, i) => ({
          ...waffle(1, 100, [`Synthetic Topping ${String(i + 1).padStart(2, '0')}`]),
          productName: 'B Synthetic Waffle',
        })),
      ];
      // Insertion order is deliberately the reverse of the expected result.
      await addOrder({ items: [...items].reverse() });
      const expected = items.slice(0, 10).map((item) => ({
        productId: item.productId,
        productName: item.productName,
        toppingNames: item.toppings,
        qtySold: 1,
        revenue: 100,
      }));
      expect(await readVariants(kind)).toEqual(expected);
      expect(await readVariants(kind)).toEqual(expected);
      const limited = kind === 'dashboard'
        ? (
            await dashboard.getOwnerSummary(
              companyId,
              { topProductsLimit: 5 },
              businessDate,
            )
          ).topProducts
        : (
            await reports.getSalesReport(companyId, {
              dateFrom,
              dateTo,
              topProductsLimit: 5,
            })
          ).topProducts;
      expect(limited).toEqual(expected.slice(0, 5));
      if (kind === 'sales report') {
        const report = await reports.getSalesReport(companyId, { dateFrom, dateTo });
        expect(report.summary).toEqual({
          totalOrders: 1, totalRevenue: 1200, averageOrderValue: 1200, totalItemsSold: 12,
        });
        expect(report.details[0].itemsSold).toBe(12);
      }
    });
  });

  describe('real sales summary and daily queries', () => {
    it('places UTC 17:xx on the next Jakarta business day consistently in all three report queries', async () => {
      await addOrder({ paidAt: '2026-10-24 16:59:59', items: [waffle(999, 99999)] });
      await addOrder({ paidAt: '2026-10-24 17:00:00', items: [waffle(2, 100, [cocoa])], grandTotal: 110 });
      await addOrder({ paidAt: '2026-10-24 17:35:00', items: [waffle(3, 200, [cocoa])], grandTotal: 220 });
      await addOrder({ paidAt: '2026-10-25 16:59:59', items: [waffle(4, 300, [cocoa])], grandTotal: 330 });
      await addOrder({ paidAt: '2026-10-25 17:00:00', items: [waffle(999, 99999)] });
      const report = await reports.getSalesReport(companyId, {
        dateFrom: dateTo, dateTo, outletId,
      });
      expect(reportQuery).toHaveBeenCalledTimes(3);
      expect(report.summary).toEqual({
        totalOrders: 3, totalRevenue: 660, averageOrderValue: 220, totalItemsSold: 9,
      });
      expect(dailyRows(report)).toEqual([{
        date: dateTo, outletId, outletName: 'Synthetic Outlet One',
        orderCount: 3, revenue: 660, itemsSold: 9,
      }]);
      expect(report.topProducts).toEqual([variant([cocoa], 9, 600)]);
      const owner = await dashboard.getOwnerSummary(
        companyId,
        { outletId },
        new Date('2026-10-24T17:35:00.000Z'),
      );
      expect(owner.salesToday).toBe(report.summary.totalOrders);
      expect(owner.revenueToday).toBe(report.summary.totalRevenue);
      expect(owner.salesTrend.map((row) => ({ ...row, date: calendarDate(row.date) })))
        .toContainEqual({ date: dateTo, revenue: 660, orderCount: 3 });
    });

    it.each(['REFUNDED', 'CANCELLED'])('honors explicit %s, company, outlet and dates in all sales queries', async (status) => {
      await addOrder({ status, paidAt: '2026-10-24 17:35:00', items: [waffle(2, 20, [cocoa, berry])], grandTotal: 25 });
      await addOrder({ status: 'PAID', items: [waffle(999, 99999)] });
      await addOrder({ status: status === 'REFUNDED' ? 'CANCELLED' : 'REFUNDED', items: [waffle(999, 99999)] });
      await addOrder({ status, companyId: otherCompanyId, items: [waffle(999, 99999)] });
      await addOrder({ status, outletId: otherOutletId, items: [waffle(999, 99999)] });
      await addOrder({ status, paidAt: '2026-10-24 16:59:59', items: [waffle(999, 99999)] });
      await addOrder({ status, paidAt: '2026-10-25 17:00:00', items: [waffle(999, 99999)] });
      const report = await reports.getSalesReport(companyId, {
        dateFrom: dateTo, dateTo, outletId, status,
      });
      expect(reportQuery).toHaveBeenCalledTimes(3);
      expect(report.summary).toEqual({
        totalOrders: 1, totalRevenue: 25, averageOrderValue: 25, totalItemsSold: 2,
      });
      expect(dailyRows(report)).toEqual([{
        date: dateTo, outletId, outletName: 'Synthetic Outlet One',
        orderCount: 1, revenue: 25, itemsSold: 2,
      }]);
      expect(report.topProducts).toEqual([variant([berry, cocoa], 2, 20)]);
    });

    it('groups and orders daily rows by Jakarta day and outlet over a multi-day range', async () => {
      await addOrder({ paidAt: '2026-10-23 17:15:00', items: [waffle(1, 100)], grandTotal: 110 });
      await addOrder({ paidAt: '2026-10-24 16:59:59', items: [waffle(2, 200)], grandTotal: 220 });
      await addOrder({ paidAt: '2026-10-24 17:45:00', outletId: otherOutletId, items: [waffle(3, 300)], grandTotal: 330 });
      const report = await reports.getSalesReport(companyId, {
        dateFrom: '2026-10-24', dateTo,
      });
      expect(reportQuery).toHaveBeenCalledTimes(3);
      expect(report.summary).toEqual({
        totalOrders: 3, totalRevenue: 660, averageOrderValue: 220, totalItemsSold: 6,
      });
      expect(dailyRows(report)).toEqual([
        { date: '2026-10-24', outletId, outletName: 'Synthetic Outlet One', orderCount: 2, revenue: 330, itemsSold: 3 },
        { date: dateTo, outletId: otherOutletId, outletName: 'Synthetic Outlet Two', orderCount: 1, revenue: 330, itemsSold: 3 },
      ]);
      expect(report.topProducts).toEqual([variant([], 6, 600)]);
    });

    it('returns zero summary aggregates and empty daily/top rows when filters exclude all sales', async () => {
      await addOrder({ companyId: otherCompanyId, items: [waffle(999, 99999)] });
      const report = await reports.getSalesReport(companyId, { dateFrom, dateTo, outletId });
      expect(reportQuery).toHaveBeenCalledTimes(3);
      expect(report.summary).toEqual({
        totalOrders: 0, totalRevenue: 0, averageOrderValue: 0, totalItemsSold: 0,
      });
      expect(report.details).toEqual([]);
      expect(report.topProducts).toEqual([]);
    });
  });
});

import { Pool, PoolClient } from 'pg';
import { ShiftRepositoryPostgres } from '../ShiftRepositoryPostgres';
import { NotFoundError } from '../../../Commons/exceptions/NotFoundError';
import { InvariantError } from '../../../Commons/exceptions/InvariantError';
import { ConflictError } from '../../../Commons/exceptions/ConflictError';

const mockPool = { query: jest.fn(), connect: jest.fn() } as unknown as Pool;

function header(over: Record<string, unknown> = {}) {
  return {
    id: 's1',
    company_id: 'c1',
    outlet_id: 'out1',
    cashier_user_id: 'u1',
    opened_at: new Date('2026-10-04T08:00:00Z'),
    closed_at: null,
    opening_cash: '500000.00',
    expected_cash: null,
    actual_cash: null,
    discrepancy: null,
    status: 'OPEN',
    notes: null,
    created_at: new Date(),
    updated_at: new Date(),
    ...over,
  };
}

describe('ShiftRepositoryPostgres', () => {
  let repo: ShiftRepositoryPostgres;
  let client: { query: jest.Mock; release: jest.Mock };

  beforeEach(() => {
    jest.clearAllMocks();
    repo = new ShiftRepositoryPostgres(mockPool);
    client = { query: jest.fn(), release: jest.fn() };
    (mockPool.connect as jest.Mock).mockResolvedValue(client as unknown as PoolClient);
  });

  describe('openShift', () => {
    it('should insert and return an OPEN shift (happy path)', async () => {
      (mockPool.query as jest.Mock).mockResolvedValueOnce({
        rows: [header({ status: 'OPEN' })],
        rowCount: 1,
      });

      const result = await repo.openShift('c1', 'u1', {
        outletId: 'out1',
        openingCash: 500000,
        notes: null,
      });

      expect(result.status).toBe('OPEN');
      expect(result.openingCash).toBe(500000);
      expect(result.expectedCash).toBeNull();
    });

    it('should translate a 23505 unique violation to SHIFT.ALREADY_OPEN', async () => {
      // Two attempts, each hitting the partial-unique-index violation.
      (mockPool.query as jest.Mock)
        .mockRejectedValueOnce({ code: '23505' })
        .mockRejectedValueOnce({ code: '23505' });

      await expect(
        repo.openShift('c1', 'u1', { outletId: 'out1', openingCash: 500000, notes: null }),
      ).rejects.toBeInstanceOf(ConflictError);
      await expect(
        repo.openShift('c1', 'u1', { outletId: 'out1', openingCash: 500000, notes: null }),
      ).rejects.toThrow('SHIFT.ALREADY_OPEN');
    });
  });

  describe('closeShift', () => {
    it('should close an OPEN shift and compute expected_cash + discrepancy (CASH payments)', async () => {
      // expected_cash = opening_cash + Σ(CASH payment) - Σ(CASH refund). Here
      // opening 500000 + 100000 CASH - 0 refund = 600000; actual 580000 →
      // discrepancy -20000.
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [header({ status: 'OPEN', opening_cash: '500000.00' })], rowCount: 1 }) // lock row
        .mockResolvedValueOnce({ rows: [{ cash_total: '100000.00' }], rowCount: 1 }) // CASH sum
        .mockResolvedValueOnce({ rows: [{ refund_total: '0' }], rowCount: 1 }) // CASH refund sum
        .mockResolvedValueOnce({
          rows: [
            header({
              status: 'CLOSED',
              closed_at: new Date(),
              expected_cash: '600000.00',
              actual_cash: '580000.00',
              discrepancy: '-20000.00',
            }),
          ],
          rowCount: 1,
        }) // update
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.closeShift('s1', 'c1', 'u1', { actualCash: 580000, notes: null });

      expect(result.status).toBe('CLOSED');
      expect(result.expectedCash).toBe(600000);
      expect(result.actualCash).toBe(580000);
      expect(result.discrepancy).toBe(-20000);
      // The CASH-sum query counts CASH payments on PAID or REFUNDED orders.
      const cashCall = client.query.mock.calls[2];
      expect(cashCall[0]).toContain("payment_method = 'CASH'");
      expect(cashCall[0]).toContain("status IN ('PAID','REFUNDED')");
      // The refund-sum query sums refund_amount from sales_returns.
      const refundCall = client.query.mock.calls[3];
      expect(refundCall[0]).toContain('sales_returns');
      expect(refundCall[0]).toContain('refund_amount');
      expect(client.query).toHaveBeenCalledWith('COMMIT');
    });

    it('expected_cash equals opening_cash when there are no CASH payments', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [header({ status: 'OPEN', opening_cash: '500000.00' })], rowCount: 1 }) // lock row
        .mockResolvedValueOnce({ rows: [{ cash_total: '0' }], rowCount: 1 }) // CASH sum (none)
        .mockResolvedValueOnce({ rows: [{ refund_total: '0' }], rowCount: 1 }) // CASH refund sum (none)
        .mockResolvedValueOnce({
          rows: [
            header({
              status: 'CLOSED',
              expected_cash: '500000.00',
              actual_cash: '500000.00',
              discrepancy: '0.00',
            }),
          ],
          rowCount: 1,
        }) // update
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.closeShift('s1', 'c1', 'u1', { actualCash: 500000, notes: null });
      expect(result.expectedCash).toBe(500000);
      expect(result.discrepancy).toBe(0);
    });

    it('subtracts CASH refunds from expected_cash (doc 51 §4.2 / OQ-8)', async () => {
      // opening 500000 + 150000 CASH payments - 50000 CASH refund = 600000.
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [header({ status: 'OPEN', opening_cash: '500000.00' })], rowCount: 1 }) // lock row
        .mockResolvedValueOnce({ rows: [{ cash_total: '150000.00' }], rowCount: 1 }) // CASH sum
        .mockResolvedValueOnce({ rows: [{ refund_total: '50000.00' }], rowCount: 1 }) // CASH refund sum
        .mockResolvedValueOnce({
          rows: [
            header({
              status: 'CLOSED',
              expected_cash: '600000.00',
              actual_cash: '600000.00',
              discrepancy: '0.00',
            }),
          ],
          rowCount: 1,
        }) // update
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.closeShift('s1', 'c1', 'u1', { actualCash: 600000, notes: null });
      // The UPDATE must have received expected_cash = 600000 (500000+150000-50000).
      const updateCall = client.query.mock.calls[4];
      expect(Number(updateCall[1][0])).toBeCloseTo(600000);
      expect(result.expectedCash).toBe(600000);
      expect(result.discrepancy).toBe(0);
    });

    it('should reject closing a shift that is already CLOSED', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [header({ status: 'CLOSED' })], rowCount: 1 }) // lock row
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(
        repo.closeShift('s1', 'c1', 'u1', { actualCash: 100, notes: null }),
      ).rejects.toThrow('SHIFT.ALREADY_CLOSED');
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });

    it('should throw NotFoundError when the shift is missing', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce({ rows: [], rowCount: 0 }) // lock row (none)
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(
        repo.closeShift('x', 'c1', 'u1', { actualCash: 100, notes: null }),
      ).rejects.toBeInstanceOf(NotFoundError);
    });
  });

  describe('getById', () => {
    it('should return the shift when found', async () => {
      (mockPool.query as jest.Mock).mockResolvedValueOnce({ rows: [header()], rowCount: 1 });
      const result = await repo.getById('s1', 'c1');
      expect(result.id).toBe('s1');
    });

    it('should throw NotFoundError when missing', async () => {
      (mockPool.query as jest.Mock).mockResolvedValueOnce({ rows: [], rowCount: 0 });
      await expect(repo.getById('x', 'c1')).rejects.toBeInstanceOf(NotFoundError);
    });
  });

  describe('list', () => {
    it('should return rows and total with filters applied', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [{ count: '2' }] }) // count
        .mockResolvedValueOnce({
          rows: [
            header({ outlet_name: 'Outlet Utama', cashier_name: 'Kasir Satu' }),
            header({ id: 's2', status: 'CLOSED' }),
          ],
          rowCount: 2,
        }); // page

      const { rows, total } = await repo.list('c1', {
        limit: 10,
        offset: 0,
        status: 'OPEN',
        outletId: 'out1',
        cashierUserId: 'u1',
      });

      expect(total).toBe(2);
      expect(rows).toHaveLength(2);
      expect(rows[0].outletName).toBe('Outlet Utama');
      expect(rows[0].cashierName).toBe('Kasir Satu');
      // first positional param is always companyId
      const countCall = (mockPool.query as jest.Mock).mock.calls[0];
      expect(countCall[1][0]).toBe('c1');
      const listQuery = (mockPool.query as jest.Mock).mock.calls[1][0] as string;
      expect(listQuery).toContain('AS outlet_name');
      expect(listQuery).toContain('AS cashier_name');
      expect(listQuery).toContain('u.company_id = shifts.company_id');
    });
  });

  it('closeShift InvariantError is thrown via InvariantError type', async () => {
    client.query
      .mockResolvedValueOnce(undefined)
      .mockResolvedValueOnce({ rows: [header({ status: 'CLOSED' })], rowCount: 1 })
      .mockResolvedValueOnce(undefined);
    await expect(
      repo.closeShift('s1', 'c1', 'u1', { actualCash: 1, notes: null }),
    ).rejects.toBeInstanceOf(InvariantError);
  });
});

import { Pool, PoolClient } from 'pg';
import { StockAdjustmentRepositoryPostgres } from '../StockAdjustmentRepositoryPostgres';
import { NotFoundError } from '../../../Commons/exceptions/NotFoundError';
import { InvariantError } from '../../../Commons/exceptions/InvariantError';

const mockPool = { query: jest.fn(), connect: jest.fn() } as unknown as Pool;

function header(over: Record<string, unknown> = {}) {
  return {
    id: 'adj-1',
    company_id: 'c1',
    outlet_id: 'o1',
    adjustment_number: 'ADJ-2026-000001',
    adjustment_date: new Date('2026-09-28'),
    status: 'APPROVED',
    notes: null,
    created_at: new Date(),
    updated_at: new Date(),
    ...over,
  };
}

function itemRow(over: Record<string, unknown> = {}) {
  return {
    id: 'item-1',
    batch_id: 'batch-1',
    product_id: 'prod-1',
    direction: 'OUT',
    qty: '3',
    reason: 'DAMAGED',
    reason_description: null,
    before_qty: null,
    after_qty: null,
    ...over,
  };
}

describe('StockAdjustmentRepositoryPostgres', () => {
  let repo: StockAdjustmentRepositoryPostgres;
  let client: { query: jest.Mock; release: jest.Mock };

  beforeEach(() => {
    jest.clearAllMocks();
    repo = new StockAdjustmentRepositoryPostgres(mockPool);
    client = { query: jest.fn(), release: jest.fn() };
    (mockPool.connect as jest.Mock).mockResolvedValue(client as unknown as PoolClient);
  });

  describe('getById', () => {
    it('should throw NotFoundError when header missing', async () => {
      (mockPool.query as jest.Mock).mockResolvedValueOnce({ rows: [], rowCount: 0 });
      await expect(repo.getById('x', 'c1')).rejects.toBeInstanceOf(NotFoundError);
    });

    it('should return adjustment with items', async () => {
      (mockPool.query as jest.Mock)
        .mockResolvedValueOnce({ rows: [header()], rowCount: 1 }) // header
        .mockResolvedValueOnce({ rows: [itemRow()], rowCount: 1 }); // items

      const adj = await repo.getById('adj-1', 'c1');
      expect(adj.id).toBe('adj-1');
      expect(adj.items).toHaveLength(1);
      expect(adj.items[0].direction).toBe('OUT');
    });
  });

  describe('complete', () => {
    it('should post OUT movement, snapshot before/after, and flip to COMPLETED', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [header({ status: 'APPROVED' })], rowCount: 1 }) // lock header
        .mockResolvedValueOnce({ rows: [itemRow({ qty: '3' })], rowCount: 1 }) // load items
        .mockResolvedValueOnce({ rows: [{ qty_available: '10' }], rowCount: 1 }) // lock batch
        .mockResolvedValueOnce({ rowCount: 1 }) // update batch
        .mockResolvedValueOnce({ rowCount: 1 }) // insert movement
        .mockResolvedValueOnce({ rowCount: 1 }) // update item snapshot
        .mockResolvedValueOnce({ rows: [header({ status: 'COMPLETED' })], rowCount: 1 }) // flip header
        .mockResolvedValueOnce({ rows: [itemRow({ before_qty: '10', after_qty: '7' })], rowCount: 1 }) // final items
        .mockResolvedValueOnce(undefined); // COMMIT

      const result = await repo.complete('adj-1', 'c1', 'user-1');

      expect(result.status).toBe('COMPLETED');
      expect(client.query).toHaveBeenCalledWith('COMMIT');
      expect(client.release).toHaveBeenCalled();
    });

    it('should reject completion when status is not APPROVED', async () => {
      client.query
        .mockResolvedValueOnce(undefined) // BEGIN
        .mockResolvedValueOnce(undefined) // SET ISOLATION
        .mockResolvedValueOnce({ rows: [header({ status: 'DRAFT' })], rowCount: 1 }) // lock header
        .mockResolvedValueOnce(undefined); // ROLLBACK

      await expect(repo.complete('adj-1', 'c1', 'user-1')).rejects.toThrow(
        'STOCK_ADJUSTMENT.INVALID_STATUS_TRANSITION',
      );
      expect(client.query).toHaveBeenCalledWith('ROLLBACK');
    });

