import * as os from 'os';
import * as path from 'path';
import { LocalPurchaseReturnAttachmentStorage } from '../LocalPurchaseReturnAttachmentStorage';
import { NotFoundError } from '../../../Commons/exceptions/NotFoundError';

describe('LocalPurchaseReturnAttachmentStorage', () => {
  let root: string;
  let storage: LocalPurchaseReturnAttachmentStorage;

  beforeEach(async () => {
    root = await fsp.mkdtemp(path.join(os.tmpdir(), 'pr-att-'));
    storage = new LocalPurchaseReturnAttachmentStorage(root);
  });

  afterEach(async () => {
    await fsp.rm(root, { recursive: true, force: true });
  });

  it('saves a file under uploads/purchase-returns/<year>/ with a safe derived name', async () => {
    const { storedPath } = await storage.save(
      'RTN-2026-000001',
      'return-note.pdf',
      'application/pdf',
      Buffer.from('%PDF data'),
    );

    const year = String(new Date().getFullYear());
    expect(storedPath.startsWith(`uploads/purchase-returns/${year}/`)).toBe(true);
    // derived name keeps the return number prefix and pdf extension, not the raw name
    expect(storedPath.endsWith('.pdf')).toBe(true);
    expect(storedPath).toContain('RTN-2026-000001');
    // and the bytes are actually on disk
    const absolute = storage.resolveAbsolutePath(storedPath);
    await expect(fsp.readFile(absolute, 'utf8')).resolves.toBe('%PDF data');
  });

  it('never uses the raw original name for the path (path traversal defense)', async () => {
    const { storedPath } = await storage.save(
      '../../etc/passwd',
      '../../evil.png',
      'image/png',
      Buffer.from('PNG'),
    );
    // The stored path stays inside uploads/purchase-returns and has no ".."
    expect(storedPath).not.toContain('..');
    expect(storedPath.startsWith('uploads/purchase-returns/')).toBe(true);
    // resolveAbsolutePath keeps it inside the root
    const absolute = storage.resolveAbsolutePath(storedPath);
    expect(absolute.startsWith(path.resolve(root, 'uploads'))).toBe(true);
  });

  it('resolveAbsolutePath rejects a path escaping the storage root', () => {
    expect(() => storage.resolveAbsolutePath('uploads/../../../etc/passwd')).toThrow(
      NotFoundError,
    );
  });

  it('remove deletes the file and is idempotent for a missing file', async () => {
    const { storedPath } = await storage.save(
      'RTN-1',
      'x.png',
      'image/png',
      Buffer.from('PNG'),
    );
    const absolute = storage.resolveAbsolutePath(storedPath);
    await storage.remove(storedPath);
    await expect(fsp.access(absolute)).rejects.toBeDefined();
    // second remove does not throw
    await expect(storage.remove(storedPath)).resolves.toBeUndefined();
  });

  it('remove silently ignores paths outside the root', async () => {
    await expect(storage.remove('uploads/../../../etc/passwd')).resolves.toBeUndefined();
  });

  it('createReadStream streams the stored bytes', async () => {
    const { storedPath } = await storage.save(
      'RTN-1',
      'x.pdf',
      'application/pdf',
      Buffer.from('hello'),
    );
    const stream = storage.createReadStream(storedPath);
    const chunks: Buffer[] = [];
    await new Promise<void>((resolve, reject) => {
      stream.on('data', (c) => chunks.push(Buffer.from(c)));
      stream.on('end', () => resolve());
      stream.on('error', reject);
    });
    expect(Buffer.concat(chunks).toString('utf8')).toBe('hello');
  });
});

import { ReportExportService } from '../report-export.service';
import { SalesReport, SalesReportTopProduct } from '../../../../../Domains/reports/entities/SalesReport';

const variant: SalesReportTopProduct = {
  productId: 'waffle-id',
  productName: 'Waffle Original',
  toppingNames: ['Cokelat', 'Keju'],
  uomCode: 'PCS',
  uomName: 'Pcs',
  qtySold: 6,
  revenue: 120000,
};

function exportRows(rows: SalesReportTopProduct[]): string {
  return new ReportExportService().exportSalesToCsv(
    new SalesReport({
      summary: {
        totalOrders: 2,
        totalRevenue: 120000,
        averageOrderValue: 60000,
        totalItemsSold: 6,
      },
      details: [],
      topProducts: rows,
    }),
  );
}

describe('ReportExportService sales topping combinations', () => {
  it('exports each combination with topping, quantity and whole-item revenue', () => {
    const csv = exportRows([variant]);
    expect(csv).toContain('Product,Topping,Qty Sold,UOM,Revenue');
    expect(csv).toContain('"Waffle Original","Cokelat + Keju",6,PCS,120000');
    expect(csv).toContain('Total Revenue,120000');
  });

  it('labels items with no topping and keeps separate variants of the same waffle', () => {
    const csv = exportRows([variant, { ...variant, toppingNames: [], qtySold: 4 }]);
    expect(csv).toContain('"Waffle Original","Tanpa topping",4,PCS,120000');
    expect(csv.match(/"Waffle Original"/g)).toHaveLength(2);
  });

  it('quotes commas and doubles quotes in product and topping names', () => {
    const csv = exportRows([
      { ...variant, productName: 'Waffle "Premium", Besar', toppingNames: ['Selai "Berry", Manis'] },
    ]);
    expect(csv).toContain('"Waffle ""Premium"", Besar","Selai ""Berry"", Manis",6,PCS,120000');
  });

  it.each(['=1+1', '+1+1', '-1+1', '@SUM(1)', '\t=1+1', '\r=1+1', '\n=1+1'])(
    'neutralizes spreadsheet formula names %j',
    (name) => {
      const csv = exportRows([{ ...variant, productName: name, toppingNames: [name] }]);
      expect(csv).toContain(`"'${name}","'${name}",6,PCS,120000`);
    },
  );

  it('still exports summary and headers with no sales', () => {
    const csv = exportRows([]);
    expect(csv).toContain('Product,Topping,Qty Sold,UOM,Revenue');
    expect(csv).not.toContain('"Waffle Original"');
  });
});

import { plainToInstance } from 'class-transformer';
import { validate } from 'class-validator';
import { OwnerDashboardQueryDto } from '../../dashboard/dto/owner-dashboard-query.dto';
import { SalesReportQueryDto } from '../dto/sales-report-query.dto';

function transform<T extends object>(type: new () => T, payload: object): T {
  return plainToInstance(type, payload, { enableImplicitConversion: true });
}

describe('top-products query DTOs', () => {
  it('accepts and converts supported owner dashboard options', async () => {
    const dto = transform(OwnerDashboardQueryDto, {
      periodDays: '30',
      topProductsLimit: '20',
    });

    expect(await validate(dto)).toEqual([]);
    expect(dto).toMatchObject({ periodDays: 30, topProductsLimit: 20 });
  });

  it.each([
    { periodDays: '8' },
    { topProductsLimit: '100' },
  ])('rejects unsupported owner dashboard options: %o', async (payload) => {
    const errors = await validate(transform(OwnerDashboardQueryDto, payload));
    expect(errors).toHaveLength(1);
  });

  it('accepts and converts a supported sales report limit', async () => {
    const dto = transform(SalesReportQueryDto, {
      dateFrom: '2026-10-01',
      dateTo: '2026-10-28',
      topProductsLimit: '50',
    });

    expect(await validate(dto)).toEqual([]);
    expect(dto.topProductsLimit).toBe(50);
  });

  it('rejects an unsupported sales report limit', async () => {
    const dto = transform(SalesReportQueryDto, {
      dateFrom: '2026-10-01',
      dateTo: '2026-10-28',
      topProductsLimit: '7',
    });

    const errors = await validate(dto);
    expect(errors.map((error) => error.property)).toEqual(['topProductsLimit']);
  });
});

import { SalesOrderController } from '../sales-order.controller';

describe('SalesOrderController.list', () => {
  const getUseCase = { list: jest.fn().mockResolvedValue({ rows: [], total: 0 }) };
  const controller = new SalesOrderController(
    {} as never,
    {} as never,
    {} as never,
    {} as never,
    getUseCase as never,
  );

  beforeEach(() => jest.clearAllMocks());

  it('limits non-owner users to their own sales orders', async () => {
    await controller.list(
      { limit: '10' },
      { companyId: 'company-1', sub: 'cashier-1', roleCode: 'KASIR' } as never,
    );

    expect(getUseCase.list).toHaveBeenCalledWith(
      expect.objectContaining({ cashierUserId: 'cashier-1' }),
      'company-1',
    );
  });

  it('does not restrict owners to one cashier', async () => {
    await controller.list(
      { limit: '10' },
      { companyId: 'company-1', sub: 'owner-1', roleCode: 'OWNER' } as never,
    );

    expect(getUseCase.list).toHaveBeenCalledWith(
      expect.not.objectContaining({ cashierUserId: expect.anything() }),
      'company-1',
    );
  });
});

import { ShiftController } from '../shift.controller';

describe('ShiftController.list', () => {
  const getShiftsUseCase = { list: jest.fn().mockResolvedValue({ rows: [], total: 0 }) };
  const controller = new ShiftController({} as never, {} as never, getShiftsUseCase as never);

  beforeEach(() => jest.clearAllMocks());

  it('forces non-owner users to their own shifts, ignoring a requested cashier filter', async () => {
    await controller.list(
      { limit: '10', cashierUserId: 'another-user' },
      { companyId: 'company-1', sub: 'cashier-1', roleCode: 'KASIR' } as never,
    );

    expect(getShiftsUseCase.list).toHaveBeenCalledWith(
      expect.objectContaining({ cashierUserId: 'cashier-1' }),
      'company-1',
    );
  });

  it('allows owners to use the requested cashier filter', async () => {
    await controller.list(
      { limit: '10', cashierUserId: 'cashier-2' },
      { companyId: 'company-1', sub: 'owner-1', roleCode: 'OWNER' } as never,
    );

    expect(getShiftsUseCase.list).toHaveBeenCalledWith(
      expect.objectContaining({ cashierUserId: 'cashier-2' }),
      'company-1',
    );
  });
});
